"""
DREAMCHAMBER Integrations / LAN Discover

Real LAN enumeration — no fabricated IPs. Uses `arp -an` to read the host's
ARP cache (populated by recent ICMP/normal traffic) and optionally seeds it
with a quick ICMP ping sweep across the host's actual subnet.

Returns a list of {ip, mac, iface, hostname?} for machines genuinely present.

Author: Built by Claude for Robert Stephen Plowman / NOIZY.AI
"""
from __future__ import annotations
import ipaddress
import re
import socket
import subprocess
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, asdict
from typing import List, Optional


_ARP_LINE = re.compile(
    r"\? \(([\d.]+)\) at ([0-9a-fA-F:]+) on (\S+)"
)


@dataclass
class LANHost:
    ip: str
    mac: str
    iface: str
    hostname: Optional[str] = None


def _host_subnet() -> Optional[ipaddress.IPv4Network]:
    """Return the /24 the host's primary interface is on."""
    try:
        # Trick: socket to public IP, never sent — reveals the local IP route.
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 53))
        local_ip = s.getsockname()[0]
        s.close()
        return ipaddress.IPv4Network(f"{local_ip}/24", strict=False)
    except OSError:
        return None


def _ping(ip: str, timeout_ms: int = 200) -> bool:
    try:
        r = subprocess.run(
            ["ping", "-c", "1", "-W", str(timeout_ms), ip],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            timeout=(timeout_ms / 1000.0) + 0.5,
        )
        return r.returncode == 0
    except Exception:
        return False


def _ping_sweep(subnet: ipaddress.IPv4Network, max_workers: int = 64) -> None:
    """Seed the ARP cache by pinging every host in the /24 in parallel."""
    targets = [str(h) for h in subnet.hosts()]
    with ThreadPoolExecutor(max_workers=max_workers) as ex:
        list(ex.map(_ping, targets))


def _read_arp() -> List[LANHost]:
    try:
        out = subprocess.run(
            ["arp", "-an"], capture_output=True, text=True, timeout=3
        ).stdout
    except Exception:
        return []
    hosts: List[LANHost] = []
    for line in out.splitlines():
        m = _ARP_LINE.search(line)
        if not m:
            continue
        ip, mac, iface = m.groups()
        if mac in ("(incomplete)", "ff:ff:ff:ff:ff:ff"):
            continue
        hosts.append(LANHost(ip=ip, mac=mac.lower(), iface=iface))
    return hosts


def _resolve_hostname(ip: str) -> Optional[str]:
    try:
        return socket.gethostbyaddr(ip)[0]
    except (socket.herror, socket.gaierror, OSError):
        return None


def lan_discover(sweep: bool = True, resolve_hostnames: bool = True) -> dict:
    """
    Discover live machines on the host's actual LAN.

    Args:
        sweep: if True, ping the entire /24 first to seed the ARP cache.
        resolve_hostnames: if True, attempt reverse DNS for each result.

    Returns:
        {
          "subnet": "192.168.x.0/24" | None,
          "host_count": int,
          "hosts": [{ip, mac, iface, hostname?}, ...],
          "note": str,
        }
    """
    subnet = _host_subnet()
    if subnet is None:
        return {
            "subnet": None,
            "host_count": 0,
            "hosts": [],
            "note": "Could not determine host subnet — no default route?",
        }

    if sweep:
        _ping_sweep(subnet)

    hosts = _read_arp()
    # Filter to this subnet only
    hosts = [h for h in hosts if ipaddress.IPv4Address(h.ip) in subnet]

    if resolve_hostnames:
        for h in hosts:
            h.hostname = _resolve_hostname(h.ip)

    hosts.sort(key=lambda h: ipaddress.IPv4Address(h.ip))

    return {
        "subnet": str(subnet),
        "host_count": len(hosts),
        "hosts": [asdict(h) for h in hosts],
        "note": (
            f"ARP cache on subnet {subnet}"
            + (" (post-sweep)" if sweep else " (no sweep)")
        ),
    }

