"""
DREAMCHAMBER Orchestrator — FastAPI brain
The runtime that wires Memory + Tools + Integrations + ModelRouter + Glossary
into a single HTTP + WebSocket service.

Receipt-aware. Local-first. Sovereign. Free-forever.

Author: Built by Claude for Robert Stephen Plowman / NOIZY.AI
"""
from __future__ import annotations
import asyncio
import os
from contextlib import asynccontextmanager
from datetime import datetime, timezone
from typing import Any, Optional

from fastapi import FastAPI, HTTPException, WebSocket, WebSocketDisconnect
from pydantic import BaseModel

from Memory.store import MemoryStore
from Memory.semantic import SemanticMemory
from Core.event_bus import bus as event_bus
from Core.health import HealthRegistry, ServiceHealth
from Tools.registry import ToolRegistry
from Tools.summary import summarize as _summarize
from Tools.action_items import extract_action_items as _extract_actions
from Tools.intent import detect_intent as _detect_intent
from ModelRouter.router import ModelRouter, TaskClass
from Integrations.calendar import CalDAVAdapter
from Integrations.email import EmailAdapter
from Integrations.files import FilesAdapter
from Integrations.notes import NotesAdapter
from Integrations.voice import PiperVoice
from Integrations.consent import ConsentGate
from Integrations.consent_oracle import ConsentOracleBridge
from Integrations.mesh import probe_mesh, NOIZY_MESH
from Integrations.audio import audio_status as _audio_status
from Integrations.studio_probe import studio_probe as _studio_probe
from Integrations.demucs import (demucs_status as _demucs_status,
                                  demucs_separate as _demucs_separate)
from Integrations.lan_discover import lan_discover as _lan_discover
from Glossary.omegat_bridge import OmegaTBridge


# ─── lifespan: build singletons ─────────────────────────────────────
@asynccontextmanager
async def lifespan(app: FastAPI):
    app.state.store = MemoryStore()
    app.state.semantic = SemanticMemory()  # FAISS layer
    app.state.bus = event_bus  # asyncio pub/sub
    app.state.health = HealthRegistry()
    app.state.router = ModelRouter()
    app.state.tools = ToolRegistry(store=app.state.store)
    app.state.calendar = CalDAVAdapter()
    app.state.email = EmailAdapter()
    app.state.files = FilesAdapter()
    app.state.notes = NotesAdapter()
    app.state.voice = PiperVoice()
    app.state.consent = ConsentGate()
    app.state.oracle = ConsentOracleBridge()
    app.state.glossary = OmegaTBridge(store=app.state.store)
    _register_tools(app.state.tools, app.state)
    yield
    await app.state.router.aclose()


app = FastAPI(title="DREAMCHAMBER", version="0.1.0", lifespan=lifespan)

# Mount the Fish Music sovereign dashboard as static files
from fastapi.staticfiles import StaticFiles
from pathlib import Path as _PathDash
_DASH = _PathDash(__file__).parent / "Dashboard"
if _DASH.exists():
    app.mount("/dashboard", StaticFiles(directory=str(_DASH), html=True),
              name="dashboard")


# ─── tool registration ──────────────────────────────────────────────
def _register_tools(reg: ToolRegistry, state):
    @reg.register("memory.add_client", description="Persist a client record")
    def add_client(name: str, notes: str = "") -> dict:
        return {"id": state.store.add_client(name, notes)}

    @reg.register("memory.add_term", description="Add glossary term")
    def add_term(term: str, translations: dict, category: str = "",
                 priority: int = 5) -> dict:
        return {"id": state.store.add_term(
            term=term, translations=translations,
            category=category, priority=priority)}

    @reg.register("memory.search_terms", description="Search glossary")
    def search_terms(query: str, limit: int = 20) -> list[dict]:
        return state.store.search_terms(query, limit)

    @reg.register("calendar.list_upcoming",
                  description="List upcoming calendar events")
    def cal_upcoming(days: int = 7) -> list[dict]:
        evts = state.calendar.list_upcoming(days=days)
        return [{"title": e.title, "starts_at": e.starts_at.isoformat(),
                 "ends_at": e.ends_at.isoformat()} for e in evts]

    @reg.register("email.draft", description="Draft an email (does not send)",
                  safety="preview_required")
    def email_draft(to: list, subject: str, body: str) -> dict:
        msg = state.email.draft(to=to, subject=subject, body=body)
        return {"preview": msg.as_string()[:2000]}

    @reg.register("files.search", description="Search trusted file roots")
    def files_search(pattern: str, max_results: int = 50) -> list[dict]:
        return [{"path": str(h.path), "size": h.size}
                for h in state.files.search(pattern, max_results)]

    @reg.register("notes.create", description="Create a markdown note")
    def notes_create(title: str, body: str = "",
                     tags: Optional[list] = None) -> dict:
        return {"path": str(state.notes.create(title, body, tags))}


    @reg.register("model.complete", description="Send a prompt to the model router")
    async def model_complete(prompt: str, task: str = "quick",
                             system: Optional[str] = None) -> dict:
        out = await state.router.complete(
            TaskClass(task), prompt, system=system)
        return {"text": out}

    @reg.register("memory.semantic_add",
                  description="Add text to FAISS semantic memory")
    def semantic_add(text: str, meta: Optional[dict] = None) -> dict:
        idx = state.semantic.add(text, meta or {})
        return {"id": idx, "size": state.semantic.size()}

    @reg.register("memory.semantic_search",
                  description="Vector search FAISS semantic memory")
    def semantic_search(query: str, k: int = 5) -> list[dict]:
        return state.semantic.search(query, k=k)

    @reg.register("events.publish",
                  description="Publish an event to the asyncio bus")
    async def events_publish(event: str, data: Optional[dict] = None) -> dict:
        await state.bus.publish(event, data or {})
        return {"event": event, "delivered": True}

    @reg.register("events.recent",
                  description="Recent events on the bus")
    def events_recent(event: Optional[str] = None, limit: int = 50) -> list[dict]:
        return state.bus.history(event=event, limit=limit)

    @reg.register("text.summarize",
                  description="Heuristic summarizer (no LLM needed)")
    def text_summarize(text: str, max_sentences: int = 3) -> dict:
        r = _summarize(text, max_sentences=max_sentences)
        return {"summary": r.summary, "highlights": r.highlights,
                "word_count": r.word_count}

    @reg.register("text.action_items",
                  description="Fail-closed action item extraction")
    def text_action_items(text: str) -> dict:
        r = _extract_actions(text)
        return {"items": [{"text": i.text, "owner": i.owner,
                           "confidence": i.confidence} for i in r.items],
                "source_sentences": r.source_sentences}

    @reg.register("text.intent", description="Detect intent of a user utterance")
    def text_intent(text: str) -> dict:
        r = _detect_intent(text)
        return {"intent": r.intent, "confidence": r.confidence,
                "reason": r.reason}

    @reg.register("text.analyze",
                  description="LLM-powered combined summary + action items + intent")
    async def text_analyze(text: str) -> dict:
        # Heuristic first (always free, instant)
        summary = _summarize(text, max_sentences=3)
        actions = _extract_actions(text)
        intent = _detect_intent(text)
        result = {
            "heuristic": {
                "summary": summary.summary,
                "highlights": summary.highlights,
                "action_items": [{"text": i.text, "owner": i.owner,
                                  "confidence": i.confidence}
                                 for i in actions.items],
                "intent": intent.intent,
            }
        }
        # LLM augmentation if available (best-effort, non-blocking on failure)
        try:
            llm = await state.router.complete(
                TaskClass.REASONING,
                prompt=(f"Given this text, output JSON with keys "
                        f"'summary' (1-2 sentences) and "
                        f"'next_steps' (list of concrete next actions). "
                        f"Text:\n{text}"),
                system="You are a precise extraction assistant. Output JSON only.",
                temperature=0.2)
            result["llm"] = {"raw": llm}
        except Exception as e:
            result["llm"] = {"error": str(e)}
        return result

    @reg.register("glossary.import_omegat",
                  description="Import an OmegaT .txt glossary into memory")
    def glossary_import(path: str, target_lang: str = "en",
                        category: str = "imported") -> dict:
        from pathlib import Path
        n = state.glossary.import_to_store(
            Path(path), target_lang=target_lang, category=category)
        return {"imported": n, "path": path}

    @reg.register("glossary.export_omegat",
                  description="Export DREAMCHAMBER terms to OmegaT .txt file")
    def glossary_export(path: str, target_lang: str = "en") -> dict:
        from pathlib import Path
        n = state.glossary.export_from_store(
            Path(path), target_lang=target_lang)
        return {"exported": n, "path": path}

    # ─── Multi-agent prompted analysis ───────────────────────────
    from pathlib import Path as _Path
    _PROMPTS_DIR = _Path(__file__).parent / "Prompts"
    _DC_CORE_PROMPT = (_PROMPTS_DIR / "dreamchamber_core.md").read_text()
    _REELTIME_PROMPT = (_PROMPTS_DIR / "reeltime_assist.md").read_text()
    _AUTONOMOUS_PROMPT = (_PROMPTS_DIR / "autonomous.md").read_text()

    @reg.register("text.dreamchamber_analyze",
                  description="DREAMCHAMBER CORE multi-agent analysis "
                              "(Interpreter+Executor+Strategist) via reasoning model")
    async def dc_analyze(text: str) -> dict:
        out = await state.router.complete(
            TaskClass.REASONING, prompt=text,
            system=_DC_CORE_PROMPT, temperature=0.3)
        # Auto-ingest into memory (this is what the system would do)
        state.semantic.add(text, meta={"source": "dc_analyze"})
        return {"analysis": out, "ingested": True,
                "semantic_size": state.semantic.size()}

    @reg.register("text.reeltime_assist",
                  description="REELTIME ASSIST fast voice-style interpretation")
    async def reeltime_assist(text: str) -> dict:
        out = await state.router.complete(
            TaskClass.QUICK, prompt=text,
            system=_REELTIME_PROMPT, temperature=0.4)
        return {"response": out}

    @reg.register("voice.speak",
                  description="Sovereign local TTS via Piper — accessibility-first",
                  safety="informational")
    def voice_speak(text: str, play: bool = True) -> dict:
        try:
            if play:
                r = state.voice.speak(text)
            else:
                r = state.voice.speak_to_file(text)
            return {"audio_path": str(r.audio_path),
                    "voice": r.voice,
                    "duration_estimate_s": r.duration_estimate_s,
                    "played": play}
        except Exception as e:
            return {"error": str(e),
                    "hint": "Install piper-tts + download a voice model"}

    @reg.register("consent.request",
                  description="Open a consent request for a guarded action")
    def consent_request(cmd: str, safety: str, args: dict,
                        actor: str = "system", rationale: str = "") -> dict:
        req = state.consent.request(cmd=cmd, safety=safety, args=args,
                                    actor=actor, rationale=rationale)
        return {"id": req.id, "status": req.status, "cmd": req.cmd,
                "safety": req.safety,
                "policy": state.consent.policy_for(safety)}

    @reg.register("consent.decide",
                  description="Grant or deny a pending consent request")
    def consent_decide(request_id: str, decision: str,
                       decided_by: str = "user") -> dict:
        ok = state.consent.decide(request_id, decision, decided_by)
        return {"updated": ok, "id": request_id, "decision": decision}

    @reg.register("consent.pending",
                  description="List pending consent requests")
    def consent_pending(limit: int = 50) -> list[dict]:
        return state.consent.pending(limit=limit)

    @reg.register("text.autonomous",
                  description="DREAMCHAMBER AUTONOMOUS continuous-loop analysis")
    async def text_autonomous(text: str) -> dict:
        out = await state.router.complete(
            TaskClass.REASONING, prompt=text,
            system=_AUTONOMOUS_PROMPT, temperature=0.3)
        state.semantic.add(text, meta={"source": "autonomous"})
        return {"analysis": out, "ingested": True,
                "semantic_size": state.semantic.size()}

    # ─── consent-oracle D1 bridge (Fish Music canonical) ───────
    @reg.register("oracle.can_i_do",
                  description="Canonical consent check against consent-oracle D1 "
                              "(voice_id + use_case → allowed + royalty_rate)")
    async def oracle_can_i_do(voice_id: str, use_case: str,
                               grantee: str = "system") -> dict:
        v = await state.oracle.can_i_do(voice_id, use_case, grantee)
        return {"allowed": v.allowed, "voice_id": v.voice_id,
                "use_case": v.use_case, "grantor": v.grantor,
                "royalty_rate": v.royalty_rate,
                "grant_id": v.grant_id, "reason": v.reason}

    @reg.register("oracle.voice_registry",
                  description="List voices in the consent-oracle registry")
    async def oracle_voice_registry(owner: Optional[str] = None) -> list[dict]:
        return await state.oracle.voice_registry(owner=owner)

    @reg.register("oracle.audit_trail",
                  description="Recent consent decisions from the audit log")
    async def oracle_audit_trail(voice_id: Optional[str] = None,
                                  limit: int = 50) -> list[dict]:
        return await state.oracle.audit_trail(voice_id=voice_id, limit=limit)

    @reg.register("mesh.status",
                  description="Live reachability probe across the NOIZY mesh "
                              "(Tailscale + mDNS + LAN). Returns per-host status.")
    async def mesh_status() -> list[dict]:
        statuses = await probe_mesh()
        return [{
            "name": s.name, "role": s.role,
            "reachable": s.reachable, "via": s.via,
            "address": s.address, "ssh_alive": s.ssh_alive,
            "latency_ms": s.latency_ms, "notes": s.notes,
        } for s in statuses]

    @reg.register("mesh.nodes",
                  description="Static list of known NOIZY mesh nodes + their addresses")
    def mesh_nodes() -> list[dict]:
        return [{
            "name": n.name, "role": n.role,
            "tailscale": n.tailscale, "mdns": n.mdns,
            "lan_ip": n.lan_ip, "ssh_port": n.ssh_port,
        } for n in NOIZY_MESH]

    @reg.register("audio.status",
                  description="BlackHole + CoreAudio device probe — STEP 2 verification")
    def audio_status_tool() -> dict:
        s = _audio_status()
        return {
            "blackhole_installed": s.blackhole_installed,
            "blackhole_channels": s.blackhole_channels,
            "blackhole_driver_path": s.blackhole_driver_path,
            "hal_drivers": s.hal_drivers,
            "devices": s.devices,
            "note": s.note,
        }

    @reg.register("studio.probe",
                  description="Studio Stack migration scorecard — what's installed, "
                              "what's paid (drop), what's free-not-yet-installed")
    def studio_probe_tool() -> dict:
        return _studio_probe()

    @reg.register("audio.demucs_status",
                  description="Check Demucs availability + cached model list")
    def demucs_status_tool() -> dict:
        return _demucs_status()

    @reg.register("audio.demucs_separate",
                  description="Separate audio stems via Demucs "
                              "(vocals/drums/bass/other)",
                  safety="external_write")
    def demucs_separate_tool(input_path: str,
                             output_dir: Optional[str] = None,
                             two_stems: bool = False,
                             model: str = "htdemucs") -> dict:
        r = _demucs_separate(input_path, output_dir=output_dir,
                             two_stems=two_stems, model=model)
        return {
            "input_path": str(r.input_path),
            "stems_dir": str(r.stems_dir),
            "stems": [str(s) for s in r.stems],
            "model": r.model,
            "duration_ms": r.duration_ms,
        }

    # Health probes
    state.health.register(
        "memory.sqlite",
        lambda: ServiceHealth("memory.sqlite", "ok"))
    state.health.register(
        "memory.faiss",
        lambda: ServiceHealth("memory.faiss", "ok",
                              metrics={"size": state.semantic.size()}))


# ─── HTTP routes ────────────────────────────────────────────────────
@app.get("/health")
async def health():
    backends = await app.state.router.health()
    return {
        "status": "ok",
        "ts": datetime.now(timezone.utc).isoformat(),
        "backends": backends,
        "tool_count": len(app.state.tools.list_tools()),
        "db": str(app.state.store.db_path),
    }


@app.get("/tools")
async def list_tools():
    return app.state.tools.list_tools()


class InvokeRequest(BaseModel):
    tool: str
    args: dict[str, Any] = {}


@app.post("/invoke")
async def invoke(req: InvokeRequest):
    receipt = await app.state.tools.invoke(req.tool, **req.args)
    if receipt["status"] == "failed":
        raise HTTPException(status_code=400, detail=receipt)
    return receipt


@app.get("/receipts/failures")
async def failure_summary():
    return app.state.store.failure_summary_by_target()


@app.get("/signals")
async def signals():
    """NOIZY signal stream — non-success receipts surfaced as structured
    feedback, not 'errors'. Grouped by target system per NOIZYWORLD doctrine.
    'There are no meaningless errors — only meaningful signals.'"""
    grouped = app.state.store.failure_summary_by_target()
    return {
        "philosophy": "Every signal carries information for the loop",
        "stream": [
            {
                "target": target,
                "signal_count": len(items),
                "signals": [
                    {
                        "id": r["id"],
                        "ts": r["ts"],
                        "cmd": r["cmd"],
                        "code": r.get("error_code") or "feedback",
                        "message": r.get("error_message") or "",
                        "duration_ms": r.get("duration_ms", 0),
                    }
                    for r in items
                ],
            }
            for target, items in grouped.items()
        ],
    }


@app.get("/health/snapshot")
async def health_snapshot():
    """Multi-service aggregated health for dashboard / WS heartbeat."""
    return app.state.health.snapshot()


# ─── WebSocket: real-time event stream ───────────────────────────────
@app.websocket("/ws/events")
async def ws_events(websocket: WebSocket):
    """Subscribe to live events from the bus. IPad/OSC dashboards connect here."""
    await websocket.accept()
    queue: asyncio.Queue = asyncio.Queue(maxsize=100)

    async def relay(data):
        try:
            queue.put_nowait({"data": data})
        except asyncio.QueueFull:
            pass  # drop if client is slow

    # Subscribe to common event channels
    for ev in ("reeltime.partial", "reeltime.final",
               "dreamchamber.ingested", "dreamchamber.system"):
        app.state.bus.subscribe(ev, relay)

    # Send health snapshot immediately on connect
    try:
        snap = app.state.health.snapshot()
        await websocket.send_json({"event": "dreamchamber.connected",
                                   "health": snap})
        # Heartbeat + relay loop
        while True:
            try:
                msg = await asyncio.wait_for(queue.get(), timeout=10.0)
                await websocket.send_json(msg)
            except asyncio.TimeoutError:
                await websocket.send_json({"event": "heartbeat",
                                           "ts": datetime.now(timezone.utc).isoformat()})
    except WebSocketDisconnect:
        pass


if __name__ == "__main__":
    import uvicorn
    port = int(os.environ.get("DC_PORT", "7777"))
    uvicorn.run("orchestrator:app", host="127.0.0.1", port=port, reload=False)

