# ─── tool registration ──────────────────────────────────────────────
def _register_tools(reg: ToolRegistry, state):
    @reg.register("memory.add_client", description="Persist a client record")
    def add_client(name: str, notes: str = "") -> dict:
        return {"id": state.store.add_client(name, notes)}

    @reg.register("memory.add_term", description="Add glossary term")
    def add_term(term: str, translations: dict, category: str = "",
                 priority: int = 5) -> dict:
        return {"id": state.store.add_term(
            term=term, translations=translations,
            category=category, priority=priority)}

    @reg.register("memory.search_terms", description="Search glossary")
    def search_terms(query: str, limit: int = 20) -> list[dict]:
        return state.store.search_terms(query, limit)

    @reg.register("calendar.list_upcoming",
                  description="List upcoming calendar events")
    def cal_upcoming(days: int = 7) -> list[dict]:
        evts = state.calendar.list_upcoming(days=days)
        return [{"title": e.title, "starts_at": e.starts_at.isoformat(),
                 "ends_at": e.ends_at.isoformat()} for e in evts]

    @reg.register("email.draft", description="Draft an email (does not send)",
                  safety="preview_required")
    def email_draft(to: list, subject: str, body: str) -> dict:
        msg = state.email.draft(to=to, subject=subject, body=body)
        return {"preview": msg.as_string()[:2000]}

    @reg.register("files.search", description="Search trusted file roots")
    def files_search(pattern: str, max_results: int = 50) -> list[dict]:
        return [{"path": str(h.path), "size": h.size}
                for h in state.files.search(pattern, max_results)]

    @reg.register("notes.create", description="Create a markdown note")
    def notes_create(title: str, body: str = "",
                     tags: Optional[list] = None) -> dict:
        return {"path": str(state.notes.create(title, body, tags))}


    @reg.register("model.complete", description="Send a prompt to the model router")
    async def model_complete(prompt: str, task: str = "quick",
                             system: Optional[str] = None) -> dict:
        out = await state.router.complete(
            TaskClass(task), prompt, system=system)
        return {"text": out}

    @reg.register("memory.semantic_add",
                  description="Add text to FAISS semantic memory")
    def semantic_add(text: str, meta: Optional[dict] = None) -> dict:
        idx = state.semantic.add(text, meta or {})
        return {"id": idx, "size": state.semantic.size()}

    @reg.register("memory.semantic_search",
                  description="Vector search FAISS semantic memory")
    def semantic_search(query: str, k: int = 5) -> list[dict]:
        return state.semantic.search(query, k=k)

    @reg.register("events.publish",
                  description="Publish an event to the asyncio bus")
    async def events_publish(event: str, data: Optional[dict] = None) -> dict:
        await state.bus.publish(event, data or {})
        return {"event": event, "delivered": True}

    @reg.register("events.recent",
                  description="Recent events on the bus")
    def events_recent(event: Optional[str] = None, limit: int = 50) -> list[dict]:
        return state.bus.history(event=event, limit=limit)

    @reg.register("text.summarize",
                  description="Heuristic summarizer (no LLM needed)")
    def text_summarize(text: str, max_sentences: int = 3) -> dict:
        r = _summarize(text, max_sentences=max_sentences)
        return {"summary": r.summary, "highlights": r.highlights,
                "word_count": r.word_count}

    @reg.register("text.action_items",
                  description="Fail-closed action item extraction")
    def text_action_items(text: str) -> dict:
        r = _extract_actions(text)
        return {"items": [{"text": i.text, "owner": i.owner,
                           "confidence": i.confidence} for i in r.items],
                "source_sentences": r.source_sentences}

    @reg.register("text.intent", description="Detect intent of a user utterance")
    def text_intent(text: str) -> dict:
        r = _detect_intent(text)
        return {"intent": r.intent, "confidence": r.confidence,
                "reason": r.reason}

    @reg.register("text.analyze",
                  description="LLM-powered combined summary + action items + intent")
    async def text_analyze(text: str) -> dict:
        # Heuristic first (always free, instant)
        summary = _summarize(text, max_sentences=3)
        actions = _extract_actions(text)
        intent = _detect_intent(text)
        result = {
            "heuristic": {
                "summary": summary.summary,
                "highlights": summary.highlights,
                "action_items": [{"text": i.text, "owner": i.owner,
                                  "confidence": i.confidence}
                                 for i in actions.items],
                "intent": intent.intent,
            }
        }
        # LLM augmentation if available (best-effort, non-blocking on failure)
        try:
            llm = await state.router.complete(
                TaskClass.REASONING,
                prompt=(f"Given this text, output JSON with keys "
                        f"'summary' (1-2 sentences) and "
                        f"'next_steps' (list of concrete next actions). "
                        f"Text:\n{text}"),
                system="You are a precise extraction assistant. Output JSON only.",
                temperature=0.2)
            result["llm"] = {"raw": llm}
        except Exception as e:
            result["llm"] = {"error": str(e)}
        return result

    @reg.register("glossary.import_omegat",
                  description="Import an OmegaT .txt glossary into memory")
    def glossary_import(path: str, target_lang: str = "en",
                        category: str = "imported") -> dict:
        from pathlib import Path
        n = state.glossary.import_to_store(
            Path(path), target_lang=target_lang, category=category)
        return {"imported": n, "path": path}

    @reg.register("glossary.export_omegat",
                  description="Export DREAMCHAMBER terms to OmegaT .txt file")
    def glossary_export(path: str, target_lang: str = "en") -> dict:
        from pathlib import Path
