        return {"exported": n, "path": path}

    # ─── Multi-agent prompted analysis ───────────────────────────
    from pathlib import Path as _Path
    _PROMPTS_DIR = _Path(__file__).parent / "Prompts"
    _DC_CORE_PROMPT = (_PROMPTS_DIR / "dreamchamber_core.md").read_text()
    _REELTIME_PROMPT = (_PROMPTS_DIR / "reeltime_assist.md").read_text()
    _AUTONOMOUS_PROMPT = (_PROMPTS_DIR / "autonomous.md").read_text()

    @reg.register("text.dreamchamber_analyze",
                  description="DREAMCHAMBER CORE multi-agent analysis "
                              "(Interpreter+Executor+Strategist) via reasoning model")
    async def dc_analyze(text: str) -> dict:
        out = await state.router.complete(
            TaskClass.REASONING, prompt=text,
            system=_DC_CORE_PROMPT, temperature=0.3)
        # Auto-ingest into memory (this is what the system would do)
        state.semantic.add(text, meta={"source": "dc_analyze"})
        return {"analysis": out, "ingested": True,
                "semantic_size": state.semantic.size()}

    @reg.register("text.reeltime_assist",
                  description="REELTIME ASSIST fast voice-style interpretation")
    async def reeltime_assist(text: str) -> dict:
        out = await state.router.complete(
            TaskClass.QUICK, prompt=text,
            system=_REELTIME_PROMPT, temperature=0.4)
        return {"response": out}

    @reg.register("voice.speak",
                  description="Sovereign local TTS via Piper — accessibility-first",
                  safety="informational")
    def voice_speak(text: str, play: bool = True) -> dict:
        try:
            if play:
                r = state.voice.speak(text)
            else:
                r = state.voice.speak_to_file(text)
            return {"audio_path": str(r.audio_path),
