                    "played": play}
        except Exception as e:
            return {"error": str(e),
                    "hint": "Install piper-tts + download a voice model"}

    @reg.register("consent.request",
                  description="Open a consent request for a guarded action")
    def consent_request(cmd: str, safety: str, args: dict,
                        actor: str = "system", rationale: str = "") -> dict:
        req = state.consent.request(cmd=cmd, safety=safety, args=args,
                                    actor=actor, rationale=rationale)
        return {"id": req.id, "status": req.status, "cmd": req.cmd,
                "safety": req.safety,
                "policy": state.consent.policy_for(safety)}

    @reg.register("consent.decide",
                  description="Grant or deny a pending consent request")
    def consent_decide(request_id: str, decision: str,
                       decided_by: str = "user") -> dict:
        ok = state.consent.decide(request_id, decision, decided_by)
        return {"updated": ok, "id": request_id, "decision": decision}

    @reg.register("consent.pending",
                  description="List pending consent requests")
    def consent_pending(limit: int = 50) -> list[dict]:
        return state.consent.pending(limit=limit)

    @reg.register("text.autonomous",
                  description="DREAMCHAMBER AUTONOMOUS continuous-loop analysis")
    async def text_autonomous(text: str) -> dict:
        out = await state.router.complete(
            TaskClass.REASONING, prompt=text,
            system=_AUTONOMOUS_PROMPT, temperature=0.3)
        state.semantic.add(text, meta={"source": "autonomous"})
        return {"analysis": out, "ingested": True,
