    @reg.register("oracle.voice_registry",
                  description="List voices in the consent-oracle registry")
    async def oracle_voice_registry(owner: Optional[str] = None) -> list[dict]:
        return await state.oracle.voice_registry(owner=owner)

    @reg.register("oracle.audit_trail",
                  description="Recent consent decisions from the audit log")
    async def oracle_audit_trail(voice_id: Optional[str] = None,
                                  limit: int = 50) -> list[dict]:
        return await state.oracle.audit_trail(voice_id=voice_id, limit=limit)

    @reg.register("mesh.status",
                  description="Live reachability probe across the NOIZY mesh "
                              "(Tailscale + mDNS + LAN). Returns per-host status.")
