# ─── WebSocket: real-time event stream ───────────────────────────────
@app.websocket("/ws/events")
async def ws_events(websocket: WebSocket):
    """Subscribe to live events from the bus. IPad/OSC dashboards connect here."""
    await websocket.accept()
    queue: asyncio.Queue = asyncio.Queue(maxsize=100)

    async def relay(data):
        try:
            queue.put_nowait({"data": data})
        except asyncio.QueueFull:
            pass  # drop if client is slow

    # Subscribe to common event channels
    for ev in ("reeltime.partial", "reeltime.final",
               "dreamchamber.ingested", "dreamchamber.system"):
        app.state.bus.subscribe(ev, relay)

    # Send health snapshot immediately on connect
    try:
        snap = app.state.health.snapshot()
        await websocket.send_json({"event": "dreamchamber.connected",
                                   "health": snap})
        # Heartbeat + relay loop
        while True:
            try:
                msg = await asyncio.wait_for(queue.get(), timeout=10.0)
                await websocket.send_json(msg)
            except asyncio.TimeoutError:
                await websocket.send_json({"event": "heartbeat",
                                           "ts": datetime.now(timezone.utc).isoformat()})
    except WebSocketDisconnect:
        pass


