/**
 * CONSENT GATEWAY — NOIZYBEAST v0.1
 *
 * Nothing creator-linked moves without passing through this worker.
 * Every request returns: ALLOW | HOLD | DENY | ESCALATE
 *
 * Deploy: npx wrangler deploy
 * Health: GET /health
 * Check:  POST /v1/check-eligibility
 * Revoke: POST /v1/revoke
 * Query:  GET /v1/consent/:id
 * Audit:  GET /v1/audit/:asset_id
 */

import { checkEligibility, type EligibilityRequest, type EligibilityResponse } from './policy';

export interface Env {
  DB: D1Database;
  NOIZY_API_KEY: string;
  ENVIRONMENT: string;
}

// --- Auth ---

function authenticate(request: Request, env: Env): boolean {
  const key = request.headers.get('X-NOIZY-Key');
  return key === env.NOIZY_API_KEY;
}

function unauthorized(): Response {
  return Response.json(
    { success: false, error: 'Unauthorized', timestamp: new Date().toISOString() },
    { status: 401 }
  );
}

function notFound(): Response {
  return Response.json(
    { success: false, error: 'Not found', timestamp: new Date().toISOString() },
    { status: 404 }
  );
}

// --- Audit Logging ---

async function logAudit(
  env: Env,
  actorType: string,
  actorId: string,
  action: string,
  objectType: string,
  objectId: string,
  decision?: string,
  reason?: string,
  metadata?: Record<string, unknown>
): Promise<void> {
  const id = crypto.randomUUID();
  const now = new Date().toISOString();
  try {
    await env.DB.prepare(`
      INSERT INTO audit_log (id, actor_type, actor_id, action, object_type, object_id, decision, reason, metadata_json, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      id, actorType, actorId, action, objectType, objectId,
      decision || null, reason || null,
      metadata ? JSON.stringify(metadata) : null, now
    ).run();
  } catch (e) {
    console.error('Audit log write failed:', e);
  }
}

// --- Router ---

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const method = request.method;

    // CORS
    if (method === 'OPTIONS') {
      return new Response(null, {
        headers: {
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
          'Access-Control-Allow-Headers': 'Content-Type, X-NOIZY-Key',
        },
      });
    }

    // Health (no auth)
    if (method === 'GET' && url.pathname === '/health') {
      return Response.json({
        success: true,
        service: 'consent-gateway',
        version: '0.1.0',
        timestamp: new Date().toISOString(),
      });
    }

    // All other routes require auth
    if (!authenticate(request, env)) {
      return unauthorized();
    }

    try {
      // POST /v1/check-eligibility
      if (method === 'POST' && url.pathname === '/v1/check-eligibility') {
        const body = (await request.json()) as EligibilityRequest;
        const result = await checkEligibility(body, env);

        await logAudit(
          env, 'claimant', body.claimant_id, 'check-eligibility',
          'consent', result.consent_record_id || 'none',
          result.decision, result.reason_codes.join(','),
          { tool_name: body.tool_name, action_type: body.action_type }
        );

        return Response.json({
          success: true,
          data: result,
          timestamp: new Date().toISOString(),
        });
      }

      // POST /v1/revoke
      if (method === 'POST' && url.pathname === '/v1/revoke') {
        const body = (await request.json()) as {
          consent_record_id: string;
          creator_id: string;
          reason: string;
          scope?: Record<string, string>;
        };

        const id = crypto.randomUUID();
        const now = new Date().toISOString();

        // Create revocation event
        await env.DB.prepare(`
          INSERT INTO revocation_events (id, consent_record_id, creator_id, reason, scope_json, effective_at, enforcement_status, created_at)
          VALUES (?, ?, ?, ?, ?, ?, 'enforced', ?)
        `).bind(
          id, body.consent_record_id, body.creator_id,
          body.reason, JSON.stringify(body.scope || {}), now, now
        ).run();

        // Update consent record
        await env.DB.prepare(`
          UPDATE consent_records SET consent_status = 'revoked', revoked_at = ?, updated_at = ?
          WHERE id = ? AND creator_id = ?
        `).bind(now, now, body.consent_record_id, body.creator_id).run();

        await logAudit(
          env, 'creator', body.creator_id, 'revoke',
          'consent', body.consent_record_id, 'REVOKED', body.reason
        );

        return Response.json({
          success: true,
          data: {
            revocation_id: id,
            consent_record_id: body.consent_record_id,
            effective_at: now,
            enforcement_status: 'enforced',
          },
          timestamp: now,
        });
      }

      // GET /v1/consent/:id
      if (method === 'GET' && url.pathname.startsWith('/v1/consent/')) {
        const consentId = url.pathname.split('/v1/consent/')[1];
        const consent = await env.DB.prepare(`
          SELECT * FROM consent_records WHERE id = ?
        `).bind(consentId).first();

        if (!consent) return notFound();

        return Response.json({
          success: true,
          data: consent,
          timestamp: new Date().toISOString(),
        });
      }

      // GET /v1/audit/:asset_id
      if (method === 'GET' && url.pathname.startsWith('/v1/audit/')) {
        const assetId = url.pathname.split('/v1/audit/')[1];
        const events = await env.DB.prepare(`
          SELECT * FROM audit_log
          WHERE object_id = ?
          ORDER BY created_at DESC
          LIMIT 100
        `).bind(assetId).all();

        return Response.json({
          success: true,
          data: events.results,
          timestamp: new Date().toISOString(),
        });
      }

      return notFound();
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      console.error('Consent gateway error:', message);
      return Response.json(
        { success: false, error: message, timestamp: new Date().toISOString() },
        { status: 500 }
      );
    }
  },
};

