/**
 * CONSENT GATEWAY — Policy Engine
 *
 * 10-step eligibility check. Every creator-linked request must pass all 10.
 * Order matters: identity → consent → status → terms → scope → tool → dispute → revocation → provenance → payout
 */

export type Decision = 'ALLOW' | 'HOLD' | 'DENY' | 'ESCALATE';

export type EligibilityRequest = {
  creator_id: string;
  claimant_id: string;
  action_type: string;
  tool_name: string;
  requested_scope: {
    media?: string;
    channel?: string;
    territory?: string;
  };
  requested_at: string;
};

export type EligibilityResponse = {
  decision: Decision;
  reason_codes: string[];
  consent_record_id?: string;
  provenance_required?: boolean;
  royalty_route_status?: string;
  missing_requirements?: string[];
};

// --- Never Clause Check ---

const NEVER_CLAUSE_PATTERNS: Record<string, RegExp> = {
  NC_POLITICAL: /political|campaign|election|vote/i,
  NC_SEXUAL: /adult|pornograph|explicit|sexual/i,
  NC_WEAPONS: /weapon|violence|gun|bomb|explosive/i,
  NC_DECEPTION: /fraud|impersonat|deepfake|scam/i,
  NC_HATE: /hate\s?speech|discriminat|supremac/i,
  NC_SURVEILLANCE: /surveillance|biometric\s?id|facial\s?recognition|tracking/i,
};

function checkNeverClauses(actionType: string, toolName: string, scope: Record<string, string | undefined>): string | null {
  const combined = `${actionType} ${toolName} ${Object.values(scope).join(' ')}`;
  for (const [code, pattern] of Object.entries(NEVER_CLAUSE_PATTERNS)) {
    if (pattern.test(combined)) {
      return code;
    }
  }
  return null;
}

// --- Main Eligibility Check ---

export async function checkEligibility(
  body: EligibilityRequest,
  env: { DB: D1Database }
): Promise<EligibilityResponse> {
  const reasons: string[] = [];
  const missing: string[] = [];

  // 0. Never Clause check (instant DENY)
  const ncViolation = checkNeverClauses(body.action_type, body.tool_name, body.requested_scope);
  if (ncViolation) {
    return {
      decision: 'DENY',
      reason_codes: [`NEVER_CLAUSE_VIOLATION:${ncViolation}`],
      royalty_route_status: 'blocked',
      missing_requirements: [`Never Clause ${ncViolation} prohibits this action`],
    };
  }

  // 1. Identity check — creator exists and is active
  const creator = await env.DB.prepare(`
    SELECT id, status FROM creators WHERE id = ? AND status = 'active'
  `).bind(body.creator_id).first<{ id: string; status: string }>();

  if (!creator) {
    return {
      decision: 'DENY',
      reason_codes: ['CREATOR_NOT_FOUND'],
      royalty_route_status: 'blocked',
      missing_requirements: ['Creator must be registered and active'],
    };
  }
  reasons.push('IDENTITY_VALID');

  // 2. Consent existence — find active consent between creator and claimant
  const consent = await env.DB.prepare(`
    SELECT * FROM consent_records
    WHERE creator_id = ? AND claimant_id = ? AND consent_status = 'active'
    ORDER BY created_at DESC LIMIT 1
  `).bind(body.creator_id, body.claimant_id).first<Record<string, unknown>>();

  if (!consent) {
    return {
      decision: 'DENY',
      reason_codes: ['CONSENT_NOT_FOUND'],
      royalty_route_status: 'blocked',
      missing_requirements: ['Active consent record required between creator and claimant'],
    };
  }
  reasons.push('CONSENT_EXISTS');

  // 3. Consent status
  if (consent.consent_status !== 'active') {
    return {
      decision: 'DENY',
      reason_codes: ['CONSENT_INACTIVE'],
      consent_record_id: consent.id as string,
      royalty_route_status: 'blocked',
      missing_requirements: ['Consent must be in active status'],
    };
  }
  reasons.push('CONSENT_ACTIVE');

  // 4. Term validity
  const now = new Date(body.requested_at);
  const termStart = new Date(consent.term_start as string);
  const termEnd = consent.term_end ? new Date(consent.term_end as string) : null;

  if (now < termStart || (termEnd && now > termEnd)) {
    return {
      decision: 'DENY',
      reason_codes: ['TERM_EXPIRED'],
      consent_record_id: consent.id as string,
      royalty_route_status: 'blocked',
      missing_requirements: ['Request falls outside consent term window'],
    };
  }
  reasons.push('TERM_VALID');

  // 5. Scope validity
  let scopeValid = true;
  const consentScope = JSON.parse((consent.scope_json as string) || '{}');

  if (body.requested_scope.media && consentScope.media) {
    if (!consentScope.media.includes(body.requested_scope.media) && consentScope.media !== 'all') {
      scopeValid = false;
      missing.push(`Media type '${body.requested_scope.media}' not in consent scope`);
    }
  }
  if (body.requested_scope.territory && consentScope.territory) {
    if (!consentScope.territory.includes(body.requested_scope.territory) && consentScope.territory !== 'global') {
      scopeValid = false;
      missing.push(`Territory '${body.requested_scope.territory}' not in consent scope`);
    }
  }

  if (!scopeValid) {
    return {
      decision: 'HOLD',
      reason_codes: ['SCOPE_MISMATCH'],
      consent_record_id: consent.id as string,
      royalty_route_status: 'blocked',
      missing_requirements: missing,
    };
  }
  reasons.push('SCOPE_VALID');

  // 6. Tool authorization
  const authorizedTools = JSON.parse((consent.authorized_tools_json as string) || '[]');
  if (authorizedTools.length > 0 && !authorizedTools.includes(body.tool_name) && !authorizedTools.includes('*')) {
    return {
      decision: 'DENY',
      reason_codes: ['TOOL_NOT_AUTHORIZED'],
      consent_record_id: consent.id as string,
      royalty_route_status: 'blocked',
      missing_requirements: [`Tool '${body.tool_name}' not in authorized tools list`],
    };
  }
  reasons.push('TOOL_AUTHORIZED');

  // 7. Dispute check
  if (consent.dispute_status !== 'none') {
    return {
      decision: 'ESCALATE',
      reason_codes: ['DISPUTE_ACTIVE'],
      consent_record_id: consent.id as string,
      royalty_route_status: 'held',
      missing_requirements: ['Active dispute must be resolved before proceeding'],
    };
  }
  reasons.push('NO_DISPUTES');

  // 8. Revocation check
  if (consent.revoked_at) {
    return {
      decision: 'DENY',
      reason_codes: ['CONSENT_REVOKED'],
      consent_record_id: consent.id as string,
      royalty_route_status: 'blocked',
      missing_requirements: ['Consent has been revoked — no new use permitted'],
    };
  }
  reasons.push('NOT_REVOKED');

  // 9. Provenance readiness
  const provenanceRequired = consent.provenance_required === 1;
  reasons.push('PROVENANCE_READY');

  // 10. Payout readiness
  const paymentTerms = JSON.parse((consent.payment_terms_json as string) || '{}');
  const creatorPayout = await env.DB.prepare(`
    SELECT payout_destination FROM creators WHERE id = ?
  `).bind(body.creator_id).first<{ payout_destination: string }>();

  let royaltyStatus = 'ready';
  if (paymentTerms.monetized && (!creatorPayout || !creatorPayout.payout_destination)) {
    royaltyStatus = 'missing_destination';
    missing.push('Creator payout destination not configured');
  }
  reasons.push('ROYALTY_ROUTE_CHECKED');

  // --- Final decision ---
  if (missing.length > 0) {
    return {
      decision: 'HOLD',
      reason_codes: reasons,
      consent_record_id: consent.id as string,
      provenance_required: provenanceRequired,
      royalty_route_status: royaltyStatus,
      missing_requirements: missing,
    };
  }

  return {
    decision: 'ALLOW',
    reason_codes: reasons,
    consent_record_id: consent.id as string,
    provenance_required: provenanceRequired,
    royalty_route_status: royaltyStatus,
  };
}

