      if (!data.success) throw new ConsentError(data.error ?? 'Gateway error', 500);
      return data.data as T;
    } finally {
      clearTimeout(timer);
    }
  }

  // ── Public Methods ────────────────────────────────────────────────────────

  /**
   * Health check — no auth required.
   */
  async health(): Promise<GatewayHealth> {
    const res = await fetch(`${this.url}/health`);
    return res.json() as Promise<GatewayHealth>;
  }

  /**
   * 10-step eligibility check.
   * Call this before ANY creator-linked action.
   * If decision !== 'ALLOW', do not proceed.
   */
  async checkEligibility(req: EligibilityRequest): Promise<EligibilityResponse> {
    return this.request<EligibilityResponse>('POST', '/v1/check-eligibility', {
      ...req,
      requested_at: req.requested_at ?? new Date().toISOString(),
    });
  }

  /**
   * Convenience: check eligibility and throw if not ALLOW.
   * Use when you want inline consent enforcement with no extra logic.
   */
  async requireConsent(req: EligibilityRequest): Promise<EligibilityResponse> {
    const result = await this.checkEligibility(req);
    if (result.decision !== 'ALLOW') {
      throw new ConsentDeniedError(result);
    }
    return result;
  }

  /**
   * Revoke a consent record immediately.
   * Effective at time of call. No new covered use permitted after revocation.
   */
  async revoke(req: RevocationRequest): Promise<RevocationResponse> {
    return this.request<RevocationResponse>('POST', '/v1/revoke', req);
  }

  /**
   * Fetch a specific consent record by ID.
   */
  async getConsent(consentId: string): Promise<ConsentRecord> {
    return this.request<ConsentRecord>('GET', `/v1/consent/${consentId}`);
  }

  /**
   * Fetch audit trail for an asset or object.
   * Returns up to 100 most recent events.
   */
  async getAuditTrail(objectId: string): Promise<AuditEvent[]> {
    return this.request<AuditEvent[]>('GET', `/v1/audit/${objectId}`);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// ERRORS
// ─────────────────────────────────────────────────────────────────────────────

export class ConsentError extends Error {
  constructor(
    message: string,
    public readonly statusCode: number
  ) {
    super(message);
    this.name = 'ConsentError';
  }
}

export class ConsentDeniedError extends Error {
  public readonly decision: Decision;
  public readonly reason_codes: string[];
  public readonly missing_requirements: string[];

  constructor(response: EligibilityResponse) {
    super(
      `Consent ${response.decision}: ${response.reason_codes.join(', ')}`
    );
    this.name = 'ConsentDeniedError';
    this.decision = response.decision;
    this.reason_codes = response.reason_codes;
    this.missing_requirements = response.missing_requirements ?? [];
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// GUARD DECORATOR (optional — for class methods)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Decorator: @ConsentGuard(sdk, { creator_id, claimant_id, action_type, tool_name })
 * Wraps a class method — checks consent before the method runs.
 * Throws ConsentDeniedError if not ALLOW.
 *
 * Example:
 *   @ConsentGuard(sdk, { creator_id: 'RSP_001', claimant_id: 'tool_001', action_type: 'synthesize', tool_name: 'noizyvox' })
 *   async generateVoice(text: string) { ... }
 */
export function ConsentGuard(
  client: ConsentClient,
  req: Omit<EligibilityRequest, 'requested_at'>
) {
  return function (
    _target: object,
    _propertyKey: string,
    descriptor: PropertyDescriptor
  ) {
    const original = descriptor.value;
    descriptor.value = async function (...args: unknown[]) {
      await client.requireConsent(req);
      return original.apply(this, args);
    };
    return descriptor;
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// FACTORY
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create a ConsentClient from environment variables.
 * Expects: CONSENT_GATEWAY_URL, NOIZY_API_KEY
 */
export function createConsentClient(env?: {
  CONSENT_GATEWAY_URL?: string;
  NOIZY_API_KEY?: string;
}): ConsentClient {
  const gatewayUrl =
    env?.CONSENT_GATEWAY_URL ??
    process.env.CONSENT_GATEWAY_URL ??
    'https://consent-gateway.noizylab.workers.dev';

  const apiKey =
    env?.NOIZY_API_KEY ??
    process.env.NOIZY_API_KEY ??
    '';

  if (!apiKey) {
    throw new Error('NOIZY_API_KEY required to initialize ConsentClient');
  }

  return new ConsentClient({ gatewayUrl, apiKey });
}

