// FACTORY
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create a ConsentClient from environment variables.
 * Expects: CONSENT_GATEWAY_URL, NOIZY_API_KEY
 */
export function createConsentClient(env?: {
  CONSENT_GATEWAY_URL?: string;
  NOIZY_API_KEY?: string;
}): ConsentClient {
  const gatewayUrl =
    env?.CONSENT_GATEWAY_URL ??
