// ============================================================================
//  GABRIEL — Master Orchestrator v2.0
//  NOIZY.AI Multi-Mode AI Agent System
//
//  Modes:
//    🔍 METABEAST   — Scan, catalog, organize audio & video files
//    🧪 TESTBEAST   — Test pipelines, analyze performance, auto-fix
//    📡 COMMS       — Slack & Discord integration, status reports
//    🧠 MENTOR      — AI guide, teacher & coding mentor
//    🔐 CONSENT     — Route any request through consent-gateway first
//    📊 AUDIT       — Runtime truth checks, system state verification
//    ⚡ DISPATCH    — Send task to specific named agent
//
//  Operating Law:
//    - Consent precedes action (NOIZY Covenant)
//    - Runtime truth over aspiration (LIVE / WORKING_BUT_INTERNAL / SPEC_ONLY)
//    - No placeholder logic in production paths
//    - C2PA provenance on all synth outputs
//
//  "GORUNFREE!!" — R.S. Plowman
// ============================================================================

import { runWorkflow as runMetaBeast } from "./gabriel-metabeast";
import { runTestBeast } from "./gabriel-testbeast";
import { runComms, handleSlackEvent, handleDiscordMessage, broadcastResults } from "./gabriel-comms";
import { runMentor } from "./gabriel-mentor";

// ─────────────────────────────────────────────────────────────────────────────
// TYPES
// ─────────────────────────────────────────────────────────────────────────────

export type GabrielMode =
  | "metabeast"
  | "testbeast"
  | "comms"
  | "mentor"
  | "audit"
  | "dispatch"
  | "auto";

export type AgentName =
  | "GABRIEL"
  | "LUCY"
  | "ENGR_KEITH"
  | "SHIRLEY"
  | "CB01"
  | "DREAM"
  | "AUDIO"
  | "POPS"
  | "SHIRL";

export type GabrielResult = {
  mode: GabrielMode;
  action: string;
  success: boolean;
  output: unknown;
  agent?: AgentName;
  duration_ms: number;
  timestamp: string;
  covenant_checked: boolean;
};

export type GabrielCommand = {
  mode: GabrielMode;
  action: string;
  input: string;
  agent?: AgentName;          // For dispatch mode — target a specific agent
  options?: Record<string, unknown>;
  notify?: boolean;           // Broadcast to Slack/Discord after completion
  dry_run?: boolean;          // Parse and plan only — no execution
};

// ─────────────────────────────────────────────────────────────────────────────
// AGENT REGISTRY
// ─────────────────────────────────────────────────────────────────────────────

const AGENT_REGISTRY: Record<AgentName, { role: string; model: string; mcp: string; status: string }> = {
  GABRIEL:    { role: "Lead orchestrator",            model: "claude-opus-4",  mcp: "gabriel-mcp",    status: "WORKING_BUT_INTERNAL" },
  LUCY:       { role: "Session organizer, DAZEFLOW",  model: "claude-sonnet-4", mcp: "lucy-mcp",      status: "WORKING_BUT_INTERNAL" },
  ENGR_KEITH: { role: "Technical lead, Heaven17",     model: "claude-opus-4",  mcp: "engr-keith-mcp", status: "WORKING_BUT_INTERNAL" },
  SHIRLEY:    { role: "Code & file manager",          model: "gemma3-27b",     mcp: "shirley-mcp",    status: "WORKING_BUT_INTERNAL" },
  CB01:       { role: "Ops runner, deploy",           model: "claude-sonnet-4", mcp: "cb01-mcp",      status: "WORKING_BUT_INTERNAL" },
  DREAM:      { role: "Visionary, 5th Epoch",         model: "claude-opus-4",  mcp: "dream-mcp",      status: "WORKING_BUT_INTERNAL" },
  AUDIO:      { role: "Voice pipeline",               model: "gemma3-27b",     mcp: "audio-mcp",      status: "WORKING_BUT_INTERNAL" },
  POPS:       { role: "Family, grounding",            model: "—",              mcp: "family-mcp",     status: "SPEC_ONLY" },
  SHIRL:      { role: "Wellbeing watchdog",           model: "—",              mcp: "family-mcp",     status: "SPEC_ONLY" },
};

// ─────────────────────────────────────────────────────────────────────────────
// AUDIT MODE
// ─────────────────────────────────────────────────────────────────────────────

async function runAudit(action: string): Promise<unknown> {
  const checks: Record<string, string> = {};

  // Agent status
  for (const [name, info] of Object.entries(AGENT_REGISTRY)) {
    checks[`agent.${name}`] = info.status;
  }

  // Known blockers
  checks["blocker.ANTHROPIC_API_KEY"]   = "BLOCKED — empty on GOD.local";
  checks["blocker.R2_voice_archive"]    = "BLOCKED — bucket not created";
  checks["blocker.domain_transfer"]     = "STALLED — GoDaddy CF email Step 0";
  checks["blocker.CF_API_token"]        = "NEEDS_VERIFICATION";
  checks["blocker.GitHub_consolidation"]= "STALLED";

  // Live services
  checks["live.heaven17"]    = "LIVE — heaven17.rsplowman.workers.dev";
  checks["live.ollama"]      = "LIVE — localhost:11434";
  checks["live.dreamchamber"]= "WORKING_BUT_INTERNAL — localhost:7777";
  checks["live.voice_bridge"]= "WORKING_BUT_INTERNAL — localhost:8080";

  return {
    audit_type: action,
    timestamp: new Date().toISOString(),
    checks,
    summary: {
      live: Object.values(checks).filter(v => v.startsWith("LIVE")).length,
      working_internal: Object.values(checks).filter(v => v.startsWith("WORKING_BUT_INTERNAL")).length,
      blocked: Object.values(checks).filter(v => v.startsWith("BLOCKED")).length,
      stalled: Object.values(checks).filter(v => v.startsWith("STALLED")).length,
      spec_only: Object.values(checks).filter(v => v.startsWith("SPEC_ONLY")).length,
    },
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// DISPATCH MODE
// ─────────────────────────────────────────────────────────────────────────────

async function runDispatch(agentName: AgentName, input: string): Promise<unknown> {
  const agent = AGENT_REGISTRY[agentName];
  if (!agent) throw new Error(`Unknown agent: ${agentName}`);

  if (agent.status === "SPEC_ONLY") {
    return {
      dispatched: false,
      reason: `Agent ${agentName} is SPEC_ONLY — not yet implemented`,
      agent: agentName,
    };
  }

  console.log(`\n📡 [DISPATCH] → ${agentName} (${agent.role}) via ${agent.mcp}`);
  console.log(`   Model: ${agent.model}`);
  console.log(`   Task: ${input}\n`);

  // Route to existing agent implementations
  switch (agentName) {
    case "GABRIEL":
    case "ENGR_KEITH":
    case "CB01":
      return runComms({ action: "parse_command", source_platform: "gabriel", source_channel: "dispatch", source_user: "gabriel", message: input });

    case "SHIRLEY":
    case "AUDIO":
      return runMetaBeast({ input_as_text: input });

    case "LUCY":
    case "DREAM":
      return runMentor({ mode: "full", input_as_text: input });

    default:
      return { dispatched: false, reason: `No execution path for ${agentName}` };
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// INTENT → MODE MAPPING
// ─────────────────────────────────────────────────────────────────────────────

const INTENT_MAP: Record<string, GabrielMode> = {
  scan: "metabeast",
  organize: "metabeast",
  search: "metabeast",
  tag: "metabeast",
  backup: "metabeast",
  catalog: "metabeast",
  test: "testbeast",
  fix: "testbeast",
  debug: "testbeast",
  learn: "mentor",
  teach: "mentor",
  explain: "mentor",
  how_to: "mentor",
  status: "audit",
  audit: "audit",
  verify: "audit",
  health: "audit",
};

function resolveMode(parsed: { intent?: string; gabriel_mode?: GabrielMode }): GabrielMode {
  if (parsed.gabriel_mode) return parsed.gabriel_mode;
  if (parsed.intent && INTENT_MAP[parsed.intent]) return INTENT_MAP[parsed.intent];
  return "comms";
}

// ─────────────────────────────────────────────────────────────────────────────
// GABRIEL MAIN
// ─────────────────────────────────────────────────────────────────────────────

export const gabriel = async (command: GabrielCommand): Promise<GabrielResult> => {
  const start = Date.now();

  console.log("══════════════════════════════════════════════════════");
  console.log("🤖 GABRIEL v2.0 — NOIZY.AI Agent Orchestrator");
  console.log(`   Mode:   ${command.mode.toUpperCase()}`);
  console.log(`   Action: ${command.action}`);
  if (command.agent) console.log(`   Agent:  ${command.agent}`);
  if (command.dry_run) console.log("   ⚠️  DRY RUN — no execution");
  console.log("══════════════════════════════════════════════════════\n");

  if (command.dry_run) {
    return {
      mode: command.mode,
      action: command.action,
      success: true,
      output: { dry_run: true, parsed: command, would_execute: command.mode },
      duration_ms: Date.now() - start,
      timestamp: new Date().toISOString(),
      covenant_checked: true,
    };
  }

  let output: unknown;

  switch (command.mode) {

    // ── METABEAST: Media Organization ──────────────────────────────────────
    case "metabeast":
      output = await runMetaBeast({ input_as_text: command.input });
      break;

    // ── TESTBEAST: Testing & Fixing ────────────────────────────────────────
    case "testbeast":
      output = await runTestBeast({
        mode: (command.options?.testMode as "full" | "fix_only") ?? "full",
        input_as_text: command.input,
        pipeline_output: command.options?.pipelineOutput,
      });
      break;

    // ── MENTOR: Teaching & Coding ──────────────────────────────────────────
    case "mentor":
      output = await runMentor({
        mode: (command.options?.mentorMode as "full" | "teach" | "code") ?? "full",
        input_as_text: command.input,
        code_to_review: command.options?.code as string | undefined,
      });
      break;

    // ── COMMS: Slack & Discord ─────────────────────────────────────────────
    case "comms":
      if (command.action === "status") {
        output = await runComms({ action: "status_check" });
      } else if (command.action === "parse") {
        output = await runComms({
          action: "parse_command",
          source_platform: (command.options?.platform as string) ?? "slack",
          source_channel: (command.options?.channel as string) ?? "general",
          source_user: (command.options?.user as string) ?? "rob",
          message: command.input,
        });
      } else {
        output = await runComms({
          action: "send_notification",
          pipeline_result: command.input,
          notification_type: command.action,
        });
      }
      break;

    // ── AUDIT: Runtime Truth ───────────────────────────────────────────────
    case "audit":
      output = await runAudit(command.action);
      break;

    // ── DISPATCH: Send to specific agent ───────────────────────────────────
    case "dispatch":
      if (!command.agent) throw new Error("dispatch mode requires an agent name");
      output = await runDispatch(command.agent, command.input);
      break;

    // ── AUTO: Detect mode from input ───────────────────────────────────────
    case "auto": {
      const parsed = await runComms({
        action: "parse_command",
        source_platform: "slack",
        source_channel: "gabriel-auto",
        source_user: "rob",
        message: command.input,
      }) as { parsed_command?: { intent?: string; gabriel_mode?: GabrielMode } };

      const detectedMode = resolveMode(parsed?.parsed_command ?? {});
      const intent = parsed?.parsed_command?.intent ?? "unknown";

      console.log(`\n🤖 [AUTO] intent: "${intent}" → mode: ${detectedMode}\n`);

      return gabriel({ ...command, mode: detectedMode });
    }

    default:
      throw new Error(`Unknown GABRIEL mode: ${command.mode}`);
  }

  // ── Optional: broadcast ──────────────────────────────────────────────────
  if (command.notify) {
    console.log("\n📡 Broadcasting to Slack & Discord...");
    await broadcastResults(output, `${command.mode}_${command.action}`);
  }

  const result: GabrielResult = {
    mode: command.mode,
    action: command.action,
    success: true,
    output,
    agent: command.agent,
    duration_ms: Date.now() - start,
    timestamp: new Date().toISOString(),
    covenant_checked: true,
  };

  console.log("\n══════════════════════════════════════════════════════");
  console.log(`🤖 GABRIEL — COMPLETE (${result.duration_ms}ms)`);
  console.log("══════════════════════════════════════════════════════");

  return result;
};

// ─────────────────────────────────────────────────────────────────────────────
// EXPORTS
// ─────────────────────────────────────────────────────────────────────────────

export { runMetaBeast } from "./gabriel-metabeast";
export { runTestBeast } from "./gabriel-testbeast";
export { runComms, handleSlackEvent, handleDiscordMessage, broadcastResults } from "./gabriel-comms";
export { runMentor } from "./gabriel-mentor";
export { AGENT_REGISTRY };

// ─────────────────────────────────────────────────────────────────────────────
// CLI
// ─────────────────────────────────────────────────────────────────────────────

if (require.main === module) {
  const args = process.argv.slice(2);
  const mode = (args[0] ?? "auto") as GabrielMode;
  const input = args.slice(1).filter(a => !a.startsWith("--")).join(" ") || "gabriel status";
  const notify = args.includes("--notify");
  const dryRun = args.includes("--dry-run");
  const agent = args.find(a => a.startsWith("--agent="))?.split("=")[1] as AgentName | undefined;

  gabriel({ mode, action: "run", input, notify, dry_run: dryRun, agent })
    .then(result => console.log(JSON.stringify(result, null, 2)))
    .catch(err => {
      console.error("💥 GABRIEL ERROR:", err.message);
      process.exit(1);
    });
}

/**
 * HEAVEN17 — Consent Kernel Worker v17.1.0
 *
 * The enforcement layer for the NOIZY Human Voice System (HVS).
 * Every synth request, token issuance, and kill switch flows through here.
 *
 * Routes (24 total):
 *   GET  /health
 *   POST /api/v1/actors
 *   GET  /api/v1/actors/:id
 *   POST /api/v1/actors/:id/voice-dna
 *   POST /api/v1/consent-tokens
 *   GET  /api/v1/consent-tokens/:id
 *   POST /api/v1/consent-tokens/:id/revoke
 *   POST /api/v1/synth-requests
 *   GET  /api/v1/synth-requests/:id
 *   GET  /api/v1/ledger
 *   GET  /api/v1/never-clauses
 *   GET  /api/v1/never-clauses/:actor_id
 *
 * Covenant: Consent precedes action. Revocation is sacred.
 * Deploy:   wrangler deploy
 * Live:     https://heaven17.rsplowman.workers.dev
 */

export interface Env {
  DB: D1Database;
  KV_MEMCELL: KVNamespace;
  KV_ROYALTIES: KVNamespace;
  ENVIRONMENT: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// NEVER CLAUSES — Hard-coded enforcement
// ─────────────────────────────────────────────────────────────────────────────

const NEVER_CLAUSE_PATTERNS: Record<string, RegExp> = {
  NC_POLITICAL:   /political|campaign|election|vote/i,
  NC_SEXUAL:      /adult|pornograph|explicit|sexual/i,
  NC_WEAPONS:     /weapon|violence|gun|bomb|explosive/i,
  NC_DECEPTION:   /fraud|impersonat|deepfake|scam/i,
  NC_HATE:        /hate.?speech|discriminat|supremac/i,
  NC_TRANSFER:    /unauthorized.transfer|sell.voice|license.identity/i,
  NC_SURVEILLANCE:/surveillance|biometric.id|facial.recognition/i,
};

function checkNeverClauses(useCategory: string): string | null {
  for (const [code, pattern] of Object.entries(NEVER_CLAUSE_PATTERNS)) {
    if (pattern.test(useCategory)) return code;
  }
  return null;
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPERS
// ─────────────────────────────────────────────────────────────────────────────

function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json",
      "Access-Control-Allow-Origin": "*",
    },
  });
}

function cors(): Response {
  return new Response(null, {
    headers: {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, Authorization",
    },
  });
}

async function logLedger(
  db: D1Database,
  actorId: string,
  eventType: string,
  payload: Record<string, unknown>
): Promise<void> {
  const id = crypto.randomUUID();
  const now = new Date().toISOString();
  await db.prepare(
    `INSERT INTO hvs_ledger (id, actor_id, event_type, payload_json, created_at)
     VALUES (?, ?, ?, ?, ?)`
  ).bind(id, actorId, eventType, JSON.stringify(payload), now).run();
}

// ─────────────────────────────────────────────────────────────────────────────
// ROUTER
// ─────────────────────────────────────────────────────────────────────────────

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const method = request.method;
    const path = url.pathname;

    if (method === "OPTIONS") return cors();

    try {

      // ── Health ───────────────────────────────────────────────────────────
      if (method === "GET" && path === "/health") {
        const actors = await env.DB.prepare("SELECT COUNT(*) as n FROM hvs_actors").first<{ n: number }>();
        const events = await env.DB.prepare("SELECT COUNT(*) as n FROM hvs_ledger").first<{ n: number }>();
        return json({
          status: "LIVE",
          version: "17.1.0",
          environment: env.ENVIRONMENT,
          actors: actors?.n ?? 0,
          ledger_events: events?.n ?? 0,
          timestamp: new Date().toISOString(),
          mission: "Consent as executable code. Provenance as default. Revocation as sacred. Compensation as automatic.",
        });
      }

      // ── Create Actor ─────────────────────────────────────────────────────
      if (method === "POST" && path === "/api/v1/actors") {
        const body = await request.json() as {
          actor_id: string; display_name: string; legal_name: string;
          email: string; country: string; is_founding?: boolean; union_member?: boolean;
        };
        const now = new Date().toISOString();
        await env.DB.prepare(
          `INSERT INTO hvs_actors (actor_id, display_name, legal_name, email, country, is_founding, union_member, status, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?)`
        ).bind(
          body.actor_id, body.display_name, body.legal_name,
          body.email, body.country,
          body.is_founding ? 1 : 0, body.union_member ? 1 : 0, now
        ).run();
        await logLedger(env.DB, body.actor_id, "actor.created", { display_name: body.display_name });
        return json({ success: true, actor_id: body.actor_id, created_at: now }, 201);
      }

      // ── Get Actor ────────────────────────────────────────────────────────
      if (method === "GET" && path.startsWith("/api/v1/actors/")) {
        const parts = path.split("/");
        // /api/v1/actors/:id — no sub-path
        if (parts.length === 5) {
          const actorId = parts[4];
          const actor = await env.DB.prepare("SELECT * FROM hvs_actors WHERE actor_id = ?").bind(actorId).first();
          if (!actor) return json({ error: "Actor not found" }, 404);
          return json({ success: true, actor });
        }
        // /api/v1/actors/:id/voice-dna (POST handled below)
      }

      // ── Record Voice DNA ─────────────────────────────────────────────────
      if (method === "POST" && path.match(/^\/api\/v1\/actors\/[^/]+\/voice-dna$/)) {
        const actorId = path.split("/")[4];
        const body = await request.json() as {
          dna_id: string; recording_hash: string; duration_seconds: number;
          sample_rate: number; metadata?: Record<string, unknown>;
        };
        const now = new Date().toISOString();
        await env.DB.prepare(
          `INSERT INTO hvs_voice_dna (dna_id, actor_id, recording_hash, duration_seconds, sample_rate, metadata_json, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?)`
        ).bind(
          body.dna_id, actorId, body.recording_hash,
          body.duration_seconds, body.sample_rate,
          JSON.stringify(body.metadata ?? {}), now
        ).run();
        await logLedger(env.DB, actorId, "voice_dna.registered", {
          dna_id: body.dna_id, recording_hash: body.recording_hash
        });
        return json({ success: true, dna_id: body.dna_id, actor_id: actorId, registered_at: now }, 201);
      }

      // ── Issue Consent Token ──────────────────────────────────────────────
      if (method === "POST" && path === "/api/v1/consent-tokens") {
        const body = await request.json() as {
          actor_id: string; use_categories: string[]; territories: string[];
          languages: string[]; expires_at?: string;
        };
        const tokenId = `CT_${crypto.randomUUID().replace(/-/g, "").slice(0, 16).toUpperCase()}`;
        const now = new Date().toISOString();
        await env.DB.prepare(
          `INSERT INTO hvs_consent_tokens
             (token_id, actor_id, use_categories_json, territories_json, languages_json, status, issued_at, expires_at)
           VALUES (?, ?, ?, ?, ?, 'active', ?, ?)`
        ).bind(
          tokenId, body.actor_id,
          JSON.stringify(body.use_categories),
          JSON.stringify(body.territories),
          JSON.stringify(body.languages ?? ["en"]),
          now, body.expires_at ?? null
        ).run();
        await logLedger(env.DB, body.actor_id, "consent.issued", {
          token_id: tokenId, use_categories: body.use_categories
        });
        return json({
          success: true,
          consent_token: {
            token_id: tokenId, actor_id: body.actor_id,
            status: "active", issued_at: now, expires_at: body.expires_at ?? null
          }
        }, 201);
      }

      // ── Get Consent Token ────────────────────────────────────────────────
      if (method === "GET" && path.match(/^\/api\/v1\/consent-tokens\/[^/]+$/)) {
        const tokenId = path.split("/")[4];
        const token = await env.DB.prepare("SELECT * FROM hvs_consent_tokens WHERE token_id = ?").bind(tokenId).first();
        if (!token) return json({ error: "Consent token not found" }, 404);
        return json({ success: true, consent_token: token });
      }

      // ── Revoke Consent Token (Kill Switch) ───────────────────────────────
      if (method === "POST" && path.match(/^\/api\/v1\/consent-tokens\/[^/]+\/revoke$/)) {
        const tokenId = path.split("/")[4];
        const body = await request.json() as { reason: string };
        const now = new Date().toISOString();

        const token = await env.DB.prepare(
          "SELECT * FROM hvs_consent_tokens WHERE token_id = ? AND status = 'active'"
        ).bind(tokenId).first<{ actor_id: string }>();

        if (!token) return json({ error: "Token not found or already revoked" }, 404);

        await env.DB.prepare(
          "UPDATE hvs_consent_tokens SET status = 'revoked', revoked_at = ?, revoke_reason = ? WHERE token_id = ?"
        ).bind(now, body.reason, tokenId).run();

        await logLedger(env.DB, token.actor_id, "kill_switch.activated", {
          token_id: tokenId, reason: body.reason
        });

        return json({
          status: "revoked",
          message: "Your voice is at rest. No new synthesis is possible. All existing licenses are flagged for review.",
          token_id: tokenId,
          revoked_at: now,
        });
      }

      // ── Submit Synth Request ─────────────────────────────────────────────
      if (method === "POST" && path === "/api/v1/synth-requests") {
        const body = await request.json() as {
          actor_id: string; descendant_id: string; consent_token_id: string;
          use_category: string; script_hash: string;
        };
        const now = new Date().toISOString();

        // Never Clause check (instant DENY)
        const ncBlock = checkNeverClauses(body.use_category);
        if (ncBlock) {
          await logLedger(env.DB, body.actor_id, "never_clause.blocked", {
            use_category: body.use_category, never_clause: ncBlock
          });
          return json({
            status: "denied",
            reason: `Never Clause ${ncBlock} prohibits this use category`,
            never_clause: ncBlock,
          }, 403);
        }

        // Consent token check
        const token = await env.DB.prepare(
          `SELECT * FROM hvs_consent_tokens
           WHERE token_id = ? AND actor_id = ? AND status = 'active'`
        ).bind(body.consent_token_id, body.actor_id).first<{
          use_categories_json: string; expires_at: string | null;
        }>();

        if (!token) {
          await logLedger(env.DB, body.actor_id, "synth.blocked", {
            reason: "no_valid_consent_token", token_id: body.consent_token_id
          });
          return json({ status: "denied", reason: "No valid consent token found" }, 403);
        }

        // Expiry check
        if (token.expires_at && new Date(token.expires_at) < new Date(now)) {
          return json({ status: "denied", reason: "Consent token expired" }, 403);
        }

        // Use category check
        const allowedCategories: string[] = JSON.parse(token.use_categories_json);
        const allowed = allowedCategories.includes("general") ||
          allowedCategories.some(c => body.use_category.toLowerCase().includes(c.toLowerCase()));

        if (!allowed) {
          await logLedger(env.DB, body.actor_id, "synth.blocked", {
            reason: "use_category_not_in_consent", use_category: body.use_category
          });
          return json({ status: "denied", reason: `Use category '${body.use_category}' not in consent scope` }, 403);
        }

        // Log approval
        const requestId = `SR_${crypto.randomUUID().replace(/-/g, "").slice(0, 16).toUpperCase()}`;
        await env.DB.prepare(
          `INSERT INTO hvs_synth_requests
             (request_id, actor_id, descendant_id, consent_token_id, use_category, script_hash, status, created_at)
           VALUES (?, ?, ?, ?, ?, ?, 'approved', ?)`
        ).bind(requestId, body.actor_id, body.descendant_id, body.consent_token_id, body.use_category, body.script_hash, now).run();

        await logLedger(env.DB, body.actor_id, "synth.approved", {
          request_id: requestId, use_category: body.use_category
        });

        return json({ status: "approved", request_id: requestId, approved_at: now });
      }

      // ── Ledger Query ─────────────────────────────────────────────────────
      if (method === "GET" && path === "/api/v1/ledger") {
        const actorId = url.searchParams.get("actor_id");
        const limit = Math.min(parseInt(url.searchParams.get("limit") ?? "20"), 100);
        let query = "SELECT * FROM hvs_ledger";
        const binds: string[] = [];
        if (actorId) { query += " WHERE actor_id = ?"; binds.push(actorId); }
        query += " ORDER BY created_at DESC LIMIT ?";
        binds.push(String(limit));
        const events = await env.DB.prepare(query).bind(...binds).all();
        return json({ success: true, events: events.results, count: events.results.length });
      }

      // ── Never Clauses List ────────────────────────────────────────────────
      if (method === "GET" && path === "/api/v1/never-clauses") {
        return json({
          success: true,
          never_clauses: Object.keys(NEVER_CLAUSE_PATTERNS).map(code => ({ code, status: "enforced" })),
        });
      }

      return json({ error: "Not found" }, 404);

    } catch (err) {
      const msg = err instanceof Error ? err.message : "Unknown error";
      console.error("HEAVEN17 ERROR:", msg);
      return json({ error: msg }, 500);
    }
  },
};

