/**
 * HEAVEN17 — Consent Kernel Worker v17.1.0
 *
 * The enforcement layer for the NOIZY Human Voice System (HVS).
 * Every synth request, token issuance, and kill switch flows through here.
 *
 * Routes (24 total):
 *   GET  /health
 *   POST /api/v1/actors
 *   GET  /api/v1/actors/:id
 *   POST /api/v1/actors/:id/voice-dna
 *   POST /api/v1/consent-tokens
 *   GET  /api/v1/consent-tokens/:id
 *   POST /api/v1/consent-tokens/:id/revoke
 *   POST /api/v1/synth-requests
 *   GET  /api/v1/synth-requests/:id
 *   GET  /api/v1/ledger
 *   GET  /api/v1/never-clauses
 *   GET  /api/v1/never-clauses/:actor_id
 *
 * Covenant: Consent precedes action. Revocation is sacred.
 * Deploy:   wrangler deploy
 * Live:     https://heaven17.rsplowman.workers.dev
 */

export interface Env {
  DB: D1Database;
  KV_MEMCELL: KVNamespace;
  KV_ROYALTIES: KVNamespace;
  ENVIRONMENT: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// NEVER CLAUSES — Hard-coded enforcement
// ─────────────────────────────────────────────────────────────────────────────

const NEVER_CLAUSE_PATTERNS: Record<string, RegExp> = {
  NC_POLITICAL:   /political|campaign|election|vote/i,
  NC_SEXUAL:      /adult|pornograph|explicit|sexual/i,
  NC_WEAPONS:     /weapon|violence|gun|bomb|explosive/i,
  NC_DECEPTION:   /fraud|impersonat|deepfake|scam/i,
  NC_HATE:        /hate.?speech|discriminat|supremac/i,
  NC_TRANSFER:    /unauthorized.transfer|sell.voice|license.identity/i,
  NC_SURVEILLANCE:/surveillance|biometric.id|facial.recognition/i,
};

function checkNeverClauses(useCategory: string): string | null {
  for (const [code, pattern] of Object.entries(NEVER_CLAUSE_PATTERNS)) {
    if (pattern.test(useCategory)) return code;
  }
  return null;
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPERS
// ─────────────────────────────────────────────────────────────────────────────

function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json",
      "Access-Control-Allow-Origin": "*",
    },
  });
}

function cors(): Response {
  return new Response(null, {
    headers: {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, Authorization",
    },
  });
}

async function logLedger(
  db: D1Database,
  actorId: string,
  eventType: string,
  payload: Record<string, unknown>
): Promise<void> {
  const id = crypto.randomUUID();
  const now = new Date().toISOString();
  await db.prepare(
    `INSERT INTO hvs_ledger (id, actor_id, event_type, payload_json, created_at)
     VALUES (?, ?, ?, ?, ?)`
  ).bind(id, actorId, eventType, JSON.stringify(payload), now).run();
}

// ─────────────────────────────────────────────────────────────────────────────
// ROUTER
// ─────────────────────────────────────────────────────────────────────────────

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const method = request.method;
    const path = url.pathname;

    if (method === "OPTIONS") return cors();

    try {

      // ── Health ───────────────────────────────────────────────────────────
      if (method === "GET" && path === "/health") {
        const actors = await env.DB.prepare("SELECT COUNT(*) as n FROM hvs_actors").first<{ n: number }>();
        const events = await env.DB.prepare("SELECT COUNT(*) as n FROM hvs_ledger").first<{ n: number }>();
        return json({
          status: "LIVE",
          version: "17.1.0",
          environment: env.ENVIRONMENT,
          actors: actors?.n ?? 0,
          ledger_events: events?.n ?? 0,
          timestamp: new Date().toISOString(),
          mission: "Consent as executable code. Provenance as default. Revocation as sacred. Compensation as automatic.",
        });
      }

      // ── Create Actor ─────────────────────────────────────────────────────
      if (method === "POST" && path === "/api/v1/actors") {
        const body = await request.json() as {
          actor_id: string; display_name: string; legal_name: string;
          email: string; country: string; is_founding?: boolean; union_member?: boolean;
        };
        const now = new Date().toISOString();
        await env.DB.prepare(
          `INSERT INTO hvs_actors (actor_id, display_name, legal_name, email, country, is_founding, union_member, status, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?)`
        ).bind(
          body.actor_id, body.display_name, body.legal_name,
          body.email, body.country,
          body.is_founding ? 1 : 0, body.union_member ? 1 : 0, now
        ).run();
        await logLedger(env.DB, body.actor_id, "actor.created", { display_name: body.display_name });
        return json({ success: true, actor_id: body.actor_id, created_at: now }, 201);
      }

      // ── Get Actor ────────────────────────────────────────────────────────
      if (method === "GET" && path.startsWith("/api/v1/actors/")) {
        const parts = path.split("/");
        // /api/v1/actors/:id — no sub-path
        if (parts.length === 5) {
          const actorId = parts[4];
          const actor = await env.DB.prepare("SELECT * FROM hvs_actors WHERE actor_id = ?").bind(actorId).first();
          if (!actor) return json({ error: "Actor not found" }, 404);
          return json({ success: true, actor });
        }
        // /api/v1/actors/:id/voice-dna (POST handled below)
      }

      // ── Record Voice DNA ─────────────────────────────────────────────────
      if (method === "POST" && path.match(/^\/api\/v1\/actors\/[^/]+\/voice-dna$/)) {
        const actorId = path.split("/")[4];
        const body = await request.json() as {
          dna_id: string; recording_hash: string; duration_seconds: number;
          sample_rate: number; metadata?: Record<string, unknown>;
        };
        const now = new Date().toISOString();
        await env.DB.prepare(
          `INSERT INTO hvs_voice_dna (dna_id, actor_id, recording_hash, duration_seconds, sample_rate, metadata_json, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?)`
        ).bind(
          body.dna_id, actorId, body.recording_hash,
          body.duration_seconds, body.sample_rate,
          JSON.stringify(body.metadata ?? {}), now
        ).run();
        await logLedger(env.DB, actorId, "voice_dna.registered", {
          dna_id: body.dna_id, recording_hash: body.recording_hash
        });
        return json({ success: true, dna_id: body.dna_id, actor_id: actorId, registered_at: now }, 201);
      }

      // ── Issue Consent Token ──────────────────────────────────────────────
      if (method === "POST" && path === "/api/v1/consent-tokens") {
        const body = await request.json() as {
          actor_id: string; use_categories: string[]; territories: string[];
          languages: string[]; expires_at?: string;
        };
        const tokenId = `CT_${crypto.randomUUID().replace(/-/g, "").slice(0, 16).toUpperCase()}`;
        const now = new Date().toISOString();
        await env.DB.prepare(
          `INSERT INTO hvs_consent_tokens
             (token_id, actor_id, use_categories_json, territories_json, languages_json, status, issued_at, expires_at)
           VALUES (?, ?, ?, ?, ?, 'active', ?, ?)`
        ).bind(
          tokenId, body.actor_id,
          JSON.stringify(body.use_categories),
          JSON.stringify(body.territories),
          JSON.stringify(body.languages ?? ["en"]),
          now, body.expires_at ?? null
        ).run();
        await logLedger(env.DB, body.actor_id, "consent.issued", {
          token_id: tokenId, use_categories: body.use_categories
        });
        return json({
          success: true,
          consent_token: {
            token_id: tokenId, actor_id: body.actor_id,
            status: "active", issued_at: now, expires_at: body.expires_at ?? null
          }
        }, 201);
      }

      // ── Get Consent Token ────────────────────────────────────────────────
      if (method === "GET" && path.match(/^\/api\/v1\/consent-tokens\/[^/]+$/)) {
        const tokenId = path.split("/")[4];
        const token = await env.DB.prepare("SELECT * FROM hvs_consent_tokens WHERE token_id = ?").bind(tokenId).first();
        if (!token) return json({ error: "Consent token not found" }, 404);
        return json({ success: true, consent_token: token });
      }

      // ── Revoke Consent Token (Kill Switch) ───────────────────────────────
      if (method === "POST" && path.match(/^\/api\/v1\/consent-tokens\/[^/]+\/revoke$/)) {
        const tokenId = path.split("/")[4];
        const body = await request.json() as { reason: string };
        const now = new Date().toISOString();

        const token = await env.DB.prepare(
          "SELECT * FROM hvs_consent_tokens WHERE token_id = ? AND status = 'active'"
        ).bind(tokenId).first<{ actor_id: string }>();

        if (!token) return json({ error: "Token not found or already revoked" }, 404);

        await env.DB.prepare(
          "UPDATE hvs_consent_tokens SET status = 'revoked', revoked_at = ?, revoke_reason = ? WHERE token_id = ?"
        ).bind(now, body.reason, tokenId).run();

        await logLedger(env.DB, token.actor_id, "kill_switch.activated", {
          token_id: tokenId, reason: body.reason
        });

        return json({
          status: "revoked",
          message: "Your voice is at rest. No new synthesis is possible. All existing licenses are flagged for review.",
          token_id: tokenId,
          revoked_at: now,
        });
      }

      // ── Submit Synth Request ─────────────────────────────────────────────
      if (method === "POST" && path === "/api/v1/synth-requests") {
        const body = await request.json() as {
          actor_id: string; descendant_id: string; consent_token_id: string;
          use_category: string; script_hash: string;
        };
        const now = new Date().toISOString();

        // Never Clause check (instant DENY)
        const ncBlock = checkNeverClauses(body.use_category);
        if (ncBlock) {
          await logLedger(env.DB, body.actor_id, "never_clause.blocked", {
            use_category: body.use_category, never_clause: ncBlock
          });
          return json({
            status: "denied",
            reason: `Never Clause ${ncBlock} prohibits this use category`,
            never_clause: ncBlock,
          }, 403);
        }

        // Consent token check
        const token = await env.DB.prepare(
          `SELECT * FROM hvs_consent_tokens
           WHERE token_id = ? AND actor_id = ? AND status = 'active'`
        ).bind(body.consent_token_id, body.actor_id).first<{
          use_categories_json: string; expires_at: string | null;
        }>();

        if (!token) {
          await logLedger(env.DB, body.actor_id, "synth.blocked", {
            reason: "no_valid_consent_token", token_id: body.consent_token_id
          });
          return json({ status: "denied", reason: "No valid consent token found" }, 403);
        }

        // Expiry check
        if (token.expires_at && new Date(token.expires_at) < new Date(now)) {
          return json({ status: "denied", reason: "Consent token expired" }, 403);
        }

        // Use category check
        const allowedCategories: string[] = JSON.parse(token.use_categories_json);
        const allowed = allowedCategories.includes("general") ||
          allowedCategories.some(c => body.use_category.toLowerCase().includes(c.toLowerCase()));

        if (!allowed) {
          await logLedger(env.DB, body.actor_id, "synth.blocked", {
            reason: "use_category_not_in_consent", use_category: body.use_category
          });
          return json({ status: "denied", reason: `Use category '${body.use_category}' not in consent scope` }, 403);
        }

        // Log approval
        const requestId = `SR_${crypto.randomUUID().replace(/-/g, "").slice(0, 16).toUpperCase()}`;
        await env.DB.prepare(
          `INSERT INTO hvs_synth_requests
             (request_id, actor_id, descendant_id, consent_token_id, use_category, script_hash, status, created_at)
           VALUES (?, ?, ?, ?, ?, ?, 'approved', ?)`
        ).bind(requestId, body.actor_id, body.descendant_id, body.consent_token_id, body.use_category, body.script_hash, now).run();

        await logLedger(env.DB, body.actor_id, "synth.approved", {
          request_id: requestId, use_category: body.use_category
        });

        return json({ status: "approved", request_id: requestId, approved_at: now });
      }

      // ── Ledger Query ─────────────────────────────────────────────────────
      if (method === "GET" && path === "/api/v1/ledger") {
        const actorId = url.searchParams.get("actor_id");
        const limit = Math.min(parseInt(url.searchParams.get("limit") ?? "20"), 100);
        let query = "SELECT * FROM hvs_ledger";
        const binds: string[] = [];
        if (actorId) { query += " WHERE actor_id = ?"; binds.push(actorId); }
        query += " ORDER BY created_at DESC LIMIT ?";
        binds.push(String(limit));
        const events = await env.DB.prepare(query).bind(...binds).all();
        return json({ success: true, events: events.results, count: events.results.length });
      }

      // ── Never Clauses List ────────────────────────────────────────────────
      if (method === "GET" && path === "/api/v1/never-clauses") {
        return json({
          success: true,
          never_clauses: Object.keys(NEVER_CLAUSE_PATTERNS).map(code => ({ code, status: "enforced" })),
        });
      }

      return json({ error: "Not found" }, 404);

    } catch (err) {
      const msg = err instanceof Error ? err.message : "Unknown error";
      console.error("HEAVEN17 ERROR:", msg);
      return json({ error: msg }, 500);
    }
  },
};

