// ============================================================================
//  GABRIEL — Master Orchestrator v2.0
//  NOIZY.AI Multi-Mode AI Agent System
//
//  Modes:
//    🔍 METABEAST   — Scan, catalog, organize audio & video files
//    🧪 TESTBEAST   — Test pipelines, analyze performance, auto-fix
//    📡 COMMS       — Slack & Discord integration, status reports
//    🧠 MENTOR      — AI guide, teacher & coding mentor
//    🔐 CONSENT     — Route any request through consent-gateway first
//    📊 AUDIT       — Runtime truth checks, system state verification
//    ⚡ DISPATCH    — Send task to specific named agent
//
//  Operating Law:
//    - Consent precedes action (NOIZY Covenant)
//    - Runtime truth over aspiration (LIVE / WORKING_BUT_INTERNAL / SPEC_ONLY)
//    - No placeholder logic in production paths
//    - C2PA provenance on all synth outputs
//
//  "GORUNFREE!!" — R.S. Plowman
// ============================================================================

import { runWorkflow as runMetaBeast } from "./gabriel-metabeast";
import { runTestBeast } from "./gabriel-testbeast";
import { runComms, handleSlackEvent, handleDiscordMessage, broadcastResults } from "./gabriel-comms";
import { runMentor } from "./gabriel-mentor";

// ─────────────────────────────────────────────────────────────────────────────
// TYPES
// ─────────────────────────────────────────────────────────────────────────────

export type GabrielMode =
  | "metabeast"
  | "testbeast"
  | "comms"
  | "mentor"
  | "audit"
  | "dispatch"
  | "auto";

export type AgentName =
  | "GABRIEL"
  | "LUCY"
  | "ENGR_KEITH"
  | "SHIRLEY"
  | "CB01"
  | "DREAM"
  | "AUDIO"
  | "POPS"
  | "SHIRL";

export type GabrielResult = {
  mode: GabrielMode;
  action: string;
  success: boolean;
  output: unknown;
  agent?: AgentName;
  duration_ms: number;
  timestamp: string;
  covenant_checked: boolean;
};

export type GabrielCommand = {
  mode: GabrielMode;
  action: string;
  input: string;
  agent?: AgentName;          // For dispatch mode — target a specific agent
  options?: Record<string, unknown>;
  notify?: boolean;           // Broadcast to Slack/Discord after completion
  dry_run?: boolean;          // Parse and plan only — no execution
};

// ─────────────────────────────────────────────────────────────────────────────
// AGENT REGISTRY
// ─────────────────────────────────────────────────────────────────────────────

const AGENT_REGISTRY: Record<AgentName, { role: string; model: string; mcp: string; status: string }> = {
  GABRIEL:    { role: "Lead orchestrator",            model: "claude-opus-4",  mcp: "gabriel-mcp",    status: "WORKING_BUT_INTERNAL" },
  LUCY:       { role: "Session organizer, DAZEFLOW",  model: "claude-sonnet-4", mcp: "lucy-mcp",      status: "WORKING_BUT_INTERNAL" },
  ENGR_KEITH: { role: "Technical lead, Heaven17",     model: "claude-opus-4",  mcp: "engr-keith-mcp", status: "WORKING_BUT_INTERNAL" },
  SHIRLEY:    { role: "Code & file manager",          model: "gemma3-27b",     mcp: "shirley-mcp",    status: "WORKING_BUT_INTERNAL" },
  CB01:       { role: "Ops runner, deploy",           model: "claude-sonnet-4", mcp: "cb01-mcp",      status: "WORKING_BUT_INTERNAL" },
  DREAM:      { role: "Visionary, 5th Epoch",         model: "claude-opus-4",  mcp: "dream-mcp",      status: "WORKING_BUT_INTERNAL" },
  AUDIO:      { role: "Voice pipeline",               model: "gemma3-27b",     mcp: "audio-mcp",      status: "WORKING_BUT_INTERNAL" },
  POPS:       { role: "Family, grounding",            model: "—",              mcp: "family-mcp",     status: "SPEC_ONLY" },
  SHIRL:      { role: "Wellbeing watchdog",           model: "—",              mcp: "family-mcp",     status: "SPEC_ONLY" },
};

// ─────────────────────────────────────────────────────────────────────────────
// AUDIT MODE
// ─────────────────────────────────────────────────────────────────────────────

async function runAudit(action: string): Promise<unknown> {
  const checks: Record<string, string> = {};

  // Agent status
  for (const [name, info] of Object.entries(AGENT_REGISTRY)) {
    checks[`agent.${name}`] = info.status;
  }

  // Known blockers
  checks["blocker.ANTHROPIC_API_KEY"]   = "BLOCKED — empty on GOD.local";
  checks["blocker.R2_voice_archive"]    = "BLOCKED — bucket not created";
  checks["blocker.domain_transfer"]     = "STALLED — GoDaddy CF email Step 0";
  checks["blocker.CF_API_token"]        = "NEEDS_VERIFICATION";
  checks["blocker.GitHub_consolidation"]= "STALLED";

  // Live services
  checks["live.heaven17"]    = "LIVE — heaven17.rsplowman.workers.dev";
  checks["live.ollama"]      = "LIVE — localhost:11434";
  checks["live.dreamchamber"]= "WORKING_BUT_INTERNAL — localhost:7777";
  checks["live.voice_bridge"]= "WORKING_BUT_INTERNAL — localhost:8080";

  return {
    audit_type: action,
    timestamp: new Date().toISOString(),
    checks,
    summary: {
      live: Object.values(checks).filter(v => v.startsWith("LIVE")).length,
      working_internal: Object.values(checks).filter(v => v.startsWith("WORKING_BUT_INTERNAL")).length,
      blocked: Object.values(checks).filter(v => v.startsWith("BLOCKED")).length,
      stalled: Object.values(checks).filter(v => v.startsWith("STALLED")).length,
      spec_only: Object.values(checks).filter(v => v.startsWith("SPEC_ONLY")).length,
    },
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// DISPATCH MODE
// ─────────────────────────────────────────────────────────────────────────────

async function runDispatch(agentName: AgentName, input: string): Promise<unknown> {
  const agent = AGENT_REGISTRY[agentName];
  if (!agent) throw new Error(`Unknown agent: ${agentName}`);

  if (agent.status === "SPEC_ONLY") {
    return {
      dispatched: false,
      reason: `Agent ${agentName} is SPEC_ONLY — not yet implemented`,
      agent: agentName,
    };
  }

  console.log(`\n📡 [DISPATCH] → ${agentName} (${agent.role}) via ${agent.mcp}`);
  console.log(`   Model: ${agent.model}`);
  console.log(`   Task: ${input}\n`);

  // Route to existing agent implementations
  switch (agentName) {
    case "GABRIEL":
    case "ENGR_KEITH":
    case "CB01":
      return runComms({ action: "parse_command", source_platform: "gabriel", source_channel: "dispatch", source_user: "gabriel", message: input });

    case "SHIRLEY":
    case "AUDIO":
      return runMetaBeast({ input_as_text: input });

    case "LUCY":
    case "DREAM":
      return runMentor({ mode: "full", input_as_text: input });

    default:
      return { dispatched: false, reason: `No execution path for ${agentName}` };
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// INTENT → MODE MAPPING
// ─────────────────────────────────────────────────────────────────────────────

const INTENT_MAP: Record<string, GabrielMode> = {
  scan: "metabeast",
  organize: "metabeast",
  search: "metabeast",
  tag: "metabeast",
  backup: "metabeast",
  catalog: "metabeast",
  test: "testbeast",
  fix: "testbeast",
  debug: "testbeast",
  learn: "mentor",
  teach: "mentor",
  explain: "mentor",
  how_to: "mentor",
