  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-NOIZY-Key",
  "X-Powered-By": "HEAVEN17/RSP_001",
  "Cache-Control": "no-store",
};

// ─── Input sanitisation helpers ─────────────────────────────────────────────

/** Validate an ID field (actor_id, token_id, etc.) — alphanumeric + hyphens + underscores only */
function isValidId(id) {
  return typeof id === "string" && /^[A-Za-z0-9_-]{1,128}$/.test(id);
}

/** Sanitise a freetext field — strip control chars, enforce max length */
function sanitizeText(text, maxLen = 2000) {
  if (typeof text !== "string") return "";
  return text.replace(/[\x00-\x1F\x7F]/g, "").substring(0, maxLen);
}

function json(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: CORS_HEADERS });
}

function err(message, status = 400) {
  return json({ error: message, status }, status);
}

// ─── Auth ────────────────────────────────────────────────────────────────────

function authenticate(request, env) {
  const key =
    request.headers.get("X-NOIZY-Key") ||
    request.headers.get("Authorization")?.replace("Bearer ", "");
  if (!env.NOIZY_API_KEY) return true; // No key configured = open (dev mode)
  if (!key) return false;
  return key === env.NOIZY_API_KEY;
}

// ─── Rate Limiter (KV-backed) ────────────────────────────────────────────────

async function checkRateLimit(kv, ip, limit = 60, windowSec = 60) {
  if (!kv) return { allowed: true };
  const key = `rl:${ip}`;
  const current = parseInt((await kv.get(key)) || "0");
  if (current >= limit) {
    return { allowed: false, remaining: 0, reset: windowSec };
  }
  await kv.put(key, String(current + 1), { expirationTtl: windowSec });
  return { allowed: true, remaining: limit - current - 1 };
}

// ─── KV Cache ────────────────────────────────────────────────────────────────

async function kvGet(kv, key) {
  if (!kv) return null;
  const cached = await kv.get(key, "json");
  return cached;
}

async function kvSet(kv, key, value, ttlSec = 300) {
  if (!kv) return;
  await kv.put(key, JSON.stringify(value), { expirationTtl: ttlSec });
}

async function kvInvalidate(kv, ...keys) {
  if (!kv) return;
  for (const key of keys) {
    await kv.delete(key);
  }
}

async function ledgerAppend(db, event) {
  try {
    await db
      .prepare(
        `
      INSERT INTO noizy_ledger
        (event_id, actor_id, descendant_id, licensee_id, license_id,
         consent_token_id, event_type, payload_json, amount_cad,
         actor_share_cad, noizy_share_cad, union_share_cad, source_system, recorded_at)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    `,
      )
      .bind(
        event.event_id || uuid(),
        event.actor_id || null,
        event.descendant_id || null,
        event.licensee_id || null,
        event.license_id || null,
        event.consent_token_id || null,
        event.event_type,
        JSON.stringify(event.payload || {}),
        event.amount_cad || 0,
        event.actor_share_cad || 0,
        event.noizy_share_cad || 0,
        event.union_share_cad || 0,
        "GABRIEL",
        now(),
      )
      .run();
  } catch (e) {
    console.error("Ledger append failed:", e.message);
  }
}

// ─── Router ──────────────────────────────────────────────────────────────────

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;
    const method = request.method;
    const db = env.GABRIEL_DB;
    const kv = env.GABRIEL_KV;

    // CORS preflight — dynamic origin matching
    if (method === "OPTIONS") {
      return new Response(null, { status: 204, headers: corsHeaders(request) });
    }

    try {
      // Rate limiting (60 req/min per IP, uses KV)
      const ip = request.headers.get("CF-Connecting-IP") || "unknown";
      const rl = await checkRateLimit(kv, ip);
      if (!rl.allowed) {
        return json({ error: "Rate limit exceeded", retry_after: rl.reset }, 429);
      }

      // Auth check (skip for health, dashboard, root, gabriel status, OPTIONS)
      if (
        path !== "/health" &&
        path !== "/dashboard" &&
        path !== "/" &&
        path !== "/gabriel" &&
        !authenticate(request, env)
      ) {
        return err("Unauthorized — provide X-NOIZY-Key header", 401);
      }
      // ── Health ──────────────────────────────────────────────────────────────
      if (path === "/health" && method === "GET") {
        const cached = await kvGet(kv, "health");
        if (cached) return json(cached);

        const actorCount = await db.prepare("SELECT COUNT(*) as c FROM hvs_actors").first();
        const ledgerCount = await db.prepare("SELECT COUNT(*) as c FROM noizy_ledger").first();
        const tokenCount = await db.prepare("SELECT COUNT(*) as c FROM hvs_consent_tokens").first();
        const data = {
          status: "LIVE",
          version: env.NOIZY_VERSION,
          environment: env.NOIZY_ENV,
          database: "gabriel_db",
          actors: actorCount?.c || 0,
          consent_tokens: tokenCount?.c || 0,
          ledger_events: ledgerCount?.c || 0,
          timestamp: now(),
          uptime: "edge",
          mission:
            "Consent as executable code. Provenance as default. Revocation as sacred. Compensation as automatic.",
        };
        await kvSet(kv, "health", data, 60); // cache 60s (KV minimum TTL)
        return json(data);
      }

      // ── Actors ──────────────────────────────────────────────────────────────
      if (path === "/api/v1/actors" && method === "GET") {
        const cached = await kvGet(kv, "actors:all");
        if (cached) return json(cached);
        const { results } = await db
          .prepare("SELECT * FROM hvs_actors ORDER BY onboarded_at DESC")
          .all();
        const data = { actors: results };
        await kvSet(kv, "actors:all", data, 120);
        return json(data);
      }

      if (path === "/api/v1/actors" && method === "POST") {
        const body = await request.json();
        const {
          actor_id,
          display_name,
          legal_name,
          email,
          country,
          is_founding,
          union_member,
          union_name,
        } = body;
        if (!actor_id || !display_name) return err("actor_id and display_name are required");

        await db
          .prepare(
            `
          INSERT INTO hvs_actors (actor_id, display_name, legal_name, email, country, is_founding, union_member, union_name)
          VALUES (?,?,?,?,?,?,?,?)
        `,
          )
          .bind(
            actor_id,
            display_name,
            legal_name || null,
            email || null,
            country || "CA",
            is_founding ? 1 : 0,
            union_member ? 1 : 0,
            union_name || null,
          )
          .run();

        await ledgerAppend(db, {
          actor_id,
          event_type: "system.audit",
          payload: { action: "actor.created", display_name, is_founding },
        });

        const actor = await db
          .prepare("SELECT * FROM hvs_actors WHERE actor_id = ?")
          .bind(actor_id)
          .first();
        await kvInvalidate(kv, "actors:all", "health");
        return json({ actor }, 201);
      }

      const actorMatch = path.match(/^\/api\/v1\/actors\/([^/]+)$/);
      if (actorMatch && method === "GET") {
        const actor = await db
          .prepare("SELECT * FROM hvs_actors WHERE actor_id = ?")
          .bind(actorMatch[1])
          .first();
        if (!actor) return err("Actor not found", 404);
        return json({ actor });
      }

      const neverClausesMatch = path.match(/^\/api\/v1\/actors\/([^/]+)\/never-clauses$/);
      if (neverClausesMatch && method === "GET") {
        const { results } = await db
          .prepare("SELECT * FROM hvs_never_clauses WHERE actor_id = ? ORDER BY clause_id")
          .bind(neverClausesMatch[1])
          .all();
        return json({ never_clauses: results, count: results.length });
      }

      const descendantsMatch = path.match(/^\/api\/v1\/actors\/([^/]+)\/descendants$/);
      if (descendantsMatch && method === "GET") {
        const { results } = await db
          .prepare("SELECT * FROM hvs_descendants WHERE actor_id = ? ORDER BY created_at DESC")
          .bind(descendantsMatch[1])
          .all();
        return json({ descendants: results, count: results.length });
      }

      const consentTokensActorMatch = path.match(/^\/api\/v1\/actors\/([^/]+)\/consent-tokens$/);
      if (consentTokensActorMatch && method === "GET") {
        const { results } = await db
          .prepare("SELECT * FROM hvs_consent_tokens WHERE actor_id = ? ORDER BY issued_at DESC")
          .bind(consentTokensActorMatch[1])
          .all();
        return json({ consent_tokens: results, count: results.length });
      }

      // ── Consent Tokens ──────────────────────────────────────────────────────
      if (path === "/api/v1/consent-tokens" && method === "POST") {
        const body = await request.json();
        const {
          actor_id,
          descendant_id,
          use_categories,
          territories,
          languages,
          licensee_id,
          time_window_start,
          time_window_end,
          expires_at,
        } = body;
        if (!actor_id || !use_categories) return err("actor_id and use_categories are required");

        const actor = await db
          .prepare("SELECT * FROM hvs_actors WHERE actor_id = ?")
          .bind(actor_id)
          .first();
        if (!actor) return err("Actor not found", 404);
        if (actor.status !== "active")
          return err(`Actor status is ${actor.status} — cannot issue consent token`);

        const token_id = uuid();
        const token_hash = await hashToken(token_id + actor_id + now());

        await db
          .prepare(
            `
          INSERT INTO hvs_consent_tokens
            (token_id, actor_id, descendant_id, token_hash, use_categories, territories,
             languages, time_window_start, time_window_end, licensee_id, expires_at, status)
          VALUES (?,?,?,?,?,?,?,?,?,?,?,'active')
        `,
          )
          .bind(
            token_id,
            actor_id,
            descendant_id || null,
            token_hash,
            JSON.stringify(use_categories),
            JSON.stringify(territories || ["GLOBAL"]),
            JSON.stringify(languages || ["*"]),
            time_window_start || null,
            time_window_end || null,
            licensee_id || null,
            expires_at || null,
          )
          .run();

        await ledgerAppend(db, {
          actor_id,
          descendant_id: descendant_id || null,
          consent_token_id: token_id,
          event_type: "consent.issued",
          payload: { use_categories, territories, licensee_id },
        });

        const token = await db
          .prepare("SELECT * FROM hvs_consent_tokens WHERE token_id = ?")
          .bind(token_id)
          .first();
        await kvInvalidate(kv, "health");
        return json({ consent_token: token }, 201);
      }

      // Kill switch — revoke consent token
      const revokeMatch = path.match(/^\/api\/v1\/consent-tokens\/([^/]+)\/revoke$/);
      if (revokeMatch && method === "POST") {
        const token_id = revokeMatch[1];
        const body = await request.json().catch(() => ({}));
        const token = await db
          .prepare("SELECT * FROM hvs_consent_tokens WHERE token_id = ?")
          .bind(token_id)
          .first();
        if (!token) return err("Consent token not found", 404);
        if (token.status === "revoked") return err("Token already revoked");

        await db
          .prepare(
            `
          UPDATE hvs_consent_tokens SET status = 'revoked', revoked_at = ?, revocation_reason = ? WHERE token_id = ?
        `,
          )
          .bind(now(), body.reason || "Actor revoked consent", token_id)
          .run();

        await ledgerAppend(db, {
          actor_id: token.actor_id,
          descendant_id: token.descendant_id,
          consent_token_id: token_id,
          event_type: "kill_switch.activated",
          payload: { reason: body.reason || "Actor revoked consent", token_id },
        });

        await kvInvalidate(kv, "health");
        return json({
          status: "revoked",
          message:
            "Your voice is at rest. No new synthesis is possible. All existing licenses are flagged for review.",
          token_id,
          revoked_at: now(),
        });
      }

      // ── Descendants ──────────────────────────────────────────────────────────
      if (path === "/api/v1/descendants" && method === "POST") {
        const body = await request.json();
        const {
          actor_id,
          parent_dna_id,
          name,
          character_type,
          emotional_tags,
          consent_scope,
          licensing_enabled,
          approval_required,
          synthesis_model,
        } = body;
        if (!actor_id || !parent_dna_id || !name)
          return err("actor_id, parent_dna_id, and name required");

        // Get actor's royalty floor
        const actor = await db
          .prepare("SELECT * FROM hvs_actors WHERE actor_id = ?")
          .bind(actor_id)
          .first();
        if (!actor) return err("Actor not found", 404);
        const royalty_floor = actor.is_founding ? 85.0 : 75.0;

        const descendant_id = uuid();
        await db
          .prepare(
            `
          INSERT INTO hvs_descendants
            (descendant_id, actor_id, parent_dna_id, name, character_type, emotional_tags,
             consent_scope, licensing_enabled, approval_required, synthesis_model, royalty_floor_pct)
          VALUES (?,?,?,?,?,?,?,?,?,?,?)
        `,
          )
          .bind(
            descendant_id,
            actor_id,
            parent_dna_id,
            name,
            character_type || null,
            JSON.stringify(emotional_tags || []),
            consent_scope || "private",
            licensing_enabled ? 1 : 0,
            approval_required !== false ? 1 : 0,
            synthesis_model || null,
            royalty_floor,
          )
          .run();

        await ledgerAppend(db, {
          actor_id,
          descendant_id,
          event_type: "descendant.created",
          payload: { name, character_type, consent_scope, royalty_floor },
        });

        const descendant = await db
          .prepare("SELECT * FROM hvs_descendants WHERE descendant_id = ?")
          .bind(descendant_id)
          .first();
        await kvInvalidate(kv, "health");
        return json({ descendant }, 201);
      }

      const descendantMatch = path.match(/^\/api\/v1\/descendants\/([^/]+)$/);
      if (descendantMatch && method === "GET") {
        const d = await db
          .prepare("SELECT * FROM hvs_descendants WHERE descendant_id = ?")
          .bind(descendantMatch[1])
          .first();
        if (!d) return err("Descendant not found", 404);
        return json({ descendant: d });
      }

      // ── Synth Requests (Never Clause Enforced) ───────────────────────────────
      if (path === "/api/v1/synth-requests" && method === "POST") {
        const body = await request.json();
        const {
          actor_id,
          descendant_id,
          consent_token_id,
          use_category,
          script_hash,
          emotional_profile,
          licensee_id,
        } = body;
        if (!actor_id || !descendant_id || !consent_token_id || !use_category) {
          return err("actor_id, descendant_id, consent_token_id, and use_category are required");
        }

        // 1. Validate consent token
        const token = await db
          .prepare(
            "SELECT * FROM hvs_consent_tokens WHERE token_id = ? AND actor_id = ? AND status = ?",
          )
          .bind(consent_token_id, actor_id, "active")
          .first();
        if (!token) {
          await ledgerAppend(db, {
            actor_id,
            descendant_id,
            event_type: "synth.blocked",
            payload: {
              reason: "No valid active consent token",
              consent_token_id,
            },
          });
          return err("No valid active consent token — synthesis blocked", 403);
        }

        // 2. Check token expiry
        if (token.expires_at && new Date(token.expires_at) < new Date()) {
          await db
            .prepare("UPDATE hvs_consent_tokens SET status = ? WHERE token_id = ?")
            .bind("expired", consent_token_id)
            .run();
          await ledgerAppend(db, {
            actor_id,
            event_type: "consent.expired",
            payload: { consent_token_id },
          });
          return err("Consent token has expired — synthesis blocked", 403);
        }

        // 3. Never Clause check
        const { results: never_clauses } = await db
          .prepare("SELECT * FROM hvs_never_clauses WHERE actor_id = ? AND is_global = 1")
          .bind(actor_id)
          .all();

        // Check use_category against known never clause categories
        const blockedClause = never_clauses.find((nc) => {
          const cat = nc.category.toLowerCase();
          const uc = use_category.toLowerCase();
          return (
            (cat === "political" && (uc.includes("politic") || uc.includes("propaganda"))) ||
            (cat === "sexual" &&
              (uc.includes("adult") || uc.includes("sexual") || uc.includes("porn"))) ||
            (cat === "weapons" &&
              (uc.includes("weapon") || uc.includes("violence") || uc.includes("harm"))) ||
            (cat === "deception" &&
              (uc.includes("deceiv") || uc.includes("impersonat") || uc.includes("fraud"))) ||
            (cat === "hate" && (uc.includes("hate") || uc.includes("demean"))) ||
            (cat === "transfer" && (uc.includes("transfer") || uc.includes("sublicens")))
          );
        });

        const request_id = uuid();

        if (blockedClause) {
          await db
            .prepare(
              `
            INSERT INTO hvs_synth_requests
              (request_id, actor_id, descendant_id, consent_token_id, licensee_id,
               script_hash, use_category, never_clause_check, blocked_clause_id, status)
            VALUES (?,?,?,?,?,?,?,'blocked',?,'blocked')
          `,
            )
            .bind(
              request_id,
              actor_id,
              descendant_id,
              consent_token_id,
              licensee_id || null,
              script_hash || null,
              use_category,
              blockedClause.clause_id,
            )
            .run();

          await ledgerAppend(db, {
            actor_id,
            descendant_id,
            consent_token_id,
            event_type: "never_clause.blocked",
            payload: {
              clause_code: blockedClause.clause_code,
              use_category,
              request_id,
            },
          });

          return json(
            {
              status: "blocked",
              request_id,
              blocked_by: blockedClause.clause_code,
              message: blockedClause.clause_text,
            },
            403,
          );
        }

        // 4. All clear — create synth request
        await db
          .prepare(
            `
          INSERT INTO hvs_synth_requests
            (request_id, actor_id, descendant_id, consent_token_id, licensee_id,
             script_hash, use_category, emotional_profile, never_clause_check, status)
          VALUES (?,?,?,?,?,?,?,?,'passed','approved')
        `,
          )
          .bind(
            request_id,
            actor_id,
            descendant_id,
            consent_token_id,
            licensee_id || null,
            script_hash || null,
            use_category,
            emotional_profile ? JSON.stringify(emotional_profile) : null,
          )
          .run();

        await ledgerAppend(db, {
          actor_id,
          descendant_id,
          consent_token_id,
          event_type: "synth.approved",
          payload: { use_category, request_id, never_clause_check: "passed" },
        });

        return json(
          {
            status: "approved",
            request_id,
            never_clause_check: "passed",
            message: "Synthesis approved. Proceed with generation.",
          },
          201,
        );
      }

      const synthMatch = path.match(/^\/api\/v1\/synth-requests\/([^/]+)$/);
      if (synthMatch && method === "GET") {
        const req = await db
          .prepare("SELECT * FROM hvs_synth_requests WHERE request_id = ?")
          .bind(synthMatch[1])
          .first();
        if (!req) return err("Synth request not found", 404);
        return json({ synth_request: req });
      }

      // ── Licenses ─────────────────────────────────────────────────────────────
      if (path === "/api/v1/licenses" && method === "GET") {
        const actor_id = url.searchParams.get("actor_id");
        const query = actor_id
          ? "SELECT * FROM hvs_licenses WHERE actor_id = ? ORDER BY issued_at DESC"
          : "SELECT * FROM hvs_licenses ORDER BY issued_at DESC LIMIT 100";
        const { results } = actor_id
          ? await db.prepare(query).bind(actor_id).all()
          : await db.prepare(query).all();
        return json({ licenses: results, count: results.length });
      }

      if (path === "/api/v1/licenses" && method === "POST") {
        const body = await request.json();
        const {
          licensee_id,
          actor_id,
          descendant_id,
          consent_token_id,
          use_category,
          territory,
          duration_type,
          license_fee_cad,
        } = body;
        if (!licensee_id || !actor_id || !descendant_id || !consent_token_id || !use_category) {
          return err(
            "licensee_id, actor_id, descendant_id, consent_token_id, use_category required",
          );
        }

        const actor = await db
          .prepare("SELECT * FROM hvs_actors WHERE actor_id = ?")
          .bind(actor_id)
          .first();
        if (!actor) return err("Actor not found", 404);

        const actor_share = actor.is_founding ? 85.0 : 75.0;
        const noizy_share = actor.is_founding ? 15.0 : 25.0;
        const fee = license_fee_cad || 0;
        const license_id = uuid();

        await db
          .prepare(
            `
          INSERT INTO hvs_licenses
            (license_id, licensee_id, actor_id, descendant_id, consent_token_id,
             use_category, territory, duration_type, license_fee_cad, actor_share_pct, noizy_share_pct)
          VALUES (?,?,?,?,?,?,?,?,?,?,?)
        `,
          )
          .bind(
            license_id,
            licensee_id,
            actor_id,
            descendant_id,
            consent_token_id,
            use_category,
            territory || "GLOBAL",
            duration_type || "perpetual",
            fee,
            actor_share,
            noizy_share,
          )
          .run();

        await ledgerAppend(db, {
          actor_id,
          descendant_id,
          licensee_id,
          license_id,
          consent_token_id,
          event_type: "license.issued",
          amount_cad: fee,
          actor_share_cad: (fee * actor_share) / 100,
          noizy_share_cad: (fee * noizy_share) / 100,
          payload: {
            use_category,
            territory,
            duration_type,
            license_fee_cad: fee,
          },
        });

        await kvInvalidate(kv, "health");
        return json(
          {
            license_id,
            actor_share_pct: actor_share,
            noizy_share_pct: noizy_share,
          },
          201,
        );
      }

      // ── Mentors ──────────────────────────────────────────────────────────────

      // GET /api/v1/mentors — list all mentors
      if (path === "/api/v1/mentors" && method === "GET") {
        const status = url.searchParams.get("status");
        const tier = url.searchParams.get("tier");
        let query = "SELECT m.*, a.display_name, a.email FROM hvs_mentors m LEFT JOIN hvs_actors a ON m.actor_id = a.actor_id WHERE 1=1";
        const params = [];
        if (status) { query += " AND m.status = ?"; params.push(status); }
        if (tier) { query += " AND m.tier = ?"; params.push(tier); }
        query += " ORDER BY m.activated_at DESC";
        const { results } = await db.prepare(query).bind(...params).all();
        return json({ mentors: results, count: results.length });
      }

      // GET /api/v1/mentors/:id — get single mentor
      if (path.match(/^\/api\/v1\/mentors\/[^/]+$/) && method === "GET") {
        const mentorId = path.split("/")[4];
        const mentor = await db.prepare("SELECT m.*, a.display_name, a.email FROM hvs_mentors m LEFT JOIN hvs_actors a ON m.actor_id = a.actor_id WHERE m.mentor_id = ?").bind(mentorId).first();
        if (!mentor) return err("Mentor not found", 404);
        const rep = await db.prepare("SELECT * FROM hvs_reputation WHERE actor_id = ?").bind(mentor.actor_id).first();
        const menteeCount = await db.prepare("SELECT COUNT(*) as c FROM hvs_mentorships WHERE mentor_id = ?").bind(mentorId).first();
        return json({ mentor, reputation: rep, active_mentees: menteeCount?.c || 0 });
      }

      // POST /api/v1/mentors — nominate a new mentor
      if (path === "/api/v1/mentors" && method === "POST") {
        const body = await request.json();
        const { actor_id, specializations, bio } = body;
        if (!actor_id) return err("actor_id required", 400);
        const actor = await db.prepare("SELECT * FROM hvs_actors WHERE actor_id = ?").bind(actor_id).first();
        if (!actor) return err("Actor not found", 404);
        const existing = await db.prepare("SELECT * FROM hvs_mentors WHERE actor_id = ?").bind(actor_id).first();
        if (existing) return err("Actor already has mentor record", 409);
        const mentorId = `MENTOR-${actor_id}`;
        await db.prepare("INSERT INTO hvs_mentors (mentor_id, actor_id, status, specializations, bio) VALUES (?, ?, 'pending', ?, ?)").bind(mentorId, actor_id, specializations || null, bio || null).run();
        await db.prepare("INSERT OR IGNORE INTO hvs_reputation (actor_id, score, peer_score, mentee_score, dispute_score) VALUES (?, 0, 0, 0, 10)").bind(actor_id).run();
        return json({ mentor_id: mentorId, status: "pending", message: "Mentor nomination submitted. Requires peer endorsement." }, 201);
      }

      // POST /api/v1/mentors/:id/activate — activate a pending mentor
      if (path.match(/^\/api\/v1\/mentors\/[^/]+\/activate$/) && method === "POST") {
        const mentorId = path.split("/")[4];
        const mentor = await db.prepare("SELECT * FROM hvs_mentors WHERE mentor_id = ?").bind(mentorId).first();
        if (!mentor) return err("Mentor not found", 404);
        if (mentor.status === "active") return err("Mentor already active", 409);
        await db.prepare("UPDATE hvs_mentors SET status = 'active', activated_at = ?, updated_at = ? WHERE mentor_id = ?").bind(now(), now(), mentorId).run();
        await db.prepare("INSERT INTO noizy_ledger (event_id, event_type, actor_id, payload_json, source_system, recorded_at) VALUES (?, 'mentor.activated', ?, ?, 'GABRIEL', ?)").bind(`MENTOR-ACT-${uuid()}`, mentor.actor_id, JSON.stringify({ mentor_id: mentorId, tier: mentor.tier }), now()).run();
        return json({ mentor_id: mentorId, status: "active", activated_at: now() });
      }

      // ── Mentorships ─────────────────────────────────────────────────────────

      // GET /api/v1/mentorships — list mentorships
      if (path === "/api/v1/mentorships" && method === "GET") {
        const mentor_id = url.searchParams.get("mentor_id");
        const mentee_id = url.searchParams.get("mentee_id");
        const phase = url.searchParams.get("phase");
        let query = "SELECT ms.*, m.actor_id as mentor_actor_id FROM hvs_mentorships ms LEFT JOIN hvs_mentors m ON ms.mentor_id = m.mentor_id WHERE 1=1";
        const params = [];
        if (mentor_id) { query += " AND ms.mentor_id = ?"; params.push(mentor_id); }
        if (mentee_id) { query += " AND ms.mentee_id = ?"; params.push(mentee_id); }
        if (phase) { query += " AND ms.phase = ?"; params.push(phase); }
        query += " ORDER BY ms.started_at DESC";
        const { results } = await db.prepare(query).bind(...params).all();
        return json({ mentorships: results, count: results.length });
      }

      // POST /api/v1/mentorships — create a new mentorship
      if (path === "/api/v1/mentorships" && method === "POST") {
        const body = await request.json();
        const { mentor_id, mentee_id } = body;
        if (!mentor_id || !mentee_id) return err("mentor_id and mentee_id required", 400);
        const mentor = await db.prepare("SELECT * FROM hvs_mentors WHERE mentor_id = ? AND status = 'active'").bind(mentor_id).first();
        if (!mentor) return err("Mentor not found or not active", 404);
        const mentee = await db.prepare("SELECT * FROM hvs_actors WHERE actor_id = ?").bind(mentee_id).first();
        if (!mentee) return err("Mentee actor not found", 404);
        if (mentor.actor_id === mentee_id) return err("Cannot mentor yourself", 400);
        const msId = `MS-${uuid()}`;
        await db.prepare("INSERT INTO hvs_mentorships (mentorship_id, mentor_id, mentee_id, phase) VALUES (?, ?, ?, 'discovery')").bind(msId, mentor_id, mentee_id).run();
        await db.prepare("INSERT INTO noizy_ledger (event_id, event_type, actor_id, payload_json, source_system, recorded_at) VALUES (?, 'mentorship.started', ?, ?, 'GABRIEL', ?)").bind(`MS-START-${uuid()}`, mentee_id, JSON.stringify({ mentorship_id: msId, mentor_id, mentee_id }), now()).run();
        return json({ mentorship_id: msId, phase: "discovery", message: "Mentorship initiated." }, 201);
      }

      // POST /api/v1/mentorships/:id/advance — advance mentorship phase
      if (path.match(/^\/api\/v1\/mentorships\/[^/]+\/advance$/) && method === "POST") {
        const msId = path.split("/")[4];
        const ms = await db.prepare("SELECT * FROM hvs_mentorships WHERE mentorship_id = ?").bind(msId).first();
        if (!ms) return err("Mentorship not found", 404);
        const phases = ['discovery', 'foundation', 'development', 'mastery', 'graduation'];
        const currentIdx = phases.indexOf(ms.phase);
        if (currentIdx >= phases.length - 1) return err("Mentorship already at final phase", 400);
        const nextPhase = phases[currentIdx + 1];
        const updates = { phase: nextPhase, updated_at: now() };
        if (nextPhase === 'graduation') updates.graduated_at = now();
        await db.prepare(`UPDATE hvs_mentorships SET phase = ?, updated_at = ?${nextPhase === 'graduation' ? ', graduated_at = ?' : ''} WHERE mentorship_id = ?`).bind(...(nextPhase === 'graduation' ? [nextPhase, now(), now(), msId] : [nextPhase, now(), msId])).run();
        if (nextPhase === 'graduation') {
          await db.prepare("INSERT INTO noizy_ledger (event_id, event_type, actor_id, payload_json, source_system, recorded_at) VALUES (?, 'mentorship.graduated', ?, ?, 'GABRIEL', ?)").bind(`MS-GRAD-${uuid()}`, ms.mentee_id, JSON.stringify({ mentorship_id: msId, mentor_id: ms.mentor_id }), now()).run();
        }
        return json({ mentorship_id: msId, phase: nextPhase, previous_phase: ms.phase });
      }

      // ── Lineage ─────────────────────────────────────────────────────────────

      // GET /api/v1/lineage — list lineage records
      if (path === "/api/v1/lineage" && method === "GET") {
        const mentor_id = url.searchParams.get("mentor_id");
        const mentee_id = url.searchParams.get("mentee_id");
        let query = "SELECT * FROM hvs_lineage WHERE 1=1";
        const params = [];
        if (mentor_id) { query += " AND mentor_id = ?"; params.push(mentor_id); }
        if (mentee_id) { query += " AND mentee_id = ?"; params.push(mentee_id); }
        query += " ORDER BY established_at DESC";
        const { results } = await db.prepare(query).bind(...params).all();
        return json({ lineage: results, count: results.length });
      }

      // POST /api/v1/lineage — establish a lineage bond
      if (path === "/api/v1/lineage" && method === "POST") {
        const body = await request.json();
        const { mentor_id, mentee_id, royalty_pct, source_mentorship_id } = body;
        if (!mentor_id || !mentee_id) return err("mentor_id and mentee_id required", 400);
        const pct = parseFloat(royalty_pct || 5);
        if (pct < 0 || pct > 15) return err("royalty_pct must be 0-15%", 400);
        // Check generation depth — max 3
        const existingLineage = await db.prepare("SELECT MAX(generation) as max_gen FROM hvs_lineage WHERE mentee_id = (SELECT actor_id FROM hvs_mentors WHERE mentor_id = ?)").bind(mentor_id).first();
        const generation = (existingLineage?.max_gen || 0) + 1;
        if (generation > 3) return err("Maximum lineage depth (3 generations) reached", 400);
        // Check cumulative cap — max 25%
        const cumulativeRes = await db.prepare("SELECT COALESCE(SUM(royalty_pct), 0) as total FROM hvs_lineage WHERE mentee_id = ? AND is_active = 1").bind(mentee_id).first();
        if ((cumulativeRes?.total || 0) + pct > 25) return err(`Cumulative lineage royalty would exceed 25% cap (current: ${cumulativeRes?.total}%)`, 400);
        const lineageId = `LIN-${uuid()}`;
        await db.prepare("INSERT INTO hvs_lineage (lineage_id, mentor_id, mentee_id, generation, royalty_pct, source_mentorship_id) VALUES (?, ?, ?, ?, ?, ?)").bind(lineageId, mentor_id, mentee_id, generation, pct, source_mentorship_id || null).run();
        await db.prepare("INSERT INTO noizy_ledger (event_id, event_type, actor_id, payload_json, source_system, recorded_at) VALUES (?, 'lineage.established', ?, ?, 'GABRIEL', ?)").bind(`LIN-EST-${uuid()}`, mentee_id, JSON.stringify({ lineage_id: lineageId, mentor_id, mentee_id, royalty_pct: pct, generation }), now()).run();
        return json({ lineage_id: lineageId, generation, royalty_pct: pct, message: "Lineage bond established." }, 201);
      }

      // ── Reputation ──────────────────────────────────────────────────────────

      // GET /api/v1/reputation/:actor_id — get NRW reputation score
      if (path.match(/^\/api\/v1\/reputation\/[^/]+$/) && method === "GET") {
        const actorId = path.split("/")[4];
        const rep = await db.prepare("SELECT * FROM hvs_reputation WHERE actor_id = ?").bind(actorId).first();
        if (!rep) return err("Reputation record not found", 404);
        return json({ reputation: rep });
      }

      // ── Masterclasses ───────────────────────────────────────────────────────

      // GET /api/v1/masterclasses — list masterclasses
      if (path === "/api/v1/masterclasses" && method === "GET") {
        const mentor_id = url.searchParams.get("mentor_id");
        const status = url.searchParams.get("status") || "published";
        let query = "SELECT mc.*, m.actor_id as mentor_actor_id FROM hvs_masterclasses mc LEFT JOIN hvs_mentors m ON mc.mentor_id = m.mentor_id WHERE mc.status = ?";
        const params = [status];
        if (mentor_id) { query += " AND mc.mentor_id = ?"; params.push(mentor_id); }
        query += " ORDER BY mc.created_at DESC";
        const { results } = await db.prepare(query).bind(...params).all();
        return json({ masterclasses: results, count: results.length });
      }

      // POST /api/v1/masterclasses — create a masterclass
      if (path === "/api/v1/masterclasses" && method === "POST") {
        const body = await request.json();
        const { mentor_id, title, description, price_cad, access_type, category, max_participants, duration_min } = body;
        if (!mentor_id || !title) return err("mentor_id and title required", 400);
        const mentor = await db.prepare("SELECT * FROM hvs_mentors WHERE mentor_id = ? AND status = 'active'").bind(mentor_id).first();
        if (!mentor) return err("Mentor not found or not active", 404);
        const classId = `MC-${uuid()}`;
        await db.prepare("INSERT INTO hvs_masterclasses (class_id, mentor_id, title, description, price_cad, access_type, category, max_participants, duration_min) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(classId, mentor_id, title, description || null, parseFloat(price_cad || 0), access_type || 'one_time', category || null, max_participants ? parseInt(max_participants) : null, parseInt(duration_min || 90)).run();
        await db.prepare("INSERT INTO noizy_ledger (event_id, event_type, actor_id, payload_json, source_system, recorded_at) VALUES (?, 'masterclass.published', ?, ?, 'GABRIEL', ?)").bind(`MC-PUB-${uuid()}`, mentor.actor_id, JSON.stringify({ class_id: classId, title, price_cad: parseFloat(price_cad || 0) }), now()).run();
        return json({ class_id: classId, status: "draft", message: "Masterclass created." }, 201);
      }

      // ── Covenant ──────────────────────────────────────────────────────────────

      // GET /api/v1/covenant/validate — run full covenant validation
      if (path === "/api/v1/covenant/validate" && method === "GET") {
        const results = await validateCovenant(db);
        const statusCode = results.overall === "PASS" ? 200 : 422;
        await db.prepare("INSERT INTO noizy_ledger (event_id, event_type, actor_id, payload_json, source_system, recorded_at) VALUES (?, 'system.audit', 'SYSTEM', ?, 'GABRIEL', ?)").bind(`COV-CHECK-${uuid()}`, JSON.stringify({ overall: results.overall, checks_run: results.checks.length, failures: results.checks.filter(c => c.status === 'FAIL').length }), now()).run();
        return json(results, statusCode);
      }

