 *   GET  /health
 *   POST /v1/route-payment        — Calculate and record a split
 *   GET  /v1/splits/:creator_id   — Get pending splits for creator
 *   POST /v1/splits/:id/confirm   — Confirm payout dispatched
 *   GET  /v1/ledger               — Full royalty ledger
 *   GET  /v1/summary/:creator_id  — Lifetime earnings summary
 *
 * Law: Creator 75% minimum. Always. No exceptions without signed override.
 * Deploy: wrangler deploy --config wrangler.toml
 */

export interface Env {
  DB: D1Database;
  KV_ROYALTIES: KVNamespace;
  ENVIRONMENT: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// SPLIT ENGINE
// ─────────────────────────────────────────────────────────────────────────────

const DEFAULT_SPLIT = { creator_pct: 75, platform_pct: 25 };
const FOUNDING_SPLIT = { creator_pct: 85, platform_pct: 15 };

function calculateSplit(
  gross: number,
  is_founding: boolean,
  override?: { creator_pct: number; platform_pct: number }
): { creator_amount: number; platform_amount: number; creator_pct: number; platform_pct: number } {
  const split = override ?? (is_founding ? FOUNDING_SPLIT : DEFAULT_SPLIT);

  // Hard floor: creator always gets at least 75% (65% for non-founding with union)
  if (split.creator_pct < 65) {
    throw new Error(`Split violation: creator_pct ${split.creator_pct}% is below minimum 65%`);
  }

  return {
    creator_amount: Math.round((gross * split.creator_pct) / 100 * 100) / 100,
    platform_amount: Math.round((gross * split.platform_pct) / 100 * 100) / 100,
    creator_pct: split.creator_pct,
    platform_pct: split.platform_pct,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPERS
// ─────────────────────────────────────────────────────────────────────────────

function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// ROUTER
// ─────────────────────────────────────────────────────────────────────────────

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const method = request.method;
    const path = url.pathname;

    if (method === "OPTIONS") {
      return new Response(null, {
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type, X-NOIZY-Key",
        },
      });
    }

    try {

      // ── Health ─────────────────────────────────────────────────────────────
      if (method === "GET" && path === "/health") {
        const total = await env.DB.prepare(
          "SELECT COUNT(*) as n, COALESCE(SUM(gross_amount), 0) as gross FROM royalty_events"
        ).first<{ n: number; gross: number }>();
        return json({
          status: "LIVE",
          version: "1.0.0",
          service: "royalty-router",
          split_law: "Creator 75% minimum. Founding actors 85%.",
          total_events: total?.n ?? 0,
          total_gross_usd: total?.gross ?? 0,
          timestamp: new Date().toISOString(),
        });
      }

      // ── Route Payment ──────────────────────────────────────────────────────
      if (method === "POST" && path === "/v1/route-payment") {
        const body = await request.json() as {
          creator_id: string;
          usage_event_id: string;
          gross_amount: number;
          currency?: string;
          override?: { creator_pct: number; platform_pct: number; signed_by: string; reason: string };
        };

        if (!body.creator_id || !body.gross_amount || !body.usage_event_id) {
          return json({ error: "creator_id, usage_event_id, gross_amount required" }, 400);
        }

        // Look up creator to check founding status
        const creator = await env.DB.prepare(
          "SELECT * FROM creators WHERE id = ?"
        ).bind(body.creator_id).first<{ id: string; status: string; payout_destination: string | null }>();

        const is_founding = body.creator_id === "RSP_001";

        // Validate override if provided
        if (body.override && !body.override.signed_by) {
          return json({ error: "Override splits require signed_by field" }, 400);
        }

        const split = calculateSplit(body.gross_amount, is_founding, body.override);

        // Write royalty event
        const id = crypto.randomUUID();
        const now = new Date().toISOString();

        await env.DB.prepare(
          `INSERT INTO royalty_events
             (id, usage_event_id, creator_id, gross_amount, creator_amount, platform_amount,
              currency, payout_status, payout_due_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', datetime('now', '+30 days'))`
        ).bind(
          id, body.usage_event_id, body.creator_id,
          body.gross_amount, split.creator_amount, split.platform_amount,
          body.currency ?? "USD"
        ).run();

        // Cache pending total for creator
        const cacheKey = `pending:${body.creator_id}`;
        const existing = await env.KV_ROYALTIES.get(cacheKey, "json") as { total: number } | null;
        await env.KV_ROYALTIES.put(cacheKey, JSON.stringify({
          total: (existing?.total ?? 0) + split.creator_amount,
          updated_at: now,
        }), { expirationTtl: 3600 });

        return json({
          royalty_event_id: id,
          creator_id: body.creator_id,
          gross_amount: body.gross_amount,
          creator_amount: split.creator_amount,
          platform_amount: split.platform_amount,
          creator_pct: split.creator_pct,
          platform_pct: split.platform_pct,
          currency: body.currency ?? "USD",
          payout_status: "pending",
          payout_due_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
          is_founding_rate: is_founding,
          override_applied: !!body.override,
        }, 201);
      }

      // ── Get Splits for Creator ─────────────────────────────────────────────
      if (method === "GET" && path.match(/^\/v1\/splits\/[^/]+$/)) {
        const creatorId = path.split("/")[3];
        const status = url.searchParams.get("status") ?? "pending";
        const events = await env.DB.prepare(
          `SELECT * FROM royalty_events WHERE creator_id = ? AND payout_status = ?
           ORDER BY payout_due_at ASC LIMIT 50`
        ).bind(creatorId, status).all();

        const total = events.results.reduce(
          (sum, e) => sum + ((e as { creator_amount: number }).creator_amount ?? 0), 0
        );

        return json({
          creator_id: creatorId,
          status_filter: status,
          events: events.results,
          count: events.results.length,
          total_creator_amount: Math.round(total * 100) / 100,
        });
      }

      // ── Confirm Payout ────────────────────────────────────────────────────
      if (method === "POST" && path.match(/^\/v1\/splits\/[^/]+\/confirm$/)) {
        const eventId = path.split("/")[3];
        const body = await request.json() as { payout_reference?: string };
        const now = new Date().toISOString();

        const event = await env.DB.prepare(
          "SELECT * FROM royalty_events WHERE id = ?"
        ).bind(eventId).first<{ id: string; creator_id: string; payout_status: string }>();

        if (!event) return json({ error: "Royalty event not found" }, 404);
        if (event.payout_status === "paid") return json({ error: "Already paid" }, 409);

        await env.DB.prepare(
          "UPDATE royalty_events SET payout_status = 'paid', paid_at = ? WHERE id = ?"
        ).bind(now, eventId).run();

        // Invalidate cache
        await env.KV_ROYALTIES.delete(`pending:${event.creator_id}`);

        return json({ confirmed: true, event_id: eventId, paid_at: now });
      }

      // ── Royalty Ledger ────────────────────────────────────────────────────
      if (method === "GET" && path === "/v1/ledger") {
        const creatorId = url.searchParams.get("creator_id");
        const limit = Math.min(parseInt(url.searchParams.get("limit") ?? "50"), 200);
        let query = "SELECT * FROM royalty_events";
        const binds: unknown[] = [];
        if (creatorId) { query += " WHERE creator_id = ?"; binds.push(creatorId); }
        query += " ORDER BY payout_due_at DESC LIMIT ?";
        binds.push(limit);
        const events = await env.DB.prepare(query).bind(...binds).all();
        return json({ events: events.results, count: events.results.length });
      }

      // ── Lifetime Summary ──────────────────────────────────────────────────
      if (method === "GET" && path.match(/^\/v1\/summary\/[^/]+$/)) {
        const creatorId = path.split("/")[3];
        const summary = await env.DB.prepare(
          `SELECT
             COUNT(*) as total_events,
             COALESCE(SUM(gross_amount), 0) as lifetime_gross,
             COALESCE(SUM(creator_amount), 0) as lifetime_creator,
             COALESCE(SUM(platform_amount), 0) as lifetime_platform,
             COALESCE(SUM(CASE WHEN payout_status = 'pending' THEN creator_amount ELSE 0 END), 0) as pending_creator,
             COALESCE(SUM(CASE WHEN payout_status = 'paid' THEN creator_amount ELSE 0 END), 0) as paid_creator
           FROM royalty_events WHERE creator_id = ?`
        ).bind(creatorId).first();

        return json({
          creator_id: creatorId,
          is_founding: creatorId === "RSP_001",
          split_law: creatorId === "RSP_001" ? "85/15 (founding)" : "75/25 (standard)",
          ...summary,
        });
      }

      return json({ error: "Not found" }, 404);

    } catch (err) {
      const msg = err instanceof Error ? err.message : "Unknown error";
      console.error("ROYALTY-ROUTER ERROR:", msg);
      return json({ error: msg }, 500);
    }
  },
};

