/**
 * GABRIEL RUNTIME — NOIZY.AI Worker v1.0.0
 *
 * Cloudflare Worker: Agent dispatch hub for the GABRIEL multi-agent system.
 * Receives task requests, routes to the right agent, logs all dispatches.
 *
 * Routes:
 *   GET  /health
 *   POST /v1/dispatch             — Dispatch a task to an agent
 *   GET  /v1/tasks/:id            — Get task status
 *   GET  /v1/tasks                — List recent tasks
 *   POST /v1/tasks/:id/complete   — Mark task complete (agent callback)
 *   GET  /v1/agents               — List agent registry and status
 *
 * Agents: GABRIEL, LUCY, ENGR_KEITH, SHIRLEY, CB01, DREAM, AUDIO
 * Deploy: wrangler deploy --config wrangler.toml
 */

export interface Env {
  DB: D1Database;
  KV_MEMCELL: KVNamespace;
  ENVIRONMENT: string;
  GABRIEL_API_URL?: string;   // GOD.local:7777 tunnel URL (set when DreamChamber is up)
}

// ─────────────────────────────────────────────────────────────────────────────
// AGENT REGISTRY
// ─────────────────────────────────────────────────────────────────────────────

const AGENTS = {
  GABRIEL:    { role: "Lead orchestrator", model: "claude-opus-4",   status: "WORKING_BUT_INTERNAL" },
  LUCY:       { role: "Session organizer, DAZEFLOW", model: "claude-sonnet-4", status: "WORKING_BUT_INTERNAL" },
  ENGR_KEITH: { role: "Technical lead, Heaven17", model: "claude-opus-4", status: "WORKING_BUT_INTERNAL" },
  SHIRLEY:    { role: "Code & file manager", model: "gemma3-27b",    status: "WORKING_BUT_INTERNAL" },
  CB01:       { role: "Ops runner, deploy", model: "claude-sonnet-4", status: "WORKING_BUT_INTERNAL" },
  DREAM:      { role: "Visionary, 5th Epoch", model: "claude-opus-4", status: "WORKING_BUT_INTERNAL" },
  AUDIO:      { role: "Voice pipeline", model: "gemma3-27b",          status: "WORKING_BUT_INTERNAL" },
  POPS:       { role: "Family, grounding", model: "—",                status: "SPEC_ONLY" },
  SHIRL:      { role: "Wellbeing watchdog", model: "—",               status: "SPEC_ONLY" },
} as const;

type AgentName = keyof typeof AGENTS;

// ─────────────────────────────────────────────────────────────────────────────
// HELPERS
// ─────────────────────────────────────────────────────────────────────────────

function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// ROUTER
// ─────────────────────────────────────────────────────────────────────────────

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const method = request.method;
    const path = url.pathname;

    if (method === "OPTIONS") {
      return new Response(null, {
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type, X-NOIZY-Key",
        },
      });
    }

    try {

      // ── Health ─────────────────────────────────────────────────────────────
      if (method === "GET" && path === "/health") {
        const tasks = await env.DB.prepare(
          "SELECT COUNT(*) as n FROM audit_log WHERE action LIKE 'gabriel.dispatch%'"
        ).first<{ n: number }>();
        return json({
          status: "LIVE",
          version: "1.0.0",
          service: "gabriel-runtime",
          agents_registered: Object.keys(AGENTS).length,
          agents_live: Object.values(AGENTS).filter(a => a.status === "WORKING_BUT_INTERNAL").length,
          total_dispatches: tasks?.n ?? 0,
          gabriel_api: env.GABRIEL_API_URL ?? "not_configured — set GABRIEL_API_URL secret",
          timestamp: new Date().toISOString(),
        });
      }

      // ── List Agents ────────────────────────────────────────────────────────
      if (method === "GET" && path === "/v1/agents") {
        return json({
          agents: Object.entries(AGENTS).map(([name, info]) => ({
            name,
            ...info,
          })),
          total: Object.keys(AGENTS).length,
          live: Object.values(AGENTS).filter(a => a.status === "WORKING_BUT_INTERNAL").length,
        });
      }

      // ── Dispatch Task ──────────────────────────────────────────────────────
      if (method === "POST" && path === "/v1/dispatch") {
        const body = await request.json() as {
          agent: AgentName;
          task: string;
          input: string;
          priority?: "critical" | "high" | "normal" | "low";
          notify?: boolean;
          dry_run?: boolean;
        };

        if (!body.agent || !body.task || !body.input) {
          return json({ error: "agent, task, input required" }, 400);
        }

        const agentInfo = AGENTS[body.agent];
        if (!agentInfo) {
          return json({ error: `Unknown agent: ${body.agent}. Valid: ${Object.keys(AGENTS).join(", ")}` }, 400);
        }

        if (agentInfo.status === "SPEC_ONLY") {
          return json({
            dispatched: false,
            reason: `Agent ${body.agent} is SPEC_ONLY — not yet implemented`,
            agent: body.agent,
          }, 422);
        }

        const taskId = `TASK-${crypto.randomUUID().slice(0, 16).toUpperCase()}`;
        const now = new Date().toISOString();

        // Log dispatch to audit_log
        await env.DB.prepare(
          `INSERT INTO audit_log (id, actor_type, actor_id, action, object_type, object_id, decision, reason, metadata_json, created_at)
           VALUES (?, 'system', 'gabriel-runtime', 'gabriel.dispatch', 'agent_task', ?, 'ALLOW', ?, ?, ?)`
        ).bind(
          crypto.randomUUID(),
          taskId,
          `Dispatched to ${body.agent}`,
          JSON.stringify({
            agent: body.agent,
            task: body.task,
            priority: body.priority ?? "normal",
            dry_run: body.dry_run ?? false,
          }),
          now
        ).run();

        // Cache task state in KV
        await env.KV_MEMCELL.put(`task:${taskId}`, JSON.stringify({
          task_id: taskId,
          agent: body.agent,
          task: body.task,
          input: body.input,
          status: body.dry_run ? "dry_run" : "dispatched",
          priority: body.priority ?? "normal",
          created_at: now,
          completed_at: null,
          result: null,
        }), { expirationTtl: 86400 }); // 24h TTL

        // If GABRIEL_API_URL is configured, forward to DreamChamber
        let forwarded = false;
        if (env.GABRIEL_API_URL && !body.dry_run) {
          try {
            const forwardRes = await fetch(`${env.GABRIEL_API_URL}/api/gabriel/dispatch`, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                mode: body.agent.toLowerCase(),
                action: body.task,
                input: body.input,
                agent: body.agent,
              }),
              signal: AbortSignal.timeout(5000),
            });
            forwarded = forwardRes.ok;
          } catch {
            // GOD.local not reachable from edge — task is queued
            forwarded = false;
          }
        }

        return json({
          task_id: taskId,
          agent: body.agent,
          agent_role: agentInfo.role,
          status: body.dry_run ? "dry_run" : (forwarded ? "forwarded_to_god_local" : "queued"),
          priority: body.priority ?? "normal",
          dispatched_at: now,
          note: forwarded
            ? `Task forwarded to GABRIEL on GOD.local via ${env.GABRIEL_API_URL}`
            : "Task queued in KV — will execute when GOD.local is reachable",
        }, 201);
      }

      // ── Get Task ───────────────────────────────────────────────────────────
      if (method === "GET" && path.match(/^\/v1\/tasks\/[^/]+$/) &&
          !path.includes("/complete")) {
        const taskId = path.split("/")[3];
        const task = await env.KV_MEMCELL.get(`task:${taskId}`, "json");
        if (!task) return json({ error: "Task not found (may have expired after 24h)" }, 404);
        return json({ task });
      }

      // ── Complete Task ──────────────────────────────────────────────────────
      if (method === "POST" && path.match(/^\/v1\/tasks\/[^/]+\/complete$/)) {
        const taskId = path.split("/")[3];
        const body = await request.json() as { result: unknown; success: boolean };
        const task = await env.KV_MEMCELL.get(`task:${taskId}`, "json") as Record<string, unknown> | null;
        if (!task) return json({ error: "Task not found" }, 404);

        const updated = {
          ...task,
          status: body.success ? "completed" : "failed",
          completed_at: new Date().toISOString(),
          result: body.result,
        };

        await env.KV_MEMCELL.put(`task:${taskId}`, JSON.stringify(updated), { expirationTtl: 86400 });

        return json({ task_id: taskId, status: updated.status, completed_at: updated.completed_at });
      }

      // ── List Recent Tasks ─────────────────────────────────────────────────
      if (method === "GET" && path === "/v1/tasks") {
        const limit = Math.min(parseInt(url.searchParams.get("limit") ?? "20"), 100);
        const logs = await env.DB.prepare(
          `SELECT * FROM audit_log WHERE action = 'gabriel.dispatch'
           ORDER BY created_at DESC LIMIT ?`
        ).bind(limit).all();
        return json({ tasks: logs.results, count: logs.results.length });
      }

      return json({ error: "Not found" }, 404);

    } catch (err) {
      const msg = err instanceof Error ? err.message : "Unknown error";
      console.error("GABRIEL-RUNTIME ERROR:", msg);
      return json({ error: msg }, 500);
    }
  },
};

