/**
 * NOIZYARMY OS — Cloudflare Worker v2.0.0
 *
 * The NOIZY catalog API + Army OS layer.
 * Serves tracks, SFX, and voice catalog with full filtering.
 * Powers the artist storefront, licensing discovery, and sync search.
 *
 * Routes:
 *   GET /                     — API index
 *   GET /health               — System health
 *   GET /catalog/tracks       — Music catalog (filter by category, mood, bpm, key)
 *   GET /catalog/sfx          — SFX catalog (filter by category, tags)
 *   GET /catalog/voice        — Voice catalog
 *   GET /catalog/:id          — Single item
 *   GET /search               — Full-text search across all catalogs
 *   GET /stats                — Catalog statistics
 *
 * Author: RSP_001 — NOIZY.AI
 */

const CORS_HEADERS = {
  "Content-Type": "application/json",
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
  "Cache-Control": "public, max-age=60",
};

function json(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: CORS_HEADERS });
}

function err(msg, status = 400) {
  return json({ error: msg, status }, status);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const method = request.method;
    const path = url.pathname;

    if (method === "OPTIONS") {
      return new Response(null, { headers: CORS_HEADERS });
    }

    if (method !== "GET") return err("Method not allowed", 405);

    try {

      // ── Root ───────────────────────────────────────────────────────────────
      if (path === "/") {
        return json({
          service: "NOIZYARMY OS",
          version: "2.0.0",
          endpoints: [
            "GET /health",
            "GET /catalog/tracks",
            "GET /catalog/sfx",
            "GET /catalog/voice",
            "GET /catalog/:id",
            "GET /search?q=",
            "GET /stats",
          ],
          docs: "https://noizy.ai/api",
        });
      }

      // ── Health ─────────────────────────────────────────────────────────────
      if (path === "/health") {
        let trackCount = 0, sfxCount = 0, voiceCount = 0;
        try {
          const t = await env.DB.prepare("SELECT COUNT(*) as n FROM tracks").first();
          const s = await env.DB.prepare("SELECT COUNT(*) as n FROM sfx").first();
          const v = await env.DB.prepare("SELECT COUNT(*) as n FROM voices").first();
          trackCount = t?.n ?? 0;
          sfxCount = s?.n ?? 0;
          voiceCount = v?.n ?? 0;
        } catch {
          // Tables may not exist yet — that's ok
        }
        return json({
          status: "LIVE",
          version: "2.0.0",
          catalog: { tracks: trackCount, sfx: sfxCount, voice: voiceCount },
          timestamp: new Date().toISOString(),
          owner: "RSP_001 — Robert Stephen Plowman",
          mission: "40 years of original music, SFX, voice — protected and discoverable.",
        });
      }

      // ── Tracks Catalog ─────────────────────────────────────────────────────
      if (path === "/catalog/tracks") {
        const category = url.searchParams.get("category");
        const mood = url.searchParams.get("mood");
        const bpm_min = url.searchParams.get("bpm_min");
        const bpm_max = url.searchParams.get("bpm_max");
        const key = url.searchParams.get("key");
        const limit = Math.min(parseInt(url.searchParams.get("limit") ?? "20"), 100);

        let query = "SELECT * FROM tracks WHERE 1=1";
        const params = [];

        if (category) { query += " AND category = ?"; params.push(category); }
        if (mood) { query += " AND mood = ?"; params.push(mood); }
        if (bpm_min) { query += " AND bpm >= ?"; params.push(parseInt(bpm_min)); }
        if (bpm_max) { query += " AND bpm <= ?"; params.push(parseInt(bpm_max)); }
        if (key) { query += " AND musical_key = ?"; params.push(key); }

        query += " ORDER BY created_at DESC LIMIT ?";
        params.push(limit);

        const result = await env.DB.prepare(query).bind(...params).all();
        return json({
          catalog: "tracks",
          items: result.results,
          count: result.results.length,
          filters: { category, mood, bpm_min, bpm_max, key },
        });
      }

      // ── SFX Catalog ────────────────────────────────────────────────────────
      if (path === "/catalog/sfx") {
        const category = url.searchParams.get("category");
        const tags = url.searchParams.get("tags");
        const limit = Math.min(parseInt(url.searchParams.get("limit") ?? "20"), 100);

        let query = "SELECT * FROM sfx WHERE 1=1";
        const params = [];

        if (category) { query += " AND category = ?"; params.push(category); }
        if (tags) { query += " AND tags LIKE ?"; params.push(`%${tags}%`); }
        query += " ORDER BY created_at DESC LIMIT ?";
        params.push(limit);

        const result = await env.DB.prepare(query).bind(...params).all();
        return json({ catalog: "sfx", items: result.results, count: result.results.length });
      }

      // ── Voice Catalog ──────────────────────────────────────────────────────
      if (path === "/catalog/voice") {
        const limit = Math.min(parseInt(url.searchParams.get("limit") ?? "20"), 100);
        const result = await env.DB.prepare(
          "SELECT * FROM voices ORDER BY created_at DESC LIMIT ?"
        ).bind(limit).all();
        return json({ catalog: "voice", items: result.results, count: result.results.length });
      }

      // ── Single Item ────────────────────────────────────────────────────────
      if (path.match(/^\/catalog\/[^/]+$/) &&
          !["tracks", "sfx", "voice"].includes(path.split("/")[2])) {
        const id = path.split("/")[2];
        // Try each table
        const tables = ["tracks", "sfx", "voices"];
        for (const table of tables) {
          try {
            const item = await env.DB.prepare(
              `SELECT *, '${table}' as catalog_type FROM ${table} WHERE id = ?`
            ).bind(id).first();
            if (item) return json({ item });
          } catch { /* table may not exist */ }
        }
        return err("Item not found", 404);
      }

      // ── Search ─────────────────────────────────────────────────────────────
      if (path === "/search") {
        const q = url.searchParams.get("q");
        if (!q || q.length < 2) return err("q parameter required (min 2 chars)", 400);
        const limit = Math.min(parseInt(url.searchParams.get("limit") ?? "20"), 50);
        const like = `%${q}%`;

        const results = { tracks: [], sfx: [], voice: [] };
        try {
          const t = await env.DB.prepare(
            "SELECT *, 'tracks' as catalog_type FROM tracks WHERE title LIKE ? OR category LIKE ? OR mood LIKE ? LIMIT ?"
          ).bind(like, like, like, limit).all();
          results.tracks = t.results;
        } catch { /* ok */ }

        try {
          const s = await env.DB.prepare(
            "SELECT *, 'sfx' as catalog_type FROM sfx WHERE name LIKE ? OR category LIKE ? OR tags LIKE ? LIMIT ?"
          ).bind(like, like, like, limit).all();
          results.sfx = s.results;
        } catch { /* ok */ }

        const total = results.tracks.length + results.sfx.length + results.voice.length;
        return json({ query: q, total, results });
      }

      // ── Stats ──────────────────────────────────────────────────────────────
      if (path === "/stats") {
        const stats = {};
        const tables = ["tracks", "sfx", "voices"];
        for (const table of tables) {
          try {
            const r = await env.DB.prepare(`SELECT COUNT(*) as n FROM ${table}`).first();
            stats[table] = r?.n ?? 0;
          } catch { stats[table] = 0; }
        }
        return json({ stats, generated_at: new Date().toISOString() });
      }

      return err("Not found", 404);

    } catch (e) {
      console.error("NOIZYARMY OS ERROR:", e.message);
      return err(e.message, 500);
    }
  },
};

