#!/usr/bin/env node
/**
 * GABRIEL MCP Server
 * Exposes GABRIEL AI Orchestration Layer to Windsurf/Cascade as MCP tools.
 *
 * Tools:
 *   gabriel_speak    — Chat with GABRIEL (AI + live Empire context)
 *   gabriel_status   — Gabriel awareness + kernel health
 *   gabriel_announce — TTS only (macOS say)
 *   gabriel_refresh  — Force Heaven17 context refresh
 *
 * Requires DreamChamber running at DREAMCHAMBER_URL (default: http://localhost:7777)
 */

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";

const DREAMCHAMBER_URL = process.env.DREAMCHAMBER_URL || "http://localhost:7777";
const REQUEST_TIMEOUT_MS = 30000;

async function apiCall(method, path, body = null) {
  const url = `${DREAMCHAMBER_URL}${path}`;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  const opts = {
    method,
    headers: { "Content-Type": "application/json" },
    signal: controller.signal,
  };
  if (body) opts.body = JSON.stringify(body);

  try {
    const res = await fetch(url, opts);
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`DreamChamber ${method} ${path} → ${res.status}: ${text.slice(0, 200)}`);
    }
    return res.json();
  } finally {
    clearTimeout(timeout);
  }
}

/** Validate a string argument — reject empty or oversized input */
function requireString(val, name, maxLen = 10000) {
  if (typeof val !== "string" || val.trim().length === 0) {
    throw new Error(`${name} is required and must be a non-empty string`);
  }
  if (val.length > maxLen) {
    throw new Error(`${name} exceeds max length of ${maxLen} characters`);
  }
  return val.trim();
}

const server = new Server(
  { name: "gabriel-mcp", version: "1.1.0" },
  { capabilities: { tools: {} } },
);

server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: [
    {
      name: "gabriel_speak",
      description:
        "Chat with GABRIEL — the AI orchestration layer of the NOIZY Empire. Returns a response grounded in live Heaven17 consent kernel state. Use for questions about the NOIZY Empire, doctrine, consent, Never Clauses, or general AI assistance.",
      inputSchema: {
        type: "object",
        properties: {
          input: {
            type: "string",
            description: "Your message or question to GABRIEL",
          },
          model: {
            type: "string",
            description:
              "Optional: override AI model (e.g. claude-opus-4, claude-sonnet-4)",
          },
          voice: {
            type: "boolean",
            description: "Speak response aloud via macOS TTS (default: false)",
          },
        },
        required: ["input"],
      },
    },
    {
      name: "gabriel_status",
      description:
        "Get GABRIEL's current status — kernel online, context age, active model, voice config, doctrine",
      inputSchema: {
        type: "object",
        properties: {},
      },
    },
    {
      name: "gabriel_announce",
      description: "Speak text aloud via macOS TTS (GABRIEL voice). No AI generation — pure TTS.",
      inputSchema: {
        type: "object",
        properties: {
          text: {
            type: "string",
            description: "Text to speak aloud",
          },
        },
        required: ["text"],
      },
    },
    {
      name: "gabriel_refresh",
      description:
        "Force GABRIEL to refresh its live context from the Heaven17 consent kernel. Use when kernel state has changed and you need fresh data.",
      inputSchema: {
        type: "object",
        properties: {},
      },
    },
  ],
}));

server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params;

  try {
    switch (name) {
      case "gabriel_speak": {
        const input = requireString(args.input, "input");
        const result = await apiCall("POST", "/api/gabriel/speak", {
          input,
          model: args.model,
          voice: args.voice ?? false,
        });
        return {
          content: [
            {
              type: "text",
              text: `**GABRIEL:** ${result.gabriel}\n\n*Model: ${result.metadata?.model || "unknown"} | Kernel: ${result.context?.kernelOnline ? "ONLINE ✓" : "OFFLINE ✗"} | Tokens: ${result.metadata?.tokens?.total ?? "?"}*`,
            },
          ],
        };
      }

      case "gabriel_status": {
        const status = await apiCall("GET", "/api/gabriel/status");
        const lines = [
          `**GABRIEL STATUS**`,
          `Online: ${status.online ? "✓" : "✗"}`,
          `Provider ready: ${status.providerReady ? "✓" : "✗"}`,
          `Kernel online: ${status.kernelOnline ? "✓" : "✗"}`,
          `Model: ${status.model}`,
          `Context age: ${status.contextAge != null ? `${status.contextAge}s` : "never loaded"}`,
          `Voice: ${status.voice?.voice} @ ${status.voice?.rate}wpm`,
          `Doctrine: ${status.doctrine?.join(" | ") || ""}`,
        ];
        return { content: [{ type: "text", text: lines.join("\n") }] };
      }

      case "gabriel_announce": {
        const text = requireString(args.text, "text", 5000);
        await apiCall("POST", "/api/gabriel/announce", { text });
        return {
          content: [{ type: "text", text: `✓ Announced: "${args.text}"` }],
        };
      }

      case "gabriel_refresh": {
        const result = await apiCall("POST", "/api/gabriel/refresh");
        return {
          content: [
            {
              type: "text",
              text: `✓ Context refreshed\nKernel: ${result.context?.kernelOnline ? "ONLINE ✓" : "OFFLINE ✗"}\nRefreshed at: ${result.context?.refreshedAt}`,
            },
          ],
        };
      }

      default:
        throw new Error(`Unknown tool: ${name}`);
    }
  } catch (err) {
    return {
      content: [{ type: "text", text: `**Error:** ${err.message}` }],
      isError: true,
    };
  }
});

const transport = new StdioServerTransport();
await server.connect(transport);

