#!/usr/bin/env node
/**
 * HEAVEN17 MCP Server — NOIZY Consent Kernel
 * Exposes the Heaven17 HVS consent kernel API to Windsurf/Cascade as MCP tools.
 *
 * Tools:
 *   h17_health           — Kernel health + version
 *   h17_gabriel          — Gabriel empire state (public)
 *   h17_actors           — List registered actors
 *   h17_actor            — Get single actor by ID
 *   h17_never_clauses    — Get actor's Never Clauses
 *   h17_consent_tokens   — List consent tokens
 *   h17_stats            — Empire-wide stats
 *   h17_ledger           — Audit ledger entries
 *   h17_rate_table       — Current rate table
 *   h17_union_tiers      — Union tier definitions
 *   h17_kpi              — KPI snapshot (trust/safety/revenue/quality/risk)
 *   h17_audit            — Enterprise audit report
 *
 * Requires: NOIZY_API_KEY env var (X-NOIZY-Key header)
 * URL: HEAVEN17_URL env var (default: https://heaven17.noizylab.workers.dev)
 */

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";

const HEAVEN17_URL = process.env.HEAVEN17_URL || "https://heaven17.noizylab.workers.dev";
const NOIZY_API_KEY = process.env.NOIZY_API_KEY || "";
const REQUEST_TIMEOUT_MS = 15000;

async function h17(path, method = "GET", body = null) {
  const url = `${HEAVEN17_URL}${path}`;
  const headers = { "Content-Type": "application/json" };
  if (NOIZY_API_KEY) headers["X-NOIZY-Key"] = NOIZY_API_KEY;

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  const opts = { method, headers, signal: controller.signal };
  if (body) opts.body = JSON.stringify(body);

  try {
    const res = await fetch(url, opts);
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`Heaven17 ${method} ${path} → ${res.status}: ${text.slice(0, 200)}`);
    }
    return res.json();
  } finally {
    clearTimeout(timeout);
  }
}

/** Validate actor_id — alphanumeric + hyphens + underscores only */
function validateActorId(id) {
  if (typeof id !== "string" || !/^[A-Za-z0-9_-]{1,64}$/.test(id)) {
    throw new Error(`Invalid actor_id: must be 1-64 alphanumeric/underscore/hyphen characters`);
  }
  return id;
}

function formatJson(obj) {
  return "```json\n" + JSON.stringify(obj, null, 2) + "\n```";
}

const server = new Server(
  { name: "heaven17-mcp", version: "1.1.0" },
  { capabilities: { tools: {} } },
);

server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: [
    {
      name: "h17_health",
      description: "Check Heaven17 consent kernel health and version. No auth required.",
      inputSchema: { type: "object", properties: {} },
    },
    {
      name: "h17_gabriel",
