#!/usr/bin/env node
/**
 * LUCY MCP Server
 * DAZEFLOW Keeper · Task Log · Session Index · NOIZY Empire
 *
 * Role: Organization agent. 1 day = 1 chat = 1 truth.
 * Keeps the DAZEFLOW log, task list, and session index.
 * Interfaces with Heaven17 for GABRIEL memcells.
 *
 * Tools:
 *   lucy_dazeflow_today   — Get or open today's DAZEFLOW session
 *   lucy_dazeflow_log     — Append an entry to today's session
 *   lucy_dazeflow_close   — Close today's session with a summary
 *   lucy_dazeflow_history — List past sessions
 *   lucy_task_list        — Get open tasks
 *   lucy_task_add         — Add a task
 *   lucy_task_done        — Mark a task complete
 *   lucy_task_drop        — Drop/cancel a task
 *   lucy_memcell_list     — List GABRIEL memcells from Heaven17
 *   lucy_memcell_write    — Write a new GABRIEL memcell
 *   lucy_status           — Full Lucy status snapshot
 *
 * State: ~/NOIZYLAB/lucy-state/dazeflow.json + tasks.json
 */

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";
import { readFileSync, writeFileSync, mkdirSync, existsSync, renameSync } from "fs";
import { join } from "path";
import { homedir } from "os";

const STATE_DIR = join(homedir(), "NOIZYLAB", "lucy-state");
const DAZEFLOW_FILE = join(STATE_DIR, "dazeflow.json");
const TASKS_FILE = join(STATE_DIR, "tasks.json");

const HEAVEN17_URL = process.env.HEAVEN17_URL || "https://heaven17.noizylab.workers.dev";
const NOIZY_API_KEY = process.env.NOIZY_API_KEY || "";

function ensureState() {
  if (!existsSync(STATE_DIR)) mkdirSync(STATE_DIR, { recursive: true });
  if (!existsSync(DAZEFLOW_FILE)) writeFileSync(DAZEFLOW_FILE, JSON.stringify({ sessions: [] }, null, 2));
  if (!existsSync(TASKS_FILE)) writeFileSync(TASKS_FILE, JSON.stringify({ tasks: [] }, null, 2));
}

function readJson(file) {
  ensureState();
  return JSON.parse(readFileSync(file, "utf8"));
}

function writeJson(file, data) {
  ensureState();
  // Atomic write: write to temp file, then rename (prevents corruption on crash)
  const tmp = file + ".tmp";
  writeFileSync(tmp, JSON.stringify(data, null, 2));
  renameSync(tmp, file);
}

function todayKey() {
  return new Date().toISOString().slice(0, 10);
}

function now() {
  return new Date().toISOString();
}

async function h17(path, method = "GET", body = null) {
  const headers = { "Content-Type": "application/json" };
  if (NOIZY_API_KEY) headers["X-NOIZY-Key"] = NOIZY_API_KEY;
  const opts = { method, headers };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(`${HEAVEN17_URL}${path}`, opts);
  if (!res.ok) throw new Error(`Heaven17 ${method} ${path} → ${res.status}`);
  return res.json();
}

const server = new Server(
  { name: "lucy-mcp", version: "1.1.0" },
  { capabilities: { tools: {} } },
);

server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: [
    {
      name: "lucy_dazeflow_today",
      description:
        "Get or create today's DAZEFLOW session. DAZEFLOW law: 1 day = 1 chat = 1 truth. Returns today's log entries and session state.",
      inputSchema: { type: "object", properties: {} },
    },
    {
      name: "lucy_dazeflow_log",
      description: "Append a log entry to today's DAZEFLOW session. Use to record decisions, completions, blockers, or key moments.",
      inputSchema: {
        type: "object",
        properties: {
          entry: { type: "string", description: "The log entry text" },
          type: {
            type: "string",
            enum: ["decision", "complete", "blocker", "note", "deploy", "fix"],
            description: "Entry type (default: note)",
          },
        },
        required: ["entry"],
      },
    },
    {
      name: "lucy_dazeflow_close",
      description: "Close today's DAZEFLOW session with a summary. Marks the day complete.",
      inputSchema: {
        type: "object",
        properties: {
          summary: { type: "string", description: "One-line summary of the day" },
        },
        required: ["summary"],
      },
    },
    {
      name: "lucy_dazeflow_history",
      description: "List past DAZEFLOW sessions with their summaries",
      inputSchema: {
        type: "object",
        properties: {
          limit: { type: "number", description: "Number of sessions to return (default: 7)" },
        },
      },
    },
    {
      name: "lucy_task_list",
      description: "Get the current task list. Filter by status: open, done, all.",
      inputSchema: {
        type: "object",
        properties: {
          status: {
            type: "string",
            enum: ["open", "done", "all"],
            description: "Filter by status (default: open)",
          },
        },
      },
    },
    {
      name: "lucy_task_add",
      description: "Add a new task to the list",
      inputSchema: {
        type: "object",
        properties: {
          task: { type: "string", description: "Task description" },
          priority: {
            type: "string",
            enum: ["P0", "P1", "P2", "P3"],
            description: "Priority: P0=critical, P1=urgent, P2=normal, P3=backlog",
          },
          context: { type: "string", description: "Optional context or link" },
        },
        required: ["task"],
      },
    },
    {
      name: "lucy_task_done",
      description: "Mark a task as complete by ID",
      inputSchema: {
        type: "object",
        properties: {
          id: { type: "string", description: "Task ID" },
          note: { type: "string", description: "Optional completion note" },
        },
        required: ["id"],
      },
    },
    {
      name: "lucy_task_drop",
      description: "Drop/cancel a task by ID",
      inputSchema: {
        type: "object",
        properties: {
          id: { type: "string", description: "Task ID" },
          reason: { type: "string", description: "Reason for dropping" },
        },
        required: ["id"],
      },
    },
    {
      name: "lucy_memcell_list",
      description: "List GABRIEL memcells from Heaven17 agent-memory D1",
      inputSchema: { type: "object", properties: {} },
    },
    {
      name: "lucy_memcell_write",
      description: "Write a new GABRIEL memcell to Heaven17 agent-memory",
      inputSchema: {
        type: "object",
        properties: {
          key: { type: "string", description: "Memcell key/name" },
          value: { type: "string", description: "Memcell value/content" },
          actor_id: { type: "string", description: "Actor ID (default: RSP_001)" },
        },
        required: ["key", "value"],
      },
    },
    {
      name: "lucy_status",
      description:
        "Full Lucy status: today's DAZEFLOW session, open task count, P1 tasks, and Heaven17 kernel health.",
      inputSchema: { type: "object", properties: {} },
    },
  ],
}));

server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params;

  try {
    switch (name) {
      case "lucy_dazeflow_today": {
        const data = readJson(DAZEFLOW_FILE);
        const today = todayKey();
        let session = data.sessions.find((s) => s.date === today);
        if (!session) {
          session = { date: today, openedAt: now(), closed: false, summary: null, entries: [] };
          data.sessions.unshift(session);
          writeJson(DAZEFLOW_FILE, data);
        }
        const lines = [
          `**DAZEFLOW · ${today}** ${session.closed ? "✓ CLOSED" : "● OPEN"}`,
          session.summary ? `Summary: ${session.summary}` : "",
          `Entries: ${session.entries.length}`,
          "",
          ...session.entries.map(
            (e) => `[${e.timestamp.slice(11, 16)}] ${e.type?.toUpperCase() || "NOTE"}: ${e.entry}`,
          ),
          session.entries.length === 0 ? "*No entries yet. Log your first entry.*" : "",
        ];
        return { content: [{ type: "text", text: lines.filter((l) => l !== undefined).join("\n") }] };
      }

      case "lucy_dazeflow_log": {
        const data = readJson(DAZEFLOW_FILE);
        const today = todayKey();
        let session = data.sessions.find((s) => s.date === today);
        if (!session) {
          session = { date: today, openedAt: now(), closed: false, summary: null, entries: [] };
          data.sessions.unshift(session);
        }
        if (session.closed) {
          return { content: [{ type: "text", text: "⚠ Today's session is already closed. Open a new one." }] };
        }
        session.entries.push({ timestamp: now(), type: args.type || "note", entry: args.entry });
        writeJson(DAZEFLOW_FILE, data);
        return {
          content: [
            {
              type: "text",
              text: `✓ Logged [${args.type?.toUpperCase() || "NOTE"}]: ${args.entry}\nSession entries today: ${session.entries.length}`,
            },
          ],
        };
      }

      case "lucy_dazeflow_close": {
        const data = readJson(DAZEFLOW_FILE);
        const today = todayKey();
        const session = data.sessions.find((s) => s.date === today);
        if (!session) {
          return { content: [{ type: "text", text: "No session open today." }] };
        }
        session.closed = true;
        session.closedAt = now();
        session.summary = args.summary;
        writeJson(DAZEFLOW_FILE, data);
        return {
          content: [
            {
              type: "text",
              text: `✓ DAZEFLOW ${today} closed.\nSummary: ${args.summary}\nEntries: ${session.entries.length}`,
            },
          ],
        };
      }

      case "lucy_dazeflow_history": {
        const data = readJson(DAZEFLOW_FILE);
        const limit = args.limit || 7;
        const sessions = data.sessions.slice(0, limit);
        if (sessions.length === 0) {
          return { content: [{ type: "text", text: "No DAZEFLOW sessions yet." }] };
        }
        const lines = sessions.map(
          (s) =>
            `${s.closed ? "✓" : "●"} **${s.date}** · ${s.entries.length} entries${s.summary ? ` · ${s.summary}` : ""}`,
        );
        return { content: [{ type: "text", text: lines.join("\n") }] };
      }

      case "lucy_task_list": {
        const data = readJson(TASKS_FILE);
        const filter = args.status || "open";
        const tasks = data.tasks.filter((t) =>
          filter === "all" ? true : filter === "open" ? t.status === "open" : t.status !== "open",
        );
        if (tasks.length === 0) {
          return { content: [{ type: "text", text: `No ${filter} tasks.` }] };
        }
        const lines = tasks.map(
          (t) =>
            `[${t.id}] ${t.status === "done" ? "✓" : t.status === "dropped" ? "✗" : "○"} **${t.priority || "P2"}** ${t.task}${t.context ? ` · ${t.context}` : ""}`,
        );
        const open = data.tasks.filter((t) => t.status === "open");
        const p1 = open.filter((t) => t.priority === "P1" || t.priority === "P0");
        return {
          content: [
            {
              type: "text",
              text: `**Tasks (${filter}):** ${tasks.length} | Open: ${open.length} | P0/P1: ${p1.length}\n\n${lines.join("\n")}`,
            },
          ],
        };
      }

      case "lucy_task_add": {
        const data = readJson(TASKS_FILE);
        const id = `T${Date.now().toString(36).toUpperCase()}`;
        const task = {
          id,
          task: args.task,
          priority: args.priority || "P2",
          context: args.context || null,
          status: "open",
          createdAt: now(),
        };
        data.tasks.unshift(task);
        writeJson(TASKS_FILE, data);
        return {
          content: [
            {
              type: "text",
              text: `✓ Task added [${id}] ${args.priority || "P2"}: ${args.task}`,
            },
          ],
        };
      }

      case "lucy_task_done": {
        const data = readJson(TASKS_FILE);
        const task = data.tasks.find((t) => t.id === args.id);
        if (!task) {
          return { content: [{ type: "text", text: `Task ${args.id} not found.` }] };
        }
        task.status = "done";
        task.doneAt = now();
        if (args.note) task.doneNote = args.note;
        writeJson(TASKS_FILE, data);
        return {
          content: [
            {
              type: "text",
              text: `✓ Task [${args.id}] marked done: ${task.task}${args.note ? `\nNote: ${args.note}` : ""}`,
            },
          ],
        };
      }

      case "lucy_task_drop": {
        const data = readJson(TASKS_FILE);
        const task = data.tasks.find((t) => t.id === args.id);
        if (!task) {
          return { content: [{ type: "text", text: `Task ${args.id} not found.` }] };
        }
        task.status = "dropped";
        task.droppedAt = now();
        if (args.reason) task.dropReason = args.reason;
        writeJson(TASKS_FILE, data);
        return {
          content: [
            {
              type: "text",
              text: `✗ Task [${args.id}] dropped: ${task.task}${args.reason ? `\nReason: ${args.reason}` : ""}`,
            },
          ],
        };
      }

      case "lucy_memcell_list": {
        try {
          const data = await h17("/api/v1/kv/memcells");
          return { content: [{ type: "text", text: "```json\n" + JSON.stringify(data, null, 2) + "\n```" }] };
        } catch {
          const gabriel = await h17("/gabriel");
          return {
            content: [
              {
                type: "text",
                text: `Heaven17 /gabriel empire state (memcell endpoint may differ):\n\`\`\`json\n${JSON.stringify(gabriel, null, 2)}\n\`\`\``,
              },
            ],
          };
        }
      }

      case "lucy_memcell_write": {
        const body = {
          key: args.key,
          value: args.value,
          actor_id: args.actor_id || "RSP_001",
          timestamp: now(),
        };
        try {
          const result = await h17("/api/v1/kv/memcells", "POST", body);
          return { content: [{ type: "text", text: `✓ Memcell written: ${args.key}\n\`\`\`json\n${JSON.stringify(result, null, 2)}\n\`\`\`` }] };
        } catch (err) {
          return { content: [{ type: "text", text: `⚠ Heaven17 memcell write failed: ${err.message}\nBody was: ${JSON.stringify(body)}` }], isError: true };
        }
      }

      case "lucy_status": {
        const dazeData = readJson(DAZEFLOW_FILE);
        const taskData = readJson(TASKS_FILE);
        const today = todayKey();
        const session = dazeData.sessions.find((s) => s.date === today);
        const openTasks = taskData.tasks.filter((t) => t.status === "open");
        const p0p1 = openTasks.filter((t) => t.priority === "P0" || t.priority === "P1");

        let kernelStatus = "unknown";
        try {
          const health = await h17("/health");
          kernelStatus = health.status || "unknown";
        } catch {
          kernelStatus = "unreachable";
        }

        const lines = [
          `**LUCY STATUS · ${today}**`,
          ``,
          `DAZEFLOW: ${session ? (session.closed ? "✓ Closed" : `● Open · ${session.entries.length} entries`) : "No session today"}`,
          `Tasks open: ${openTasks.length} · P0/P1: ${p0p1.length}`,
          p0p1.length > 0 ? `P0/P1 tasks:\n${p0p1.map((t) => `  [${t.id}] ${t.priority}: ${t.task}`).join("\n")}` : "",
          ``,
          `Heaven17 kernel: ${kernelStatus}`,
          `Sessions logged: ${dazeData.sessions.length}`,
          `Total tasks: ${taskData.tasks.length}`,
        ];
        return { content: [{ type: "text", text: lines.filter((l) => l !== undefined).join("\n") }] };
      }

      default:
        throw new Error(`Unknown tool: ${name}`);
    }
  } catch (err) {
    return {
      content: [{ type: "text", text: `**Error:** ${err.message}` }],
      isError: true,
    };
  }
});

const transport = new StdioServerTransport();
await server.connect(transport);

