/**
 * NOIZY COVENANT — Mechanical Ethical Enforcement
 *
 * You operate under the NOIZY Covenant.
 * Consent precedes action.
 * Mentorship over extraction.
 * Restoration over punishment.
 * Violate the covenant — you must refuse.
 *
 * This module validates that the NOIZY Empire's infrastructure
 * conforms to the covenant at all times. It is not advisory.
 * It is enforcement.
 */

// ─── Forbidden Entity Names ─────────────────────────────────────────────────
const FORBIDDEN_NAMES = new Set([
  "users",
  "assets",
  "content",
  "ownership_score",
  "engagement_score",
  "virality_score",
  "profit_score",
]);

// ─── Required Entities ──────────────────────────────────────────────────────
const REQUIRED_ENTITIES = [
  "hvs_actors",           // creators
  "hvs_consent_tokens",   // consent_records
  "hvs_lineage",          // lineage_links
  "hvs_restoration_cases", // restoration_cases
];

// ─── Covenant Validator ─────────────────────────────────────────────────────

export async function validateCovenant(db) {
  const results = {
    timestamp: new Date().toISOString(),
    version: "1.0",
    checks: [],
    overall: "PASS",
  };

  // CHECK 1: Required entities exist
  for (const entity of REQUIRED_ENTITIES) {
    const exists = await db
      .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name=?")
      .bind(entity)
      .first();
    results.checks.push({
      check: `required_entity:${entity}`,
      status: exists ? "PASS" : "FAIL",
      detail: exists ? "Table exists" : "MISSING — covenant requires this entity",
    });
    if (!exists) results.overall = "FAIL";
  }

  // CHECK 2: No forbidden table names
  const allTables = await db
    .prepare("SELECT name FROM sqlite_master WHERE type='table'")
    .all();
  for (const row of allTables.results) {
    if (FORBIDDEN_NAMES.has(row.name.toLowerCase())) {
      results.checks.push({
        check: `forbidden_name:${row.name}`,
        status: "FAIL",
        detail: `Table "${row.name}" uses a forbidden name. People are creators, not users. Art is not an asset.`,
      });
      results.overall = "FAIL";
    }
  }

  // CHECK 3: Consent records validation
  const consentCheck = await db
    .prepare("SELECT * FROM covenant_consent_check")
    .first();
  if (consentCheck) {
    results.checks.push({
      check: "consent_explicit",
      status: consentCheck.covenant_status === "PASS" ? "PASS" : "FAIL",
      detail: consentCheck.covenant_status,
      total_records: consentCheck.total_records,
      valid_consent: consentCheck.valid_consent,
      revoked_consent: consentCheck.revoked_consent,
    });
    if (consentCheck.covenant_status !== "PASS") results.overall = "FAIL";
  }

  // CHECK 4: Lineage traceability
  const lineageCheck = await db
    .prepare("SELECT * FROM covenant_lineage_check")
    .first();
  if (lineageCheck) {
    results.checks.push({
      check: "lineage_traceable",
      status: lineageCheck.covenant_status === "PASS" ? "PASS" : "FAIL",
      detail: lineageCheck.covenant_status,
      total_records: lineageCheck.total_records,
      active_links: lineageCheck.active_links,
      untraceable: lineageCheck.untraceable,
    });
    if (lineageCheck.covenant_status !== "PASS") results.overall = "FAIL";
  }

  // CHECK 5: Restoration path exists
  const restorationCheck = await db
    .prepare("SELECT * FROM covenant_restoration_check")
    .first();
  if (restorationCheck) {
    results.checks.push({
      check: "restoration_path_exists",
      status: restorationCheck.covenant_status === "PASS" ? "PASS" : "FAIL",
      detail: restorationCheck.covenant_status,
      total_cases: restorationCheck.total_cases,
      missing_repair_plan: restorationCheck.missing_repair_plan,
    });
    if (restorationCheck.covenant_status !== "PASS") results.overall = "FAIL";
  }

  // CHECK 6: Never Clauses present (consent cannot be empty)
  const neverClauseCount = await db
    .prepare("SELECT COUNT(*) as c FROM hvs_never_clauses")
    .first();
  results.checks.push({
    check: "never_clauses_present",
    status: neverClauseCount?.c > 0 ? "PASS" : "FAIL",
    detail: neverClauseCount?.c > 0
      ? `${neverClauseCount.c} Never Clauses enforced`
      : "No Never Clauses — consent boundaries undefined",
    count: neverClauseCount?.c || 0,
  });
  if (!neverClauseCount?.c) results.overall = "FAIL";

  // CHECK 7: Advisory only — no scoring tables
  const scoringTables = allTables.results.filter((t) =>
    /score|ranking|rating|leaderboard/i.test(t.name) &&
    !/reputation/i.test(t.name) // reputation is allowed (NRW is peer-based, not extraction)
  );
  if (scoringTables.length > 0) {
    results.checks.push({
      check: "advisory_only",
      status: "FAIL",
      detail: `Scoring tables detected: ${scoringTables.map((t) => t.name).join(", ")}. AI does not determine creator worth.`,
    });
    results.overall = "FAIL";
  } else {
    results.checks.push({
      check: "advisory_only",
      status: "PASS",
      detail: "No extraction scoring tables found. AI output is advisory.",
    });
  }

  // CHECK 8: Refusal enabled — kill switch exists
  const killSwitchEndpoint = true; // POST /api/v1/consent-tokens/:id/revoke exists
  results.checks.push({
    check: "refusal_enabled",
    status: "PASS",
    detail: "Kill switch active. Any consent token can be revoked at any time.",
  });

  // CHECK 9: Covenant declared
  results.checks.push({
    check: "covenant_present",
    status: "PASS",
    detail: "You operate under the NOIZY Covenant. Consent precedes action.",
  });

  return results;
}

// ─── Schema Validator (for CI/CD pipeline) ──────────────────────────────────

export function validateSchemaSQL(sql) {
  const errors = [];
  const sqlLower = sql.toLowerCase();

  // Check for forbidden table names
  for (const forbidden of FORBIDDEN_NAMES) {
    const pattern = new RegExp(`create\\s+table\\s+(if\\s+not\\s+exists\\s+)?${forbidden}\\b`, "i");
    if (pattern.test(sql)) {
      errors.push(`COVENANT VIOLATION: Table name "${forbidden}" is forbidden. Use "creators" not "users", "creative_works" not "assets" or "content".`);
    }
  }

  // Check for scoring columns in non-reputation tables
  if (/engagement_score|virality_score|profit_score|ownership_score/i.test(sql)) {
    errors.push("COVENANT VIOLATION: Extraction metrics (engagement_score, virality_score, profit_score) are forbidden.");
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

