      <h2>Estates — 100-Year Preservation <span class="count">(${est.length})</span></h2>
      ${est.length ? `<table>
        <tr><th>Estate ID</th><th>Actor</th><th>Standard</th><th>Retention</th><th>Trustee</th><th>Status</th></tr>
        ${est.map(e => `
        <tr>
          <td><code>${esc(e.estate_id)}</code></td>
          <td>${esc(e.actor_id)}</td>
          <td>${esc(e.preservation_standard)}</td>
          <td>${e.retention_years} years</td>
