  <h2>Rate Table <span class="count">(${rt.length} categories)</span></h2>
  <table>
    <tr><th>Category</th><th>Base Fee (CAD)</th><th>Per Minute (CAD)</th><th>Description</th></tr>
    ${
      rt
        .map(
          (r) => `
    <tr>
      <td><strong>${esc(r.use_category)}</strong></td>
      <td>$${r.base_fee_cad.toFixed(2)}</td>
      <td>$${r.per_minute_cad.toFixed(2)}</td>
      <td>${esc(r.description)}</td>
    </tr>`,
        )
        .join("") || '<tr><td colspan="4">No rates configured</td></tr>'
    }
  </table>
</div>

<div class="footer">
  HEAVEN17 v${esc(health.version) || "17.0.0"} — NOIZY.AI — ${health.timestamp || ""}<br>
  <a href="/health">API Health</a> · <a href="/api/v1/stats">Stats JSON</a> · <a href="/">Endpoints</a><br>
  <span style="color:#222">Consent is law. Provenance is default. Revocation is sacred.</span>
</div>

<script>
  // Auto-refresh every 60 seconds
  setTimeout(() => location.reload(), 60000);
</script>

</body>
</html>`;
}

