            }
        }

    def analyze_query_intent(self, query: str) -> Dict[str, float]:
        """Analyze query to determine intent and complexity"""

        intent_scores = {
            "coding": 0.0,
            "analysis": 0.0,
            "creative": 0.0,
            "simple": 0.0,
            "research": 0.0,
            "multilingual": 0.0
        }

        query_lower = query.lower()

        # Coding indicators
        coding_keywords = ["code", "programming", "function", "algorithm", "debug", "python", "javascript", "sql"]
        intent_scores["coding"] = sum(1 for keyword in coding_keywords if keyword in query_lower) / len(coding_keywords)

        # Analysis indicators
        analysis_keywords = ["analyze", "compare", "evaluate", "assess", "review", "examine"]
        intent_scores["analysis"] = sum(1 for keyword in analysis_keywords if keyword in query_lower) / len(analysis_keywords)

        # Creative indicators
        creative_keywords = ["write", "create", "story", "poem", "creative", "imagine", "design"]
        intent_scores["creative"] = sum(1 for keyword in creative_keywords if keyword in query_lower) / len(creative_keywords)

        # Simple task indicators
        simple_keywords = ["what", "how", "when", "where", "quick", "simple"]
        intent_scores["simple"] = sum(1 for keyword in simple_keywords if keyword in query_lower) / len(simple_keywords)

        # Research indicators
        research_keywords = ["research", "study", "investigate", "explore", "detailed", "comprehensive"]
        intent_scores["research"] = sum(1 for keyword in research_keywords if keyword in query_lower) / len(research_keywords)

        # Multilingual indicators
        multilingual_keywords = ["translate", "language", "español", "français", "deutsch", "中文", "日本語"]
        intent_scores["multilingual"] = sum(1 for keyword in multilingual_keywords if keyword in query_lower) / len(multilingual_keywords)

        # Query length factor
        if len(query) > 500:
            intent_scores["analysis"] += 0.3
            intent_scores["research"] += 0.3
        elif len(query) < 100:
            intent_scores["simple"] += 0.4

        return intent_scores

    def select_optimal_model(self, query: str, user_tier: str, context: str = "general") -> str:
        """Select optimal model based on query analysis and user tier"""

        intent_scores = self.analyze_query_intent(query)
        available_models = [model for model, config in self.model_configs.items() 
                          if self.check_user_access(user_tier, config["tier_required"])]

        if not available_models:
            return "claude-haiku"  # Fallback

        # Score each available model
        model_scores = {}

        for model in available_models:
            config = self.model_configs[model]
            score = 0.0

            # Match strengths with intent
            for strength in config["strengths"]:
                if strength in intent_scores:
                    score += intent_scores[strength] * 2
                elif strength == "balanced":
                    score += sum(intent_scores.values()) / len(intent_scores)
                elif strength == "cost_effective" and user_tier == "free":
                    score += 1.0
                elif strength == "enterprise" and user_tier in ["premium", "admin"]:
                    score += 0.5

            # Adjust for context
            if context == "thread" and config["speed"] == "fast":
                score += 0.3
            elif context == "dm" and "chat" in config["strengths"]:
                score += 0.2

            # Cost consideration for non-admin users
            if user_tier != "admin":
                score -= config["cost_per_1k"] * 100  # Penalize expensive models

            model_scores[model] = score

        # Return highest scoring model
        return max(model_scores.items(), key=lambda x: x[1])[0]

    def check_user_access(self, user_tier: str, required_tier: str) -> bool:
        """Check if user has access to model tier"""
        tier_hierarchy = {"free": 0, "premium": 1, "admin": 2}
        return tier_hierarchy.get(user_tier, 0) >= tier_hierarchy.get(required_tier, 0)

router = EnterpriseAIRouter()

def get_user_tier(user_id: str) -> str:
    """Determine user access tier"""
    if user_id in config.admin_users:
        return "admin"
    elif user_id in config.premium_users:
        return "premium"
    else:
        return "free"

def check_cooldown(user_id: str) -> tuple[bool, float]:
    """Check if user is on cooldown"""
    current_time = time.time()
    if user_id in user_last_request:
        time_diff = current_time - user_last_request[user_id]
        if time_diff < config.cooldown_seconds:
            return False, config.cooldown_seconds - time_diff

    user_last_request[user_id] = current_time
    return True, 0

async def query_ai_model(model: str, query: str, user_id: str) -> tuple[str, float, Dict]:
    """Query AI model and return response with metadata"""

    try:
        model_config = router.model_configs[model]

        if model.startswith("claude"):
            message = claude_client.messages.create(
                model=model_config["model_id"],
                max_tokens=config.max_tokens,
                messages=[{"role": "user", "content": query}]
            )

            response = message.content[0].text
            cost = (message.usage.input_tokens + message.usage.output_tokens) * model_config["cost_per_1k"] / 1000

            metadata = {
                "input_tokens": message.usage.input_tokens,
                "output_tokens": message.usage.output_tokens,
                "model": model_config["model_id"]
            }

            usage_stats["cost_tracking"]["claude"] += cost

        elif model.startswith("cohere"):
            response_obj = cohere_client.chat(
                model=model_config["model_id"],
                message=query,
                max_tokens=config.max_tokens
            )

            response = response_obj.text
            estimated_tokens = len(query.split()) * 1.3 + len(response.split()) * 1.3
            cost = estimated_tokens * model_config["cost_per_1k"] / 1000

            metadata = {
                "estimated_tokens": estimated_tokens,
                "model": model_config["model_id"]
            }

            usage_stats["cost_tracking"]["cohere"] += cost

        elif model.startswith("gpt"):
            completion = openai_client.chat.completions.create(
                model=model_config["model_id"],
                messages=[{"role": "user", "content": query}],
                max_tokens=config.max_tokens
            )

            response = completion.choices[0].message.content
            cost = (completion.usage.prompt_tokens + completion.usage.completion_tokens) * model_config["cost_per_1k"] / 1000

            metadata = {
                "prompt_tokens": completion.usage.prompt_tokens,
                "completion_tokens": completion.usage.completion_tokens,
                "model": model_config["model_id"]
            }

            usage_stats["cost_tracking"]["openai"] += cost

        # Track usage
        usage_stats["model_usage"][model] = usage_stats["model_usage"].get(model, 0) + 1
        usage_stats["user_requests"][user_id] = usage_stats["user_requests"].get(user_id, 0) + 1
        usage_stats["total_requests"] += 1

        return response, cost, metadata

    except Exception as e:
        logger.error(f"Error querying {model}: {e}")
        return f"Error with {model}: {str(e)}", 0.0, {}

