    required_vars = ["SLACK_BOT_TOKEN", "SLACK_SIGNING_SECRET", "SLACK_APP_TOKEN", 
                    "ANTHROPIC_API_KEY", "COHERE_API_KEY"]
    missing_vars = [var for var in required_vars if not getattr(config, var.lower().replace('_', '_'))]

    if missing_vars:
