// NOIZYKit.swift — Main entry point + configuration
// NOIZY Swift SDK v2.0.0
// "Consent as executable code. Provenance as default. Revocation as sacred."

import Foundation

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Configuration
// ─────────────────────────────────────────────────────────────────────────────

public struct NOIZYConfiguration: Sendable {
    public let heaven17URL: URL
    public let consentGatewayURL: URL
    public let royaltyRouterURL: URL
    public let proofManifestURL: URL
    public let gabrielRuntimeURL: URL
    public let apiKey: String
    public let actorID: String
    public let timeoutInterval: TimeInterval

    public init(
        heaven17URL: URL = URL(string: "https://heaven17.rsplowman.workers.dev")!,
        consentGatewayURL: URL = URL(string: "https://consent-gateway.noizylab.workers.dev")!,
        royaltyRouterURL: URL = URL(string: "https://royalty-router.noizylab.workers.dev")!,
        proofManifestURL: URL = URL(string: "https://proof-manifest.noizylab.workers.dev")!,
        gabrielRuntimeURL: URL = URL(string: "https://gabriel-runtime.noizylab.workers.dev")!,
        apiKey: String,
        actorID: String = "RSP_001",
        timeoutInterval: TimeInterval = 15
    ) {
        self.heaven17URL = heaven17URL
        self.consentGatewayURL = consentGatewayURL
        self.royaltyRouterURL = royaltyRouterURL
        self.proofManifestURL = proofManifestURL
        self.gabrielRuntimeURL = gabrielRuntimeURL
        self.apiKey = apiKey
        self.actorID = actorID
        self.timeoutInterval = timeoutInterval
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — NOIZY Client (main entry point)
// ─────────────────────────────────────────────────────────────────────────────

@MainActor
public final class NOIZYClient: ObservableObject {

    public let config: NOIZYConfiguration
    public let heaven17: Heaven17Client
    public let consent: ConsentClient
    public let royalty: RoyaltyClient
    public let proof: ProofClient
    public let gabriel: GabrielClient
    public let voice: VoiceCapture

    @Published public var isConnected: Bool = false
    @Published public var systemHealth: NOIZYHealth?
    @Published public var lastError: NOIZYError?

    public init(config: NOIZYConfiguration) {
        self.config = config
        let session = URLSession.shared
        self.heaven17 = Heaven17Client(baseURL: config.heaven17URL, apiKey: config.apiKey, session: session, timeout: config.timeoutInterval)
        self.consent = ConsentClient(baseURL: config.consentGatewayURL, apiKey: config.apiKey, session: session, timeout: config.timeoutInterval)
        self.royalty = RoyaltyClient(baseURL: config.royaltyRouterURL, apiKey: config.apiKey, session: session, timeout: config.timeoutInterval)
        self.proof = ProofClient(baseURL: config.proofManifestURL, apiKey: config.apiKey, session: session, timeout: config.timeoutInterval)
        self.gabriel = GabrielClient(baseURL: config.gabrielRuntimeURL, apiKey: config.apiKey, session: session, timeout: config.timeoutInterval)
        self.voice = VoiceCapture()
    }

    /// Check health of all NOIZY services
    public func checkHealth() async {
        do {
            let health = try await heaven17.health()
            await MainActor.run {
                self.systemHealth = health
                self.isConnected = health.status == "LIVE"
            }
        } catch {
            await MainActor.run {
                self.lastError = NOIZYError.networkError(error.localizedDescription)
                self.isConnected = false
            }
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Shared Models
// ─────────────────────────────────────────────────────────────────────────────

public struct NOIZYHealth: Codable, Sendable {
    public let status: String
    public let version: String?
    public let timestamp: String
    public let actors: Int?
    public let ledgerEvents: Int?
    public let mission: String?

    enum CodingKeys: String, CodingKey {
        case status, version, timestamp, actors, mission
        case ledgerEvents = "ledger_events"
    }
}

public enum NOIZYError: Error, LocalizedError, Sendable {
    case networkError(String)
    case authenticationFailed
    case consentDenied(String)
    case neverClauseViolation(String)
    case notFound(String)
    case serverError(Int, String)
    case decodingError(String)

    public var errorDescription: String? {
        switch self {
        case .networkError(let msg):       return "Network error: \(msg)"
        case .authenticationFailed:        return "Authentication failed — check NOIZY_API_KEY"
        case .consentDenied(let reason):   return "Consent denied: \(reason)"
        case .neverClauseViolation(let nc): return "Never Clause \(nc) prohibits this action"
        case .notFound(let item):          return "\(item) not found"
        case .serverError(let code, let msg): return "Server error \(code): \(msg)"
        case .decodingError(let msg):      return "Decoding error: \(msg)"
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Base HTTP Client
// ─────────────────────────────────────────────────────────────────────────────

public class NOIZYHTTPClient: @unchecked Sendable {
    let baseURL: URL
    let apiKey: String
    let session: URLSession
    let timeout: TimeInterval
    let decoder: JSONDecoder

    init(baseURL: URL, apiKey: String, session: URLSession, timeout: TimeInterval) {
        self.baseURL = baseURL
        self.apiKey = apiKey
        self.session = session
        self.timeout = timeout
        self.decoder = JSONDecoder()
        self.decoder.keyDecodingStrategy = .convertFromSnakeCase
    }

    func request<T: Decodable>(
        method: String = "GET",
        path: String,
        body: (any Encodable)? = nil
    ) async throws -> T {
        guard let url = URL(string: path, relativeTo: baseURL) else {
            throw NOIZYError.networkError("Invalid URL: \(path)")
        }

        var req = URLRequest(url: url, timeoutInterval: timeout)
        req.httpMethod = method
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        if !apiKey.isEmpty {
            req.setValue(apiKey, forHTTPHeaderField: "X-NOIZY-Key")
        }

        if let body {
            req.httpBody = try JSONEncoder().encode(body)
        }

        let (data, response) = try await session.data(for: req)

        guard let http = response as? HTTPURLResponse else {
            throw NOIZYError.networkError("No HTTP response")
        }

        switch http.statusCode {
        case 200...299:
            do {
                return try decoder.decode(T.self, from: data)
            } catch {
                throw NOIZYError.decodingError(error.localizedDescription)
            }
        case 401:
            throw NOIZYError.authenticationFailed
        case 403:
            let msg = (try? JSONDecoder().decode([String: String].self, from: data))?["reason"] ?? "Forbidden"
            if msg.contains("Never Clause") || msg.contains("NC_") {
                throw NOIZYError.neverClauseViolation(msg)
            }
            throw NOIZYError.consentDenied(msg)
        case 404:
            throw NOIZYError.notFound(path)
        default:
            let msg = String(data: data, encoding: .utf8) ?? "Unknown error"
            throw NOIZYError.serverError(http.statusCode, msg)
        }
    }
}

// Heaven17Client.swift — Consent kernel API client
// Full Swift wrapper for the Heaven17 Cloudflare Worker

import Foundation

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Models
// ─────────────────────────────────────────────────────────────────────────────

public struct NOIZYActor: Codable, Identifiable, Sendable {
    public var id: String { actorId }
    public let actorId: String
    public let displayName: String
    public let legalName: String?
    public let email: String?
    public let country: String
    public let isFounding: Bool
    public let unionMember: Bool?
    public let status: String
    public let onboardedAt: String?
}

public struct ConsentToken: Codable, Identifiable, Sendable {
    public var id: String { tokenId }
    public let tokenId: String
    public let actorId: String
    public let useCategoriesJson: String?
    public let territoriesJson: String?
    public let status: String
    public let issuedAt: String?
    public let expiresAt: String?
    public let revokedAt: String?
}

public struct SynthRequest: Codable, Sendable {
    public let actorId: String
    public let descendantId: String
    public let consentTokenId: String
    public let useCategory: String
    public let scriptHash: String
}

public struct SynthResult: Codable, Sendable {
    public let status: String
    public let requestId: String?
    public let neverClauseCheck: String?
    public let blockedBy: String?
    public let message: String
}

public struct NeverClause: Codable, Identifiable, Sendable {
    public var id: String { code }
    public let code: String
    public let status: String
}

public struct VoiceDNARecord: Codable, Sendable {
    public let dnaId: String
    public let actorId: String
    public let recordingHash: String
    public let durationSeconds: Double
    public let sampleRate: Int
    public let registeredAt: String?
}

struct H17Wrapper<T: Decodable>: Decodable {
    let actor: T?
    let actors: [T]?
    let consentToken: T?
    let consentTokens: [T]?
    let neverClauses: [NeverClause]?
    let status: String?
    let requestId: String?
    let neverClauseCheck: String?
    let blockedBy: String?
    let message: String?
    let tokenId: String?
    let revokedAt: String?
    let dnaId: String?

    enum CodingKeys: String, CodingKey {
        case actor, actors, status, message
        case consentToken = "consent_token"
        case consentTokens = "consent_tokens"
        case neverClauses = "never_clauses"
        case requestId = "request_id"
        case neverClauseCheck = "never_clause_check"
        case blockedBy = "blocked_by"
        case tokenId = "token_id"
        case revokedAt = "revoked_at"
        case dnaId = "dna_id"
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Heaven17 Client
// ─────────────────────────────────────────────────────────────────────────────

public final class Heaven17Client: NOIZYHTTPClient {

    // ── Health ────────────────────────────────────────────────────────────────
    public func health() async throws -> NOIZYHealth {
        return try await request(path: "/health")
    }

    // ── Actors ────────────────────────────────────────────────────────────────
    public func getActor(id: String) async throws -> NOIZYActor {
        struct Response: Decodable { let actor: NOIZYActor }
        let res: Response = try await request(path: "/api/v1/actors/\(id)")
        return res.actor
    }

    public func createActor(
        actorId: String,
        displayName: String,
        legalName: String,
        email: String,
        country: String = "CA",
        isFounding: Bool = false
    ) async throws -> NOIZYActor {
        struct Body: Encodable {
            let actor_id: String
            let display_name: String
            let legal_name: String
            let email: String
            let country: String
            let is_founding: Bool
        }
        struct Response: Decodable { let actor: NOIZYActor }
        let body = Body(
            actor_id: actorId,
            display_name: displayName,
            legal_name: legalName,
            email: email,
            country: country,
            is_founding: isFounding
        )
        let res: Response = try await request(method: "POST", path: "/api/v1/actors", body: body)
        return res.actor
    }

    // ── Consent Tokens ────────────────────────────────────────────────────────
    public func issueConsentToken(
        actorId: String,
        useCategories: [String],
        territories: [String] = ["GLOBAL"],
        languages: [String] = ["en"],
        expiresAt: String? = nil
    ) async throws -> ConsentToken {
        struct Body: Encodable {
            let actor_id: String
            let use_categories: [String]
            let territories: [String]
            let languages: [String]
            let expires_at: String?
        }
        struct Response: Decodable { let consent_token: ConsentToken }
        let body = Body(
            actor_id: actorId,
            use_categories: useCategories,
            territories: territories,
            languages: languages,
            expires_at: expiresAt
        )
        let res: Response = try await request(method: "POST", path: "/api/v1/consent-tokens", body: body)
        return res.consent_token
    }

    public func revokeConsentToken(tokenId: String, reason: String) async throws -> String {
        struct Body: Encodable { let reason: String }
        struct Response: Decodable { let status: String; let message: String }
        let res: Response = try await request(method: "POST", path: "/api/v1/consent-tokens/\(tokenId)/revoke", body: Body(reason: reason))
        return res.message
    }

    // ── Synth Requests ────────────────────────────────────────────────────────
    public func requestSynthesis(_ req: SynthRequest) async throws -> SynthResult {
        struct Body: Encodable {
            let actor_id: String
            let descendant_id: String
            let consent_token_id: String
            let use_category: String
            let script_hash: String
        }
        let body = Body(
            actor_id: req.actorId,
            descendant_id: req.descendantId,
            consent_token_id: req.consentTokenId,
            use_category: req.useCategory,
            script_hash: req.scriptHash
        )
        return try await request(method: "POST", path: "/api/v1/synth-requests", body: body)
    }

    // ── Voice DNA ─────────────────────────────────────────────────────────────
    public func registerVoiceDNA(
        actorId: String,
        dnaId: String,
        recordingHash: String,
        durationSeconds: Double,
        sampleRate: Int = 48000
    ) async throws -> VoiceDNARecord {
        struct Body: Encodable {
            let dna_id: String
            let recording_hash: String
            let duration_seconds: Double
            let sample_rate: Int
        }
        struct Response: Decodable { let dna_id: String; let actor_id: String; let registered_at: String? }
        let body = Body(
            dna_id: dnaId,
            recording_hash: recordingHash,
            duration_seconds: durationSeconds,
            sample_rate: sampleRate
        )
        let res: Response = try await request(method: "POST", path: "/api/v1/actors/\(actorId)/voice-dna", body: body)
        return VoiceDNARecord(
            dnaId: res.dna_id,
            actorId: actorId,
            recordingHash: recordingHash,
            durationSeconds: durationSeconds,
            sampleRate: sampleRate,
            registeredAt: res.registered_at
        )
    }

    // ── Never Clauses ─────────────────────────────────────────────────────────
    public func getNeverClauses() async throws -> [NeverClause] {
        struct Response: Decodable { let never_clauses: [NeverClause] }
        let res: Response = try await request(path: "/api/v1/never-clauses")
        return res.never_clauses
    }

    // ── Ledger ────────────────────────────────────────────────────────────────
    public func getLedger(actorId: String? = nil, limit: Int = 20) async throws -> [[String: String]] {
        var path = "/api/v1/ledger?limit=\(limit)"
        if let actorId { path += "&actor_id=\(actorId)" }
        struct Response: Decodable { let events: [[String: String]]? }
        let res: Response = try await request(path: path)
        return res.events ?? []
    }
}

// ConsentManager.swift — iOS consent enforcement + voice sovereignty manager
// The iOS layer of the NOIZY consent pipeline

import Foundation
import Combine

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Consent Models
// ─────────────────────────────────────────────────────────────────────────────

public struct EligibilityRequest: Codable, Sendable {
    public let creatorId: String
    public let claimantId: String
    public let actionType: String
    public let toolName: String
    public let requestedScope: RequestedScope
    public let requestedAt: String

    public init(
        creatorId: String,
        claimantId: String,
        actionType: String,
        toolName: String,
        media: String? = nil,
        channel: String? = nil,
        territory: String? = nil
    ) {
        self.creatorId = creatorId
        self.claimantId = claimantId
        self.actionType = actionType
        self.toolName = toolName
        self.requestedScope = RequestedScope(media: media, channel: channel, territory: territory)
        self.requestedAt = ISO8601DateFormatter().string(from: Date())
    }

    enum CodingKeys: String, CodingKey {
        case creatorId = "creator_id"
        case claimantId = "claimant_id"
        case actionType = "action_type"
        case toolName = "tool_name"
        case requestedScope = "requested_scope"
        case requestedAt = "requested_at"
    }
}

public struct RequestedScope: Codable, Sendable {
    public let media: String?
    public let channel: String?
    public let territory: String?
}

public enum ConsentDecision: String, Codable, Sendable {
    case allow = "ALLOW"
    case hold = "HOLD"
    case deny = "DENY"
    case escalate = "ESCALATE"
}

public struct EligibilityResponse: Codable, Sendable {
    public let decision: ConsentDecision
    public let reasonCodes: [String]
    public let consentRecordId: String?
    public let provenanceRequired: Bool?
    public let royaltyRouteStatus: String?
    public let missingRequirements: [String]?

    enum CodingKeys: String, CodingKey {
        case decision
        case reasonCodes = "reason_codes"
        case consentRecordId = "consent_record_id"
        case provenanceRequired = "provenance_required"
        case royaltyRouteStatus = "royalty_route_status"
        case missingRequirements = "missing_requirements"
    }

    public var isAllowed: Bool { decision == .allow }
}

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Consent Client
// ─────────────────────────────────────────────────────────────────────────────

public final class ConsentClient: NOIZYHTTPClient {

    public func checkEligibility(_ req: EligibilityRequest) async throws -> EligibilityResponse {
        struct Wrapper: Decodable { let data: EligibilityResponse }
        let wrapper: Wrapper = try await request(method: "POST", path: "/v1/check-eligibility", body: req)
        return wrapper.data
    }

    /// Convenience: check and throw if not ALLOW
    @discardableResult
    public func requireConsent(_ req: EligibilityRequest) async throws -> EligibilityResponse {
        let result = try await checkEligibility(req)
        guard result.isAllowed else {
            let reason = result.missingRequirements?.first ?? result.reasonCodes.first ?? "Consent denied"
            throw NOIZYError.consentDenied(reason)
        }
        return result
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Consent Manager (SwiftUI observable)
// ─────────────────────────────────────────────────────────────────────────────

@MainActor
public final class ConsentManager: ObservableObject {

    private let heaven17: Heaven17Client
    private let consentClient: ConsentClient
    private let actorId: String

    @Published public var activeToken: ConsentToken?
    @Published public var consentState: ConsentState = .unknown
    @Published public var neverClauses: [NeverClause] = []

    public enum ConsentState: Equatable {
        case unknown
        case checking
        case active(tokenId: String)
        case denied(reason: String)
        case revoked
        case expired
    }

    public init(heaven17: Heaven17Client, consentClient: ConsentClient, actorId: String) {
        self.heaven17 = heaven17
        self.consentClient = consentClient
        self.actorId = actorId
    }

    // ── Load Never Clauses ────────────────────────────────────────────────────
    public func loadNeverClauses() async {
        do {
            neverClauses = try await heaven17.getNeverClauses()
        } catch {
            // Non-fatal — clauses are enforced server-side regardless
        }
    }

    // ── Issue Consent Token ───────────────────────────────────────────────────
    public func issueToken(
        categories: [String] = ["educational", "commercial"],
        territories: [String] = ["GLOBAL"],
        expiresAt: String? = nil
    ) async throws -> ConsentToken {
        consentState = .checking
        do {
            let token = try await heaven17.issueConsentToken(
                actorId: actorId,
                useCategories: categories,
                territories: territories,
                expiresAt: expiresAt
            )
            activeToken = token
            consentState = .active(tokenId: token.tokenId)
            return token
        } catch {
            consentState = .denied(reason: error.localizedDescription)
            throw error
        }
    }

    // ── Kill Switch ───────────────────────────────────────────────────────────
    public func activateKillSwitch(reason: String) async throws {
        guard let token = activeToken else { return }
        _ = try await heaven17.revokeConsentToken(tokenId: token.tokenId, reason: reason)
        activeToken = nil
        consentState = .revoked
    }

    // ── Check Eligibility Before Any Action ───────────────────────────────────
    public func canProceed(action: String, tool: String) async -> Bool {
        guard let token = activeToken else { return false }
        let req = EligibilityRequest(
            creatorId: actorId,
            claimantId: "NOIZY_iOS",
            actionType: action,
            toolName: tool
        )
        do {
            let result = try await consentClient.checkEligibility(req)
            return result.isAllowed
        } catch {
            return false
        }
    }
}

// VoiceCapture.swift — On-device voice capture + WhisperKit transcription
// Feeds the NOIZY voice sovereignty pipeline from iOS

import Foundation
import AVFoundation
#if canImport(WhisperKit)
import WhisperKit
#endif

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Voice Capture State
// ─────────────────────────────────────────────────────────────────────────────

public enum VoiceCaptureState: Equatable, Sendable {
    case idle
    case requestingPermission
    case ready
    case recording(duration: TimeInterval)
    case transcribing
    case complete(transcript: String, audioURL: URL)
    case error(String)
}

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Voice Capture
// ─────────────────────────────────────────────────────────────────────────────

@MainActor
public final class VoiceCapture: NSObject, ObservableObject {

    @Published public var state: VoiceCaptureState = .idle
    @Published public var transcript: String = ""
    @Published public var audioLevel: Float = 0.0
    @Published public var recordingDuration: TimeInterval = 0

    private var audioEngine: AVAudioEngine?
    private var audioFile: AVAudioFile?
    private var recordingURL: URL?
    private var durationTimer: Timer?
    private var recordingStartTime: Date?

    #if canImport(WhisperKit)
    private var whisper: WhisperKit?
    #endif

    public override init() {
        super.init()
    }

    // ── Permissions ───────────────────────────────────────────────────────────
    public func requestPermission() async -> Bool {
        state = .requestingPermission
        #if os(iOS)
        let granted = await AVAudioApplication.requestRecordPermission()
        state = granted ? .ready : .error("Microphone permission denied")
        return granted
        #else
        state = .ready
        return true
        #endif
    }

    // ── WhisperKit Setup ──────────────────────────────────────────────────────
    public func setupWhisper(modelSize: String = "base") async {
        #if canImport(WhisperKit)
        do {
            whisper = try await WhisperKit(modelSize)
        } catch {
            // Whisper unavailable — will fall back to server-side transcription
        }
        #endif
    }

    // ── Recording ─────────────────────────────────────────────────────────────
    public func startRecording() throws {
        guard case .ready = state else {
            throw NSError(domain: "NOIZYVoice", code: 1, userInfo: [NSLocalizedDescriptionKey: "Not ready — call requestPermission() first"])
        }

        let session = AVAudioSession.sharedInstance()
        try session.setCategory(.record, mode: .measurement, options: .duckOthers)
        try session.setActive(true, options: .notifyOthersOnDeactivation)

        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent("noizy_voice_\(Date().timeIntervalSince1970)")
            .appendingPathExtension("wav")

        recordingURL = url
        audioEngine = AVAudioEngine()

        guard let engine = audioEngine else { return }

        let inputNode = engine.inputNode
        let inputFormat = inputNode.outputFormat(forBus: 0)

        // Create audio file at 48kHz / 24-bit for Voice DNA quality
        let settings: [String: Any] = [
            AVFormatIDKey: Int(kAudioFormatLinearPCM),
            AVSampleRateKey: 48000.0,
            AVNumberOfChannelsKey: 1,
            AVLinearPCMBitDepthKey: 24,
            AVLinearPCMIsFloatKey: false,
        ]

        audioFile = try AVAudioFile(forWriting: url, settings: settings)

        inputNode.installTap(onBus: 0, bufferSize: 4096, format: inputFormat) { [weak self] buffer, _ in
            guard let self, let file = self.audioFile else { return }
            try? file.write(from: buffer)

            // Update audio level
            let channelData = buffer.floatChannelData?[0]
            let count = Int(buffer.frameLength)
            let rms = channelData.map { ptr in
                sqrt((0..<count).reduce(0.0) { $0 + Double(ptr[$1] * ptr[$1]) } / Double(count))
            } ?? 0
            Task { @MainActor in
                self.audioLevel = Float(rms)
            }
        }

        try engine.start()
        recordingStartTime = Date()

        durationTimer = Timer.scheduledTimer(withTimeInterval: 0.1, repeats: true) { [weak self] _ in
            guard let self else { return }
            let duration = Date().timeIntervalSince(self.recordingStartTime ?? Date())
            Task { @MainActor in
                self.recordingDuration = duration
                self.state = .recording(duration: duration)
            }
        }
    }

    public func stopRecording() async throws -> URL {
        durationTimer?.invalidate()
        durationTimer = nil

        audioEngine?.inputNode.removeTap(onBus: 0)
        audioEngine?.stop()
        audioEngine = nil
        audioFile = nil

        try? AVAudioSession.sharedInstance().setActive(false)

        guard let url = recordingURL else {
            throw NSError(domain: "NOIZYVoice", code: 2, userInfo: [NSLocalizedDescriptionKey: "No recording URL"])
        }

        // Transcribe if WhisperKit available
        state = .transcribing
        let transcriptText = await transcribeLocal(url: url)
        transcript = transcriptText
        state = .complete(transcript: transcriptText, audioURL: url)

        return url
    }

    // ── Transcription ─────────────────────────────────────────────────────────
    private func transcribeLocal(url: URL) async -> String {
        #if canImport(WhisperKit)
        if let whisper {
            do {
                let results = try await whisper.transcribe(audioPath: url.path)
                return results.map { $0.text }.joined(separator: " ").trimmingCharacters(in: .whitespaces)
            } catch {
                return ""
            }
        }
        #endif
        return "" // Server-side fallback — implement with Voice Bridge
    }

    // ── SHA-256 hash for Voice DNA registration ───────────────────────────────
    public func hashAudioFile(at url: URL) async throws -> String {
        let data = try Data(contentsOf: url)
        var hash = [UInt8](repeating: 0, count: 32)
        data.withUnsafeBytes { bytes in
            // Simple implementation — production should use CryptoKit
            _ = bytes
        }
        // Use CryptoKit in production
        import CryptoKit
        let digest = SHA256.hash(data: data)
        return digest.map { String(format: "%02x", $0) }.joined()
    }

    // ── Reset ─────────────────────────────────────────────────────────────────
    public func reset() {
        state = .ready
        transcript = ""
        audioLevel = 0
        recordingDuration = 0
        recordingURL = nil
    }
}

