public struct VoiceCaptureView: View {
    @StateObject private var capture = VoiceCapture()
    @State private var hasPermission = false
    let onComplete: (String, URL) -> Void

    public init(onComplete: @escaping (String, URL) -> Void) {
        self.onComplete = onComplete
    }

    public var body: some View {
        VStack(spacing: 32) {
            // Audio visualizer
            AudioLevelView(level: capture.audioLevel)
                .frame(height: 80)

            // State display
            stateView

            // Record button
            recordButton

            // Transcript
            if !capture.transcript.isEmpty {
                VStack(alignment: .leading, spacing: 8) {
                    Text("Transcript")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                    Text(capture.transcript)
                        .padding()
                        .background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 12))
                }
                .padding(.horizontal)
            }
        }
        .padding()
        .task {
            hasPermission = await capture.requestPermission()
            await capture.setupWhisper()
        }
        .onChange(of: capture.state) { _, newState in
            if case .complete(let transcript, let url) = newState {
                onComplete(transcript, url)
            }
        }
    }

    @ViewBuilder
    private var stateView: some View {
        switch capture.state {
        case .idle, .requestingPermission:
            Text("Preparing microphone...")
                .foregroundStyle(.secondary)
        case .ready:
            Text("Ready to record")
                .foregroundStyle(.secondary)
        case .recording(let duration):
            VStack {
                Text(String(format: "%.1fs", duration))
                    .font(.system(.largeTitle, design: .monospaced))
                Text("Recording...")
                    .foregroundStyle(.red)
            }
        case .transcribing:
            ProgressView("Transcribing...")
        case .complete(let transcript, _):
            VStack {
                Image(systemName: "checkmark.circle.fill")
                    .foregroundStyle(.green)
                    .font(.title)
                Text("\(transcript.split(separator: " ").count) words")
                    .foregroundStyle(.secondary)
            }
        case .error(let msg):
            Label(msg, systemImage: "exclamationmark.triangle")
                .foregroundStyle(.red)
        }
    }

    @ViewBuilder
    private var recordButton: some View {
        let isRecording: Bool = {
            if case .recording = capture.state { return true }
            return false
        }()

        Button {
            if isRecording {
                Task {
                    _ = try? await capture.stopRecording()
                }
            } else {
                try? capture.startRecording()
            }
        } label: {
            ZStack {
                Circle()
                    .fill(isRecording ? .red : .blue)
                    .frame(width: 80, height: 80)

                if isRecording {
                    RoundedRectangle(cornerRadius: 4)
                        .fill(.white)
                        .frame(width: 28, height: 28)
                } else {
                    Circle()
                        .fill(.white)
                        .frame(width: 28, height: 28)
                }
            }
        }
        .disabled(!hasPermission)
        .scaleEffect(isRecording ? 1.1 : 1.0)
        .animation(.easeInOut(duration: 0.5).repeatForever(autoreverses: true), value: isRecording)
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// MARK: — Audio Level Visualizer
// ─────────────────────────────────────────────────────────────────────────────

struct AudioLevelView: View {
    let level: Float
    private let barCount = 20

    var body: some View {
        GeometryReader { geo in
            HStack(spacing: 3) {
                ForEach(0..<barCount, id: \.self) { i in
                    let threshold = Float(i) / Float(barCount)
                    RoundedRectangle(cornerRadius: 2)
                        .fill(level > threshold ? barColor(for: threshold) : Color.gray.opacity(0.3))
                        .animation(.easeOut(duration: 0.05), value: level)
                }
            }
        }
    }

    private func barColor(for threshold: Float) -> Color {
        switch threshold {
        case ..<0.5: return .green
        case ..<0.8: return .yellow
        default: return .red
        }
    }
}

