// TypeScript client for the royalty-router Cloudflare Worker
// Same pattern as consent-sdk

export interface RoyaltySplit {
  royalty_event_id: string;
  creator_id: string;
  gross_amount: number;
  creator_amount: number;
  platform_amount: number;
  creator_pct: number;
  platform_pct: number;
  currency: string;
  payout_status: "pending" | "paid" | "failed";
  payout_due_at: string | null;
  is_founding_rate: boolean;
  override_applied: boolean;
}

export interface RoyaltySummary {
  creator_id: string;
  is_founding: boolean;
  split_law: string;
  total_events: number;
  lifetime_gross: number;
  lifetime_creator: number;
  lifetime_platform: number;
  pending_creator: number;
  paid_creator: number;
}

export class RoyaltyClient {
  private readonly url: string;
  private readonly key: string;
  private readonly timeout: number;

  constructor(config: { routerUrl?: string; apiKey: string; timeout?: number }) {
    this.url = (config.routerUrl ?? "https://royalty-router.noizylab.workers.dev").replace(/\/$/, "");
    this.key = config.apiKey;
    this.timeout = config.timeout ?? 10_000;
  }

  private async req<T>(method: "GET" | "POST", path: string, body?: unknown): Promise<T> {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), this.timeout);
    try {
      const res = await fetch(`${this.url}${path}`, {
        method,
        headers: { "Content-Type": "application/json", "X-NOIZY-Key": this.key },
        body: body ? JSON.stringify(body) : undefined,
        signal: ctrl.signal,
      });
      if (!res.ok) {
        const e = await res.json().catch(() => ({})) as { error?: string };
        throw new Error(e.error ?? `HTTP ${res.status}`);
      }
      return res.json() as Promise<T>;
    } finally {
      clearTimeout(timer);
    }
  }

  async health() {
    return this.req<{ status: string; version: string; split_law: string; total_gross_usd: number }>("GET", "/health");
  }

  async routePayment(params: {
    creator_id: string;
    usage_event_id: string;
    gross_amount: number;
    currency?: string;
  }): Promise<RoyaltySplit> {
    return this.req<RoyaltySplit>("POST", "/v1/route-payment", params);
  }

  async getSplits(creatorId: string, status: "pending" | "paid" | "all" = "pending"): Promise<RoyaltySplit[]> {
    const res = await this.req<{ events: RoyaltySplit[] }>("GET", `/v1/splits/${creatorId}?status=${status}`);
    return res.events;
  }

  async confirmPayout(eventId: string): Promise<{ confirmed: boolean; paid_at: string }> {
    return this.req("POST", `/v1/splits/${eventId}/confirm`, {});
  }

  async getSummary(creatorId: string): Promise<RoyaltySummary> {
    return this.req<RoyaltySummary>("GET", `/v1/summary/${creatorId}`);
  }

  /**
   * Verify creator gets at least 75% (65% with union).
   * Throws if split is below minimum floor.
   */
  static verifySplitLaw(creatorPct: number): void {
    if (creatorPct < 65) {
      throw new Error(`COVENANT VIOLATION: Creator split ${creatorPct}% is below minimum 65%`);
    }
  }
}

export function createRoyaltyClient(env?: { ROYALTY_ROUTER_URL?: string; NOIZY_API_KEY?: string }): RoyaltyClient {
  const routerUrl = env?.ROYALTY_ROUTER_URL ?? process.env.ROYALTY_ROUTER_URL;
  const apiKey = env?.NOIZY_API_KEY ?? process.env.NOIZY_API_KEY ?? "";
  if (!apiKey) throw new Error("NOIZY_API_KEY required");
  return new RoyaltyClient({ routerUrl, apiKey });
}

// index.ts — @noizybeast/proof-sdk
// TypeScript client for the proof-manifest Cloudflare Worker

export interface ManifestResult {
  manifest_id: string;
  output_asset_id: string;
  manifest_hash: string;
  provenance_status: "signed" | "pending" | "failed";
  manifest: C2PAManifest;
  created_at: string;
}

export interface C2PAManifest {
  "@context": string;
  claim_generator: string;
  claim_generator_version: string;
  title: string;
  format: string;
  instance_id: string;
  created_at: string;
  assertions: Array<{ label: string; data: Record<string, unknown> }>;
  ingredients: Array<{ title: string; relationship: string; actor_id: string; consent_token_id: string }>;
  signature: { issuer: string; date: string; algorithm: string; manifest_hash: string };
}

export interface VerificationResult {
  manifest_id: string;
  verification_status: "verified" | "failed";
  provenance_status: string;
  creator_id: string;
  consent_token_id: string;
  manifest_hash: string;
  verified_at: string;
  c2pa_compliant: boolean;
  never_clauses_checked: boolean;
  consent_verified: boolean;
}

export class ProofClient {
  private readonly url: string;
  private readonly key: string;

  constructor(config: { manifestUrl?: string; apiKey: string }) {
    this.url = (config.manifestUrl ?? "https://proof-manifest.noizylab.workers.dev").replace(/\/$/, "");
    this.key = config.apiKey;
  }

  private async req<T>(method: "GET" | "POST", path: string, body?: unknown): Promise<T> {
    const res = await fetch(`${this.url}${path}`, {
      method,
      headers: { "Content-Type": "application/json", "X-NOIZY-Key": this.key },
      body: body ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`Proof manifest error: HTTP ${res.status}`);
    return res.json() as Promise<T>;
  }

  async health() {
    return this.req<{ status: string; version: string; total_manifests: number }>("GET", "/health");
  }

  async createManifest(params: {
    output_asset_id: string;
    creator_id: string;
    consent_token_id: string;
    synth_request_id: string;
    tool_name: string;
    use_category: string;
    script_hash?: string;
  }): Promise<ManifestResult> {
    return this.req<ManifestResult>("POST", "/v1/manifests", params);
  }

  async verifyManifest(manifestId: string): Promise<VerificationResult> {
    return this.req<VerificationResult>("POST", `/v1/manifests/${manifestId}/verify`, {});
  }

  async getManifestForAsset(assetId: string): Promise<ManifestResult> {
    return this.req<{ manifest_record: ManifestResult }>("GET", `/v1/manifests/asset/${assetId}`)
      .then(r => r.manifest_record);
  }

  /**
   * Full pipeline: create manifest + verify in one call.
   * Returns verified manifest or throws.
   */
  async createAndVerify(params: Parameters<typeof this.createManifest>[0]): Promise<{
    manifest: ManifestResult;
    verification: VerificationResult;
  }> {
    const manifest = await this.createManifest(params);
    const verification = await this.verifyManifest(manifest.manifest_id);
    if (verification.verification_status !== "verified") {
      throw new Error("Manifest verification failed — provenance chain broken");
    }
    return { manifest, verification };
  }
}

export function createProofClient(env?: { PROOF_MANIFEST_URL?: string; NOIZY_API_KEY?: string }): ProofClient {
  return new ProofClient({
    manifestUrl: env?.PROOF_MANIFEST_URL ?? process.env.PROOF_MANIFEST_URL,
    apiKey: env?.NOIZY_API_KEY ?? process.env.NOIZY_API_KEY ?? "",
  });
}

