  // Health
  async health() {
    return this.req<{ status: string; version: string; actors: number; ledger_events: number }>("GET", "/health");
  }

  // Actors
  async getActor(actorId: string): Promise<HVSActor> {
    return this.req<{ actor: HVSActor }>("GET", `/api/v1/actors/${actorId}`).then(r => r.actor);
  }

  async createActor(params: {
    actor_id: string; display_name: string; legal_name?: string;
    email?: string; country?: string; is_founding?: boolean;
  }): Promise<HVSActor> {
    return this.req<{ actor: HVSActor }>("POST", "/api/v1/actors", params).then(r => r.actor);
  }

  // Consent Tokens
  async issueConsentToken(params: {
    actor_id: string; use_categories: string[];
    territories?: string[]; languages?: string[]; expires_at?: string;
  }): Promise<HVSConsentToken> {
    return this.req<{ consent_token: HVSConsentToken }>("POST", "/api/v1/consent-tokens", {
      territories: ["GLOBAL"], languages: ["en"], ...params,
    }).then(r => r.consent_token);
  }

  async revokeConsentToken(tokenId: string, reason: string): Promise<{ status: string; message: string; revoked_at: string }> {
    return this.req("POST", `/api/v1/consent-tokens/${tokenId}/revoke`, { reason });
  }

  // Kill Switch — instant revocation, logged, permanent
  async killSwitch(tokenId: string, reason: string = "Creator activated kill switch"): Promise<void> {
    await this.revokeConsentToken(tokenId, reason);
  }

  // Synth Requests (Never Clause enforced server-side)
  async requestSynthesis(params: {
    actor_id: string; descendant_id: string; consent_token_id: string;
    use_category: string; script_hash?: string;
  }): Promise<HVSSynthResult> {
    return this.req<HVSSynthResult>("POST", "/api/v1/synth-requests", params);
  }

  // Voice DNA
  async registerVoiceDNA(actorId: string, params: {
    dna_id: string; recording_hash: string; duration_seconds: number;
    sample_rate?: number; metadata?: Record<string, unknown>;
  }): Promise<{ success: boolean; dna_id: string; registered_at: string }> {
    return this.req("POST", `/api/v1/actors/${actorId}/voice-dna`, {
      sample_rate: 48000, ...params,
    });
  }

  // Never Clauses
  async getNeverClauses(): Promise<HVSNeverClause[]> {
    return this.req<{ never_clauses: HVSNeverClause[] }>("GET", "/api/v1/never-clauses").then(r => r.never_clauses);
  }

  // Ledger
  async getLedger(actorId?: string, limit = 20): Promise<Record<string, unknown>[]> {
    const path = `/api/v1/ledger?limit=${limit}${actorId ? `&actor_id=${actorId}` : ""}`;
    return this.req<{ events: Record<string, unknown>[] }>("GET", path).then(r => r.events ?? []);
  }
}

export class HVSError extends Error {
  constructor(message: string, public readonly statusCode: number) {
    super(message);
    this.name = "HVSError";
  }
}

export function createHVSClient(env?: { HEAVEN17_URL?: string; NOIZY_API_KEY?: string }): HVSClient {
  return new HVSClient({
    heaven17URL: env?.HEAVEN17_URL ?? process.env.HEAVEN17_URL,
    apiKey: env?.NOIZY_API_KEY ?? process.env.NOIZY_API_KEY ?? "",
  });
}

// src/index.js — Beast Core v2.0
// Core orchestration layer for the NOIZYBEAST monorepo
// Entry point: coordinates all packages and workers

import { createConsentClient } from "@noizybeast/consent-sdk";
import { createRoyaltyClient } from "@noizybeast/royalty-sdk";
import { createProofClient } from "@noizybeast/proof-sdk";
import { createHVSClient } from "@noizybeast/hvs-sdk";

// ─────────────────────────────────────────────────────────────────────────────
// BEAST CORE — The unified pipeline
// ─────────────────────────────────────────────────────────────────────────────

export class BeastCore {
  constructor(config = {}) {
    const apiKey = config.apiKey ?? process.env.NOIZY_API_KEY ?? "";
    if (!apiKey) console.warn("[BEAST] NOIZY_API_KEY not set — most operations will fail");

    this.hvs      = createHVSClient({ ...config, NOIZY_API_KEY: apiKey });
    this.consent  = createConsentClient({ ...config, NOIZY_API_KEY: apiKey });
    this.royalty  = createRoyaltyClient({ ...config, NOIZY_API_KEY: apiKey });
    this.proof    = createProofClient({ ...config, NOIZY_API_KEY: apiKey });
    this.actorId  = config.actorId ?? "RSP_001";
    this.apiKey   = apiKey;
  }

  // ── Full pipeline: consent → synth → royalty → proof ──────────────────────
  async pipeline(params) {
    const {
      actorId = this.actorId,
      descendantId,
      useCategory,
      scriptHash,
      toolName = "noizybeast",
      grossAmount = 0,
      currency = "USD",
    } = params;

    const results = { actorId, useCategory, steps: [] };

    // 1. Check consent
    const eligibility = await this.consent.checkEligibility({
      creator_id: actorId,
      claimant_id: "NOIZYBEAST_PIPELINE",
      action_type: useCategory,
      tool_name: toolName,
      requested_scope: { territory: "global" },
      requested_at: new Date().toISOString(),
    });
    results.steps.push({ step: "consent", decision: eligibility.decision });
    if (eligibility.decision !== "ALLOW") {
      results.blocked = true;
      results.reason = eligibility.reason_codes?.[0];
      return results;
    }

    // 2. Request synthesis
    if (descendantId && eligibility.consent_record_id) {
      const synth = await this.hvs.requestSynthesis({
        actor_id: actorId,
        descendant_id: descendantId,
        consent_token_id: eligibility.consent_record_id,
        use_category: useCategory,
        script_hash: scriptHash ?? "pipeline_auto",
      });
      results.steps.push({ step: "synthesis", status: synth.status });
      results.synthRequestId = synth.request_id;
      if (synth.status !== "approved") {
        results.blocked = true;
        results.reason = synth.blocked_by ?? synth.message;
        return results;
      }
    }

    // 3. Route royalty
    if (grossAmount > 0) {
      const royalty = await this.royalty.routePayment({
        creator_id: actorId,
        usage_event_id: results.synthRequestId ?? `EVT-${Date.now()}`,
        gross_amount: grossAmount,
        currency,
      });
      results.steps.push({
        step: "royalty",
        creatorAmount: royalty.creator_amount,
        platformAmount: royalty.platform_amount,
        creatorPct: royalty.creator_pct,
      });
      results.royaltyEventId = royalty.royalty_event_id;
    }

    // 4. Create provenance manifest
    const assetId = `ASSET-${Date.now()}-${actorId}`;
    const manifest = await this.proof.createManifest({
      output_asset_id: assetId,
      creator_id: actorId,
      consent_token_id: eligibility.consent_record_id ?? "none",
      synth_request_id: results.synthRequestId ?? "none",
      tool_name: toolName,
      use_category: useCategory,
      script_hash: scriptHash,
    });
    results.steps.push({ step: "proof", manifestHash: manifest.manifest_hash });
    results.manifestId = manifest.manifest_id;
    results.manifestHash = manifest.manifest_hash;
    results.assetId = assetId;

    results.success = true;
    return results;
  }

  // ── Audit: check all systems ───────────────────────────────────────────────
  async audit() {
    const checks = {};

    try {
      const health = await this.hvs.health();
      checks.heaven17 = { status: health.status, actors: health.actors };
    } catch (e) {
      checks.heaven17 = { status: "ERROR", error: e.message };
    }

    try {
      const rh = await this.royalty.health();
      checks.royaltyRouter = { status: rh.status };
    } catch (e) {
      checks.royaltyRouter = { status: "ERROR", error: e.message };
    }

    try {
      const ph = await this.proof.health();
      checks.proofManifest = { status: ph.status, manifests: ph.total_manifests };
    } catch (e) {
      checks.proofManifest = { status: "ERROR", error: e.message };
    }

    const allLive = Object.values(checks).every(c => c.status === "LIVE" || c.status === "OK");
    return {
      timestamp: new Date().toISOString(),
      overall: allLive ? "ALL_SYSTEMS_LIVE" : "DEGRADED",
      checks,
    };
  }

  // ── Kill switch ────────────────────────────────────────────────────────────
  async killSwitch(tokenId, reason = "Kill switch activated via BeastCore") {
    return this.hvs.killSwitch(tokenId, reason);
  }
}

export { createConsentClient, createRoyaltyClient, createProofClient, createHVSClient };

// Convenience factory
export function createBeastCore(config = {}) {
  return new BeastCore(config);
}

