import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { CallToolRequestSchema, ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";

const DREAMCHAMBER_URL = process.env.DREAMCHAMBER_URL || "http://localhost:7777";
const HEAVEN17_URL = process.env.HEAVEN17_URL || "https://heaven17.rsplowman.workers.dev";
const GABRIEL_RUNTIME_URL = process.env.GABRIEL_RUNTIME_URL || "https://gabriel-runtime.noizylab.workers.dev";
const NOIZY_API_KEY = process.env.NOIZY_API_KEY || "";
const TIMEOUT = 30000;

async function dc(method, path, body = null) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), TIMEOUT);
  try {
    const opts = { method, headers: { "Content-Type": "application/json" }, signal: ctrl.signal };
    if (body) opts.body = JSON.stringify(body);
    const res = await fetch(`${DREAMCHAMBER_URL}${path}`, opts);
    if (!res.ok) throw new Error(`DreamChamber ${method} ${path} → ${res.status}`);
    return res.json();
  } finally { clearTimeout(t); }
}

async function h17(path, method = "GET", body = null) {
  const headers = { "Content-Type": "application/json" };
  if (NOIZY_API_KEY) headers["X-NOIZY-Key"] = NOIZY_API_KEY;
  const opts = { method, headers };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(`${HEAVEN17_URL}${path}`, opts);
  if (!res.ok) throw new Error(`Heaven17 ${method} ${path} → ${res.status}`);
  return res.json();
}

async function gabriel_rt(path, method = "GET", body = null) {
  const headers = { "Content-Type": "application/json" };
  if (NOIZY_API_KEY) headers["X-NOIZY-Key"] = NOIZY_API_KEY;
  const opts = { method, headers };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(`${GABRIEL_RUNTIME_URL}${path}`, opts);
  if (!res.ok) throw new Error(`gabriel-runtime ${method} ${path} → ${res.status}`);
  return res.json();
}

function req(val, name, max = 10000) {
  if (typeof val !== "string" || !val.trim()) throw new Error(`${name} required`);
  if (val.length > max) throw new Error(`${name} exceeds ${max} chars`);
  return val.trim();
}

const server = new Server({ name: "gabriel-mcp", version: "2.0.0" }, { capabilities: { tools: {} } });

server.setRequestHandler(ListToolsRequestSchema, async () => ({
