        return { content: [{ type: "text", text:
          `**Dispatched → ${result.agent}**\nTask ID: \`${result.task_id}\`\nStatus: ${result.status}\nPriority: ${result.priority}\nNote: ${result.note ?? "queued"}`
        }]};
      }

      case "gabriel_audit": {
        const [h17Health, rtHealth] = await Promise.allSettled([
          h17("/health"),
          gabriel_rt("/health"),
        ]);
        const hh = h17Health.status === "fulfilled" ? h17Health.value : null;
        const rh = rtHealth.status === "fulfilled" ? rtHealth.value : null;
        const lines = [
