          ``,
          `**Workers**`,
          `heaven17: ${hh?.status ?? "ERROR"} — actors: ${hh?.actors ?? "?"} — ledger: ${hh?.ledger_events ?? "?"}`,
          `gabriel-runtime: ${rh?.status ?? "ERROR"} — dispatches: ${rh?.total_dispatches ?? "?"}`,
          `consent-gateway: CODED — pending CF auth`,
          `royalty-router: CODED — pending CF auth`,
          `proof-manifest: CODED — pending CF auth`,
          ``,
          `**Blockers**`,
          `🔴 B1: ANTHROPIC_API_KEY empty on GOD.local → blocks GABRIEL`,
          `🔴 B3: R2 bucket noizy-voice-archive not created`,
          `🟡 B4: CF API token conflict → blocks all deploys`,
          `🟡 B5: NOIZY_API_KEY secret not set on consent-gateway`,
          ``,
          `**Overall**`,
          `Coded: 100% | Deployed: 30%`,
          `Run \`wrangler login\` to fix B4 and unblock all 4 deploys`,
        ];
        return { content: [{ type: "text", text: lines.join("\n") }] };
      }

      case "gabriel_kill_switch": {
        const tokenId = req(args.token_id, "token_id");
        const reason = req(args.reason, "reason");
        const result = await h17(`/api/v1/consent-tokens/${tokenId}/revoke`, "POST", { reason });
        return { content: [{ type: "text", text:
          `⚠️ **KILL SWITCH ACTIVATED**\nToken: ${tokenId}\nStatus: ${result.status}\nRevoked at: ${result.revoked_at}\nMessage: ${result.message}`
        }]};
      }

      default:
        throw new Error(`Unknown tool: ${name}`);
    }
  } catch (err) {
    return { content: [{ type: "text", text: `**Error:** ${err.message}` }], isError: true };
  }
});

const transport = new StdioServerTransport();
await server.connect(transport);

