// TypeScript client for the full Human Voice System (Heaven17 Worker)
// Wraps all 24+ routes with typed methods

export interface HVSActor {
  actor_id: string;
  display_name: string;
  legal_name: string | null;
  email: string | null;
  country: string;
  is_founding: number;
  union_member: number;
  status: string;
  onboarded_at: string;
}

