  territories: string;
  languages: string;
  status: "active" | "revoked" | "expired";
  issued_at: string;
  expires_at: string | null;
  revoked_at: string | null;
}

export interface HVSSynthResult {
  status: "approved" | "blocked" | "denied";
  request_id: string;
  never_clause_check?: string;
  blocked_by?: string;
  message: string;
}

