import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { CallToolRequestSchema, ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";

const DREAMCHAMBER_URL = process.env.DREAMCHAMBER_URL || "http://localhost:7777";
const HEAVEN17_URL = process.env.HEAVEN17_URL || "https://heaven17.rsplowman.workers.dev";
const GABRIEL_RUNTIME_URL = process.env.GABRIEL_RUNTIME_URL || "https://gabriel-runtime.noizylab.workers.dev";
const NOIZY_API_KEY = process.env.NOIZY_API_KEY || "";
const TIMEOUT = 30000;

async function dc(method, path, body = null) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), TIMEOUT);
  try {
    const opts = { method, headers: { "Content-Type": "application/json" }, signal: ctrl.signal };
    if (body) opts.body = JSON.stringify(body);
    const res = await fetch(`${DREAMCHAMBER_URL}${path}`, opts);
    if (!res.ok) throw new Error(`DreamChamber ${method} ${path} → ${res.status}`);
    return res.json();
  } finally { clearTimeout(t); }
}

async function h17(path, method = "GET", body = null) {
  const headers = { "Content-Type": "application/json" };
  if (NOIZY_API_KEY) headers["X-NOIZY-Key"] = NOIZY_API_KEY;
  const opts = { method, headers };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(`${HEAVEN17_URL}${path}`, opts);
  if (!res.ok) throw new Error(`Heaven17 ${method} ${path} → ${res.status}`);
  return res.json();
}

async function gabriel_rt(path, method = "GET", body = null) {
  const headers = { "Content-Type": "application/json" };
  if (NOIZY_API_KEY) headers["X-NOIZY-Key"] = NOIZY_API_KEY;
  const opts = { method, headers };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(`${GABRIEL_RUNTIME_URL}${path}`, opts);
  if (!res.ok) throw new Error(`gabriel-runtime ${method} ${path} → ${res.status}`);
  return res.json();
}

function req(val, name, max = 10000) {
  if (typeof val !== "string" || !val.trim()) throw new Error(`${name} required`);
  if (val.length > max) throw new Error(`${name} exceeds ${max} chars`);
  return val.trim();
}

const server = new Server({ name: "gabriel-mcp", version: "2.0.0" }, { capabilities: { tools: {} } });

server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: [
    {
      name: "gabriel_speak",
      description: "Chat with GABRIEL — warrior executor of the NOIZY Empire. Grounded in live Heaven17 consent kernel state. Use for: architecture decisions, consent questions, empire doctrine, build guidance.",
      inputSchema: { type: "object", required: ["input"], properties: {
        input: { type: "string", description: "Your message or question to GABRIEL" },
        model: { type: "string", description: "Override AI model (e.g. claude-opus-4)" },
        voice: { type: "boolean", description: "Speak via macOS TTS (default: false)" },
      }},
    },
    {
      name: "gabriel_status",
      description: "Full GABRIEL ensemble status: kernel health, context age, all agent states, blockers, runtime truth.",
      inputSchema: { type: "object", properties: {} },
    },
    {
      name: "gabriel_announce",
      description: "Speak text aloud via macOS TTS (GABRIEL voice). No AI — pure announcement.",
      inputSchema: { type: "object", required: ["text"], properties: {
        text: { type: "string", description: "Text to announce" },
      }},
    },
    {
      name: "gabriel_refresh",
      description: "Force GABRIEL to refresh live context from Heaven17 consent kernel.",
      inputSchema: { type: "object", properties: {} },
    },
    {
      name: "gabriel_dispatch",
      description: "Dispatch a task to a specific named agent: GABRIEL, LUCY, ENGR_KEITH, SHIRLEY, CB01, DREAM, AUDIO.",
      inputSchema: { type: "object", required: ["agent", "task", "input"], properties: {
        agent: { type: "string", enum: ["GABRIEL","LUCY","ENGR_KEITH","SHIRLEY","CB01","DREAM","AUDIO"] },
        task: { type: "string", description: "Task name" },
        input: { type: "string", description: "Task input/description" },
        priority: { type: "string", enum: ["critical","high","normal","low"], description: "Task priority (default: normal)" },
        dry_run: { type: "boolean", description: "Plan only — no execution" },
      }},
    },
    {
      name: "gabriel_audit",
      description: "Run full empire runtime truth audit: all workers health, all agents status, all blockers. Returns honest system state.",
      inputSchema: { type: "object", properties: {} },
    },
    {
      name: "gabriel_kill_switch",
      description: "⚠️ EMERGENCY: Revoke a consent token immediately via kill switch. Logged permanently. Irreversible.",
      inputSchema: { type: "object", required: ["token_id", "reason"], properties: {
        token_id: { type: "string", description: "Consent token ID to revoke" },
        reason: { type: "string", description: "Reason for revocation" },
      }},
    },
  ],
}));

server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params;

  try {
    switch (name) {

      case "gabriel_speak": {
        const result = await dc("POST", "/api/gabriel/speak", {
          input: req(args.input, "input"),
          model: args.model,
          voice: args.voice ?? false,
        });
        return { content: [{ type: "text", text:
          `**GABRIEL v2.0:** ${result.gabriel}\n\n*Model: ${result.metadata?.model || "?"} | Kernel: ${result.context?.kernelOnline ? "ONLINE ✓" : "OFFLINE ✗"} | Tokens: ${result.metadata?.tokens?.total ?? "?"} | v2.0.0*`
        }]};
      }

      case "gabriel_status": {
        const [status, health] = await Promise.allSettled([
          dc("GET", "/api/gabriel/status"),
          h17("/health"),
        ]);
        const s = status.status === "fulfilled" ? status.value : {};
        const h = health.status === "fulfilled" ? health.value : {};
        const lines = [
          `**GABRIEL v2.0 — FULL STATUS**`,
          ``,
          `**Core**`,
          `GABRIEL online: ${s.online ? "✓" : "✗"}`,
          `Provider ready: ${s.providerReady ? "✓" : "✗"}`,
          `Model: ${s.model ?? "?"}`,
          `Context age: ${s.contextAge != null ? s.contextAge + "s" : "never loaded"}`,
          ``,
          `**Heaven17 Kernel**`,
          `Status: ${h.status ?? "unreachable"}`,
          `Actors: ${h.actors ?? "?"}`,
          `Ledger events: ${h.ledger_events ?? "?"}`,
          ``,
          `**Agents**`,
          `GABRIEL: ACTIVE | LUCY: ACTIVE | ENGR_KEITH: ACTIVE`,
          `SHIRLEY: ACTIVE | CB01: ACTIVE | DREAM: ACTIVE | AUDIO: ACTIVE`,
          ``,
          `**Blockers**`,
          `B1: ANTHROPIC_API_KEY empty on GOD.local`,
          `B3: R2 bucket not created`,
          `B4: CF API token conflict`,
          `B5: NOIZY_API_KEY secret not set`,
        ];
        return { content: [{ type: "text", text: lines.join("\n") }] };
      }

      case "gabriel_announce": {
        await dc("POST", "/api/gabriel/announce", { text: req(args.text, "text", 5000) });
        return { content: [{ type: "text", text: `✓ Announced: "${args.text}"` }] };
      }

      case "gabriel_refresh": {
        const result = await dc("POST", "/api/gabriel/refresh");
        return { content: [{ type: "text", text:
          `✓ Context refreshed\nKernel: ${result.context?.kernelOnline ? "ONLINE ✓" : "OFFLINE ✗"}\nAt: ${result.context?.refreshedAt}`
        }]};
      }

      case "gabriel_dispatch": {
        const result = await gabriel_rt("/v1/dispatch", "POST", {
          agent: req(args.agent, "agent"),
          task: req(args.task, "task"),
          input: req(args.input, "input"),
          priority: args.priority ?? "normal",
          dry_run: args.dry_run ?? false,
        });
        return { content: [{ type: "text", text:
          `**Dispatched → ${result.agent}**\nTask ID: \`${result.task_id}\`\nStatus: ${result.status}\nPriority: ${result.priority}\nNote: ${result.note ?? "queued"}`
        }]};
      }

      case "gabriel_audit": {
        const [h17Health, rtHealth] = await Promise.allSettled([
          h17("/health"),
          gabriel_rt("/health"),
        ]);
        const hh = h17Health.status === "fulfilled" ? h17Health.value : null;
        const rh = rtHealth.status === "fulfilled" ? rtHealth.value : null;
        const lines = [
          `**GABRIEL AUDIT — ${new Date().toISOString()}**`,
          ``,
          `**Workers**`,
          `heaven17: ${hh?.status ?? "ERROR"} — actors: ${hh?.actors ?? "?"} — ledger: ${hh?.ledger_events ?? "?"}`,
          `gabriel-runtime: ${rh?.status ?? "ERROR"} — dispatches: ${rh?.total_dispatches ?? "?"}`,
          `consent-gateway: CODED — pending CF auth`,
          `royalty-router: CODED — pending CF auth`,
          `proof-manifest: CODED — pending CF auth`,
          ``,
          `**Blockers**`,
          `🔴 B1: ANTHROPIC_API_KEY empty on GOD.local → blocks GABRIEL`,
          `🔴 B3: R2 bucket noizy-voice-archive not created`,
          `🟡 B4: CF API token conflict → blocks all deploys`,
          `🟡 B5: NOIZY_API_KEY secret not set on consent-gateway`,
          ``,
          `**Overall**`,
          `Coded: 100% | Deployed: 30%`,
          `Run \`wrangler login\` to fix B4 and unblock all 4 deploys`,
        ];
        return { content: [{ type: "text", text: lines.join("\n") }] };
      }

      case "gabriel_kill_switch": {
        const tokenId = req(args.token_id, "token_id");
        const reason = req(args.reason, "reason");
        const result = await h17(`/api/v1/consent-tokens/${tokenId}/revoke`, "POST", { reason });
        return { content: [{ type: "text", text:
          `⚠️ **KILL SWITCH ACTIVATED**\nToken: ${tokenId}\nStatus: ${result.status}\nRevoked at: ${result.revoked_at}\nMessage: ${result.message}`
        }]};
      }

      default:
        throw new Error(`Unknown tool: ${name}`);
    }
  } catch (err) {
    return { content: [{ type: "text", text: `**Error:** ${err.message}` }], isError: true };
  }
});

const transport = new StdioServerTransport();
await server.connect(transport);

