#!/usr/bin/env python3
"""Read-only NOIZY eligibility indexer.

Creates CSV and JSONL manifests. It never moves, renames, deletes, or follows symlinks.
"""
from __future__ import annotations

import csv
import hashlib
import json
import os
from collections import defaultdict
from datetime import datetime, timezone
from pathlib import Path

SOURCE_ROOTS = [
    Path("/Users/m2ultra/NOIZYANTHROPIC"),
    Path("/Users/m2ultra/Library/CloudStorage/GoogleDrive-rspplowman@gmail.com/My Drive"),
]
OUTPUT_ROOT = Path("/Users/m2ultra/Library/CloudStorage/GoogleDrive-rspplowman@gmail.com/My Drive/output")
DESTINATION_ROOT = Path("/Users/m2ultra/Library/CloudStorage/GoogleDrive-rspplowman@gmail.com/My Drive/NOIZY_MASTER")

EXCLUDED_PARTS = {
    ".git", ".gitmodules", "node_modules", "venv", ".venv", "packages",
    ".cursor", ".vscode", "__pycache__", ".next", "build", "dist",
}
EXCLUDED_SUFFIXES = {".pem", ".key", ".p12", ".pfx"}
EXCLUDED_NAMES = {".env", ".env.local", "credentials.json", "service-account.json"}


def md5_file(path: Path, chunk_size: int = 1024 * 1024) -> str:
    digest = hashlib.md5()
    with path.open("rb") as stream:
        while chunk := stream.read(chunk_size):
            digest.update(chunk)
    return digest.hexdigest()


def exclusion_reason(path: Path) -> str | None:
    if path.is_symlink():
        return "symlink_not_traversed"
    if DESTINATION_ROOT == path or DESTINATION_ROOT in path.parents:
        return "destination_excluded"
    if any(part in EXCLUDED_PARTS for part in path.parts):
        return "protected_runtime_or_dependency_path"
    if path.name in EXCLUDED_NAMES:
        return "credential_or_environment_file"
    if path.suffix.lower() in EXCLUDED_SUFFIXES:
        return "private_key_or_certificate"
    return None


def labels_for(path: Path) -> dict[str, str]:
    text = str(path).lower()
    family = "UNASSIGNED_REVIEW"
    for candidate in ("gabriel alameida", "gabriel", "lucy cortez", "lucy", "shiley marie", "pops plowman", "dream", "engr_keith"):
        if candidate in text:
            family = candidate.upper().replace("_", " ")
            break
    brand = next((x for x in ("noizyfish", "noizylab", "noizykids", "noizyvox", "myfamily.ai", "oxygen.io") if x in text), "UNASSIGNED_REVIEW")
    workspace = next((x for x in ("the-gathering", "the-dreamchamber") if x in text), "UNASSIGNED_REVIEW")
    function = "DOCUMENTATION"
    if path.suffix.lower() in {".wav", ".mp3", ".aiff", ".flac", ".mp4", ".mov", ".m4v"}:
        function = "MEDIA_MASTERS"
    elif path.suffix.lower() in {".py", ".js", ".ts", ".tsx", ".jsx", ".swift", ".sh"}:
        function = "CODE_AND_RUNTIME"
    elif "prompt" in text or "template" in text:
        function = "PROMPTS_TEMPLATES"
    state = "ARCHIVE" if any(x in text for x in ("archive", "backup", "snapshot", "copy", "fork")) else "ACTIVE"
    confidence = "confirmed" if family != "UNASSIGNED_REVIEW" or brand != "UNASSIGNED_REVIEW" or workspace != "UNASSIGNED_REVIEW" else "ambiguous"
    return {"family_agent": family, "brand_product": brand, "workspace_project": workspace, "function": function, "state": state, "confidence": confidence}


def main() -> None:
    records: list[dict[str, object]] = []
    for root in SOURCE_ROOTS:
        if not root.exists():
            continue
        for current, directories, filenames in os.walk(root, followlinks=False):
            current_path = Path(current)
            directories[:] = [d for d in directories if exclusion_reason(current_path / d) is None]
            for filename in filenames:
                path = current_path / filename
                reason = exclusion_reason(path)
                record: dict[str, object] = {
                    "path": str(path), "source_root": str(root),
                    "relative_path": str(path.relative_to(root)), "name": path.name,
                    "extension": path.suffix.lower(), "eligible": reason is None,
                    "exclusion_reason": reason,
                }
                if reason is None and path.is_file():
                    stat = path.stat()
                    record.update({"size_bytes": stat.st_size, "modified_time": datetime.fromtimestamp(stat.st_mtime, timezone.utc).isoformat(), "md5": md5_file(path)})
                    record.update(labels_for(path))
                records.append(record)
    groups: defaultdict[str, list[dict[str, object]]] = defaultdict(list)
    for record in records:
        if record.get("eligible") and record.get("md5"):
            groups[str(record["md5"])].append(record)
    for record in records:
        record["duplicate_status"] = "duplicate" if len(groups[str(record.get("md5"))]) > 1 else "unique" if record.get("md5") else "not_checked"
    OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    jsonl_path = OUTPUT_ROOT / f"NOIZY_INDEX_{stamp}.jsonl"
    csv_path = OUTPUT_ROOT / f"NOIZY_INDEX_{stamp}.csv"
    with jsonl_path.open("w", encoding="utf-8") as stream:
        for record in records:
            stream.write(json.dumps(record, ensure_ascii=False) + "\n")
    columns = sorted({key for record in records for key in record})
    with csv_path.open("w", newline="", encoding="utf-8") as stream:
        writer = csv.DictWriter(stream, fieldnames=columns)
        writer.writeheader()
        writer.writerows(records)
    print(json.dumps({"records": len(records), "jsonl": str(jsonl_path), "csv": str(csv_path)}, indent=2))


if __name__ == "__main__":
    main()

